const MUTATION_SCALE = {
  size: 0.09, bodyLength: 0.11, bodyWidth: 0.1, bodyHeight: 0.1, neckLength: 0.12, headSize: 0.1,
  snoutLength: 0.12, eyeSize: 0.1, legLength: 0.11, legThickness: 0.1, armLength: 0.12,
  tailLength: 0.12, wingSpan: 0.1, hornSize: 0.12, spikeSize: 0.12, armor: 0.1,
  clawSize: 0.12, teethSize: 0.1, jawSize: 0.1, hue1: 6, hue2: 7, saturation: 4, lightness: 4,
  speed: 0.055, strength: 0.055, agility: 0.055, intelligence: 0.045, metabolism: 0.05,
  fertility: 0.05, lifespan: 0.05, senseRange: 0.05, fearfulness: 0.06, boldness: 0.06,
  aggression: 0.06, sociability: 0.06
};

function gauss(rng) { return (rng() + rng() + rng() - 1.5) / 1.5; }

export function mutateGenome(parent, rng = Math.random, intensity = 1, pressures = {}) {
  const g = { ...parent };
  const pressureKeys = Object.keys(pressures);
  for (const [key, [min, max]] of Object.entries(GENE_RANGES)) {
    if (key === 'pattern' || key === 'texture') continue;
    let amount = MUTATION_SCALE[key] || 0.05;
    let bias = 0;
    if (pressures.cold) {
      if (key === 'size' || key === 'bodyHeight') bias += 0.12;
      if (key === 'metabolism') bias -= 0.05;
    }
    if (pressures.predators) {
      if (key === 'armor' || key === 'speed' || key === 'legLength' || key === 'senseRange') bias += 0.12;
      if (key === 'size') bias += 0.04;
    }
    if (pressures.scarcity) {
      if (key === 'metabolism') bias -= 0.14;
      if (key === 'size') bias -= 0.06;
      if (key === 'fertility') bias += 0.05;
    }
    if (pressures.arid) {
      if (key === 'bodyHeight') bias -= 0.04;
      if (key === 'legLength') bias += 0.08;
      if (key === 'metabolism') bias -= 0.05;
    }
    if (pressures.competition) {
      if (key === 'strength' || key === 'aggression' || key === 'teethSize') bias += 0.1;
      if (key === 'size') bias += 0.05;
    }
    g[key] = clamp(g[key] + gauss(rng) * amount * intensity + bias * intensity * (max - min) * 0.35, min, max);
  }
  if (chance(rng, 0.06 * intensity)) g.pattern = pick(rng, [0, 1, 2, 3, 4]);
  if (chance(rng, 0.045 * intensity)) g.texture = pick(rng, [0, 1, 2, 3]);
  if (chance(rng, 0.07 * intensity)) g.diet = mutateDiet(g.diet, rng);
  if (chance(rng, 0.035 * intensity) && pressureKeys.length) {
    if (pressures.predators && chance(rng, 0.5)) g.diet = 'carnivore';
    if (pressures.scarcity && chance(rng, 0.45)) g.diet = 'omnivore';
  }
  g.id = 'g' + Math.floor(rng() * 1e9).toString(36);
  return normalizeGenome(g);
}

function mutateDiet(diet, rng) {
  const near = { herbivore: ['herbivore', 'omnivore'], carnivore: ['carnivore', 'omnivore', 'scavenger'], omnivore: ['omnivore', 'herbivore', 'carnivore', 'scavenger'], scavenger: ['scavenger', 'carnivore', 'omnivore'] };
  return pick(rng, near[diet] || DIETS);
}

export function crossoverGenome(a, b, rng = Math.random, mutation = 0.45) {
  const child = {};
  for (const key of Object.keys(GENE_RANGES)) {
    const va = a[key], vb = b[key];
    child[key] = chance(rng, 0.5) ? va : vb;
    if (typeof va === 'number' && key !== 'pattern' && key !== 'texture' && key !== 'legCount') {
      child[key] = lerp(va, vb, rng());
    }
  }
  child.diet = chance(rng, 0.5) ? a.diet : b.diet;
  child.seed = Math.floor(rng() * 1e9);
  child.id = 'g' + Math.floor(rng() * 1e9).toString(36);
  return mutation > 0 ? mutateGenome(child, rng, mutation) : normalizeGenome(child);
}

export function geneticDistance(a, b) {
  let sum = 0;
  const keys = ['size', 'bodyLength', 'bodyWidth', 'bodyHeight', 'neckLength', 'headSize', 'snoutLength', 'legLength', 'legThickness', 'tailLength', 'wingSpan', 'hornSize', 'armor', 'clawSize', 'teethSize', 'speed', 'strength', 'intelligence', 'sociability', 'fearfulness'];
  for (const key of keys) {
    const [min, max] = GENE_RANGES[key];
    sum += Math.abs(a[key] - b[key]) / (max - min);
  }
  if (a.diet !== b.diet) sum += 1.5;
  return sum / keys.length;
}

export function deriveStats(g) {
  const size = g.size;
  const legFactor = g.legLength * (g.legCount / 4) * (1.15 - g.legThickness * 0.15);
  const maxHealth = 48 + size * 46 + g.armor * 28 + g.legThickness * 14;
  const maxStamina = 32 + g.agility * 34 + size * 8;
  const walk = (1.9 + g.speed * 3.6 + legFactor * 1.3 - size * 0.55) * (g.legCount === 2 ? 1.12 : 1);
  const sprint = walk * (1.55 + g.agility * 0.35);
  const swim = 1.5 + g.agility * 2.2 + g.tailLength * 0.8;
  const fly = g.wings ? 3.6 + g.wingSpan * 3.6 + g.agility * 1.5 - size * 0.6 : 0;
  const bite = 4 + g.teethSize * 12 + g.jawSize * 7 + g.strength * 8;
  const claw = 2 + g.clawSize * 10 + g.strength * 5;
  const armorRating = g.armor * 0.62 + size * 0.1;
  const senses = 11 + g.eyeSize * 7 + g.senseRange * 10 + g.intelligence * 4;
  const metabolismRate = 0.45 + g.metabolism * 1.3 + size * 0.22 - (g.diet === 'carnivore' ? 0.2 : 0);
  const fearBias = g.fearfulness * 1.25 - g.boldness * 0.55 + g.intelligence * 0.15;
  const jump = (3.2 + g.legLength * 3.2 + g.agility * 2.2) * (size > 1.8 ? 0.7 : 1);
  const bodyRadius = size * 0.92;
  const reach = 0.8 + g.snoutLength * 1.2 + size * 0.55;
  const adultAge = 1.2 + size * 1.4;
  const lifeSpan = 7 + g.lifespan * 30 + size * 4;
  const attackCooldown = clamp(1.35 - g.agility * 0.45, 0.6, 1.4);
  const fearDecay = 0.34 - g.intelligence * 0.12;
  const memory = 0.3 + g.intelligence * 0.7;
  return {
    maxHealth, maxStamina, walk, sprint, swim, fly, bite, claw, armorRating, senses,
    metabolismRate, fearBias, jump, bodyRadius, reach, adultAge, lifeSpan, attackCooldown,
    fearDecay, memory, size, vision: 24 + senses * 1.8,
    herdRadius: 7 + g.sociability * 14,
    fleeRadius: 16 + g.fearfulness * 28,
    huntRadius: 20 + senses * 1.8
  };
}

export function genomeColor(g, secondary = false) {
  const h = secondary ? g.hue2 : g.hue1;
  const l = secondary ? clamp(g.lightness * 0.8, 18, 62) : g.lightness;
  return `hsl(${h}, ${g.saturation}%, ${l}%)`;
}

export function genomeAccent(g) {
  return `hsl(${(g.hue2 + 180) % 360}, ${Math.min(95, g.saturation + 15)}%, 62%)`;
}

export function topTraits(g, n = 3) {
  const s = deriveStats(g);
  const traits = [
    { name: 'Devastating jaws', value: s.bite, icon: 'jaw' },
    { name: 'Rending claws', value: s.claw, icon: 'claw' },
    { name: 'Burst speed', value: s.sprint, icon: 'speed' },
    { name: 'Heavy armor', value: s.armorRating * 10, icon: 'armor' },
    { name: 'Keen senses', value: s.senses, icon: 'eye' },
    { name: 'Endurance', value: s.maxStamina, icon: 'stamina' },
    { name: 'Aerial mastery', value: s.fly * 8, icon: 'wing' },
    { name: 'Deep intellect', value: g.intelligence * 100, icon: 'mind' }
  ];
  traits.sort((a, b) => b.value - a.value);
  return traits.slice(0, n);
}

export function speciesDescription(g) {
  const s = deriveStats(g);
  const dietText = g.diet === 'carnivore' ? 'obligate carnivore' : g.diet === 'herbivore' ? 'specialised herbivore' : g.diet === 'scavenger' ? 'opportunistic scavenger' : 'adaptable omnivore';
  const limbs = g.legCount === 2 ? 'bipedal' : g.legCount === 6 ? 'hexapodal' : 'quadrupedal';
  const cover = TEXTURES[g.texture];
  const wings = g.wings ? ' It bears membranous wings and can take to the air.' : '';
  const tail = g.tailLength > 1.2 ? ' A long counterbalancing tail trails behind it.' : '';
  const armor = g.armor > 0.8 ? ' Bony armor plates shield its back.' : '';
  const social = g.sociability > 0.7 ? ' Highly social, moving in coordinated herds or packs.' : g.sociability < 0.3 ? ' Solitary and territorial.' : ' Loosely gregarious.';
  const fear = g.fearfulness > 0.7 ? ' It is easily startled.' : g.boldness > 0.7 ? ' It shows little fear of larger animals.' : '';
  return `A ${g.size > 1.7 ? 'massive' : g.size < 0.9 ? 'diminutive' : 'medium-sized'} ${limbs} ${dietText} with ${cover} skin. ${wings}${tail}${armor}${social}${fear} Bite force measured at ${s.bite.toFixed(0)} N, sprinting near ${(s.sprint * 2.4).toFixed(0)} km/h.`;
}

export function makeSpecies(rng, genome, opts = {}) {
  const g = normalizeGenome(genome);
  return {
    id: opts.id || 'sp_' + Math.floor(rng() * 1e9).toString(36),
    name: opts.name || makeSpeciesName(rng),
    common: opts.common || makeCommonName(rng, g.diet),
    genome: g,
    diet: g.diet,
    habitat: opts.habitat || pick(rng, ['forest', 'grassland', 'marsh', 'desert', 'mountain']),
    population: opts.population ?? Math.floor(randRange(rng, 26, 90)),
    generation: opts.generation || 1,
    originYear: opts.originYear || 0,
    ancestorId: opts.ancestorId || null,
    playerLineage: !!opts.playerLineage,
    extinct: false,
    discovered: !!opts.discovered,
    behavior: opts.behavior || 'wander',
    color: genomeColor(g),
    notes: opts.notes || ''
  };
}

export function buildStartingSpecies(rng) {
  const defs = [
    ['grazer', 'grassland'], ['strider', 'desert'], ['stalker', 'forest'], ['hopper', 'marsh'],
    ['scavenger', 'grassland'], ['glider', 'mountain'], ['titan', 'grassland'], ['lurker', 'marsh']
  ];
  return defs.map(([kind, habitat], i) => makeSpecies(rng, presetGenome(kind, rng), {
    habitat, population: [54, 42, 31, 38, 27, 22, 14, 17][i],
    name: ['Verdant Thalara', 'Dunestrider Vex', 'Crimson Korrath', 'Marsh Yssil', 'Bonecarrier Oth', 'Cloud Nyra', 'Old Titan Galum', 'Mire Lurker Uul'][i],
    common: ['Dawn Grazer', 'Dune Strider', 'Ember Stalker', 'Marsh Hopper', 'Bone Scavenger', 'Sky Glider', 'Titan Grazer', 'Mire Lurker'][i],
    behavior: ['herd', 'herd', 'pack', 'wander', 'scavenge', 'territory', 'herd', 'ambush'][i],
    discovered: i < 4
  }));
}

// Draw a side-profile silhouette from a genome. Used by codex, family tree and HUD portrait.
export function drawSilhouette(ctx, g, w, h, opts = {}) {
  const s = deriveStats(g);
  const scale = Math.min(w / 5.4, h / 3.6) * (opts.zoom || 1);
  const cx = w * 0.47, baseY = h * 0.7;
  const bl = g.bodyLength * scale * 1.15;
  const bh = g.bodyHeight * scale * 0.72;
  const bodyY = baseY - g.legLength * scale * 0.72 - bh * 0.5;
  const primary = opts.monochrome ? '#d8f5ea' : `hsl(${g.hue1}, ${g.saturation}%, ${Math.max(30, g.lightness)}%)`;
  const secondary = opts.monochrome ? '#7aa99a' : `hsl(${g.hue2}, ${g.saturation}%, ${Math.max(24, g.lightness * 0.72)}%)`;
  ctx.save();
  ctx.lineJoin = 'round';
  ctx.lineCap = 'round';

  // tail
  if (g.tailLength > 0.05) {
    ctx.strokeStyle = secondary;
    ctx.lineWidth = Math.max(2, g.tailLength * scale * 0.1);
    ctx.beginPath();
    ctx.moveTo(cx - bl * 0.85, bodyY + bh * 0.15);
    ctx.quadraticCurveTo(cx - bl * (1.1 + g.tailLength * 0.35), bodyY - bh * (0.2 + g.tailLength * 0.3), cx - bl * (1.25 + g.tailLength * 0.55), bodyY - bh * (0.5 + g.tailLength * 0.4));
    ctx.stroke();
  }
  // far legs
  ctx.strokeStyle = secondary;
  ctx.lineWidth = Math.max(2, g.legThickness * scale * 0.075);
  const legPairs = g.legCount / 2;
  for (let i = 0; i < legPairs; i++) {
    const lx = cx - bl * 0.52 + (bl * 1.04) * (i / Math.max(1, legPairs - 1 || 0.5));
    ctx.beginPath();
    ctx.moveTo(lx - 5, bodyY + bh * 0.3);
    ctx.lineTo(lx - 9, baseY);
    ctx.stroke();
  }
  // body
  ctx.fillStyle = primary;
  ctx.beginPath();
  ctx.ellipse(cx, bodyY, bl, bh, -0.03, 0, Math.PI * 2);
  ctx.fill();
  // dorsal pattern
  if (g.pattern === 1 || g.pattern === 4) {
    ctx.save();
    ctx.clip();
    ctx.fillStyle = secondary;
    for (let i = -2; i <= 2; i++) {
      if (g.pattern === 4) ctx.fillRect(cx + i * bl * 0.32, bodyY - bh * 1.1, bl * 0.12, bh * 0.55);
      else ctx.fillRect(cx + i * bl * 0.35, bodyY - bh, bl * 0.075, bh * 2);
    }
    ctx.restore();
  }
  if (g.pattern === 2) {
    ctx.save(); ctx.clip();
    ctx.fillStyle = secondary;
    for (let i = 0; i < 6; i++) {
      ctx.beginPath(); ctx.arc(cx + ((i * 37) % 60 - 30) * scale * 0.035, bodyY + ((i * 23) % 24 - 12) * scale * 0.03, scale * 0.045, 0, Math.PI * 2); ctx.fill();
    }
    ctx.restore();
  }
  // armor plates
  if (g.armor > 0.25) {
    ctx.fillStyle = secondary;
    for (let i = 0; i < 4; i++) {
      ctx.beginPath();
      ctx.ellipse(cx + (i - 1.5) * bl * 0.34, bodyY - bh * 0.72, bl * 0.13, bh * 0.28 * g.armor, -0.1, 0, Math.PI * 2);
      ctx.fill();
    }
  }
  // spikes
  if (g.spikeSize > 0.1) {
    ctx.fillStyle = secondary;
    const n = Math.round(3 + g.spikeSize * 4);
    for (let i = 0; i < n; i++) {
      const sx = cx + (i - (n - 1) / 2) * bl * 0.24;
      const sh = (0.18 + g.spikeSize * 0.3) * scale * (0.5 + (i % 2) * 0.3);
      ctx.beginPath(); ctx.moveTo(sx - bl * 0.06, bodyY - bh * 0.75); ctx.lineTo(sx, bodyY - bh * 0.75 - sh); ctx.lineTo(sx + bl * 0.06, bodyY - bh * 0.75); ctx.fill();
    }
  }
  // neck + head
  const neckX = cx + bl * 0.85;
  const headX = neckX + g.neckLength * scale * 0.48 + g.headSize * scale * 0.18;
  const headY = bodyY - bh * 0.6 - g.neckLength * scale * 0.5;
  ctx.strokeStyle = primary;
  ctx.lineWidth = Math.max(4, g.headSize * scale * 0.2);
  ctx.beginPath();
  ctx.moveTo(neckX, bodyY - bh * 0.15);
  ctx.quadraticCurveTo(neckX + g.neckLength * scale * 0.2, headY + bh * 0.2, headX, headY);
  ctx.stroke();
  const hw = g.headSize * scale * (0.34 + g.snoutLength * 0.2);
  const hh = g.headSize * scale * 0.26;
  ctx.fillStyle = primary;
  ctx.beginPath();
  ctx.ellipse(headX + hw * 0.45, headY, hw, hh, -0.05, 0, Math.PI * 2);
  ctx.fill();
  // jaw
  if (g.teethSize > 0.35) {
    ctx.strokeStyle = secondary;
    ctx.lineWidth = Math.max(2, hh * 0.18);
    ctx.beginPath(); ctx.moveTo(headX + hw * 0.15, headY + hh * 0.45); ctx.lineTo(headX + hw * 1.25, headY + hh * 0.28); ctx.stroke();
  }
  // horns
  if (g.hornSize > 0.08) {
    ctx.strokeStyle = secondary;
    ctx.lineWidth = Math.max(2, g.hornSize * scale * 0.1);
    ctx.beginPath();
    ctx.moveTo(headX + hw * 0.45, headY - hh * 0.5);
    ctx.quadraticCurveTo(headX + hw * 0.65, headY - hh * 1.1, headX + hw * 1.05, headY - hh * (1.15 + g.hornSize * 0.8));
    ctx.stroke();
  }
  // eye
  ctx.fillStyle = '#f5f8e8';
  ctx.beginPath(); ctx.arc(headX + hw * 0.7, headY - hh * 0.2, Math.max(1.6, g.eyeSize * scale * 0.055), 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#101612';
  ctx.beginPath(); ctx.arc(headX + hw * 0.73, headY - hh * 0.2, Math.max(0.8, g.eyeSize * scale * 0.027), 0, Math.PI * 2); ctx.fill();
  // near legs
  ctx.strokeStyle = primary;
  ctx.lineWidth = Math.max(2.5, g.legThickness * scale * 0.09);
  for (let i = 0; i < legPairs; i++) {
    const lx = cx - bl * 0.45 + (bl * 0.92) * (i / Math.max(1, legPairs - 1 || 0.5));
    ctx.beginPath();
    ctx.moveTo(lx, bodyY + bh * 0.25);
    ctx.lineTo(lx + 6, bodyY + bh * 0.45 + g.legLength * scale * 0.32);
    ctx.lineTo(lx + 12, baseY);
    ctx.stroke();
  }
  // wings
  if (g.wings) {
    ctx.fillStyle = primary;
    ctx.globalAlpha = 0.55;
    ctx.beginPath();
    ctx.moveTo(cx - bl * 0.25, bodyY - bh * 0.4);
    ctx.quadraticCurveTo(cx - bl * 0.4, bodyY - bh * 1.9 * g.wingSpan, cx + bl * 0.25, bodyY - bh * 1.7 * g.wingSpan);
    ctx.quadraticCurveTo(cx + bl * 0.42, bodyY - bh * 0.9, cx - bl * 0.05, bodyY - bh * 0.3);
    ctx.fill();
    ctx.globalAlpha = 1;
  }
  ctx.restore();
  return s;
}

// Procedural creature anatomy + skeletal rig + procedural animation.
import * as THREE from 'three';
import { mergeGeometries } from 'three/addons/utils/BufferGeometryUtils.js';
import { clamp, lerp, damp, TAU } from './util.js';
import { deriveStats, genomeColor } from './genome.js';

const skinCache = new Map();
const matCache = new Map();

function mat(key, make) {
  if (!matCache.has(key)) matCache.set(key, make());
  return matCache.get(key);
}

export function skinTexture(g) {
  const key = `${Math.round(g.hue1)}_${Math.round(g.hue2)}_${Math.round(g.saturation)}_${Math.round(g.lightness)}_${g.pattern}_${g.texture}`;
  if (skinCache.has(key)) return skinCache.get(key);
  const size = 128;
  const c = document.createElement('canvas');
  c.width = c.height = size;
  const ctx = c.getContext('2d');
  const base = `hsl(${g.hue1}, ${g.saturation}%, ${g.lightness}%)`;
  const sec = `hsl(${g.hue2}, ${g.saturation}%, ${Math.max(16, g.lightness * 0.72)}%)`;
  ctx.fillStyle = base;
  ctx.fillRect(0, 0, size, size);
  if (g.pattern === 1) {
    ctx.fillStyle = sec;
    for (let i = 0; i < 6; i++) ctx.fillRect(0, i * 22 + 4, size, 7);
  } else if (g.pattern === 2) {
    ctx.fillStyle = sec;
    for (let i = 0; i < 46; i++) {
      const x = (i * 79) % size, y = (i * 47) % size, r = 2 + (i % 4);
      ctx.beginPath(); ctx.arc(x, y, r, 0, TAU); ctx.fill();
    }
  } else if (g.pattern === 3) {
    const grd = ctx.createLinearGradient(0, 0, 0, size);
    grd.addColorStop(0, sec); grd.addColorStop(0.55, base); grd.addColorStop(1, sec);
    ctx.fillStyle = grd; ctx.fillRect(0, 0, size, size);
  } else if (g.pattern === 4) {
    ctx.fillStyle = sec;
    ctx.fillRect(0, 0, size, 30);
    for (let i = 0; i < 8; i++) ctx.fillRect(i * 17, 14, 6, 34 + (i % 3) * 9);
  }
  if (g.texture === 1) {
    ctx.strokeStyle = 'rgba(10,20,14,0.22)';
    ctx.lineWidth = 1;
    for (let y = 4; y < size; y += 8) for (let x = (y / 8) % 2 ? 0 : 5; x < size; x += 10) {
      ctx.beginPath(); ctx.arc(x, y, 4, 0, Math.PI); ctx.stroke();
    }
  } else if (g.texture === 2) {
    ctx.strokeStyle = 'rgba(255,255,255,0.10)';
    ctx.lineWidth = 1;
    for (let i = 0; i < 90; i++) {
      const x = (i * 61) % size, y = (i * 37) % size;
      ctx.beginPath(); ctx.moveTo(x, y); ctx.lineTo(x - 1, y + 7 + (i % 4)); ctx.stroke();
    }
  } else if (g.texture === 3) {
    ctx.strokeStyle = 'rgba(0,0,0,0.20)';
    ctx.lineWidth = 1.4;
    for (let y = 0; y < size; y += 14) {
      for (let x = (y / 14) % 2 ? 0 : 7; x < size; x += 14) {
        ctx.beginPath(); ctx.arc(x, y, 6, 0, TAU); ctx.stroke();
      }
    }
  }
  const tex = new THREE.CanvasTexture(c);
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
  tex.repeat.set(1.4, 1.4);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.anisotropy = 4;
  skinCache.set(key, tex);
  return tex;
}

function clean(g) {
  const geo = g.index ? g.toNonIndexed() : g;
  if (geo !== g) g.dispose();
  return geo;
}
function merge(list) {
  const cleaned = list.map(clean);
  return mergeGeometries(cleaned, false);
}
function ellipsoid(rx, ry, rz, seg = 14, rings = 10) {
  return new THREE.SphereGeometry(1, seg, rings).scale(rx, ry, rz);
}
function ellipsoidAt(rx, ry, rz, x, y, z, seg = 14, rings = 10) {
  return ellipsoid(rx, ry, rz, seg, rings).translate(x, y, z);
}
function cylBetween(a, b, r1, r2, radial = 7) {
  const dir = new THREE.Vector3().subVectors(b, a);
  const len = dir.length();
  const geo = new THREE.CylinderGeometry(r2, r1, len, radial, 1, false);
  geo.translate(0, len / 2, 0);
  const q = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.normalize());
  geo.applyQuaternion(q);
  geo.translate(a.x, a.y, a.z);
  return geo;
}
function coneAt(r, h, x, y, z, dir = new THREE.Vector3(0, 1, 0), radial = 6) {
  const geo = new THREE.ConeGeometry(r, h, radial);
  geo.translate(0, h / 2, 0);
  const q = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.clone().normalize());
  geo.applyQuaternion(q);
  geo.translate(x, y, z);
  return geo;
}
function ringGeo(r1, r2, h, radial = 8) {
  return new THREE.CylinderGeometry(r2, r1, h, radial);
}

function wingGeometry(span, length) {
  const pts = [
    0, 0, 0,
    span * 0.34, 0.16, -length * 0.28,
    span, 0.08, -length * 0.5,
    span * 0.78, -0.02, -length * 1.05,
    span * 0.36, -0.04, -length * 1.2,
    0.04, 0, -length * 0.7
  ];
  const idx = [0, 1, 2, 0, 2, 3, 0, 3, 4, 0, 4, 5, 0, 5, 1];
  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.Float32BufferAttribute(pts, 3));
  const uvs = [0, 0, 0.2, 0.2, 0.6, 0.15, 0.45, 0.8, 0.2, 0.9, 0.05, 0.55];
  geo.setAttribute('uv', new THREE.Float32BufferAttribute(uvs, 2));
  geo.setIndex(idx);
  geo.computeVertexNormals();
  return geo;
}

export class CreatureRig {
  constructor(genome, opts = {}) {
    this.g = genome;
    this.stats = deriveStats(genome);
    this.root = new THREE.Group();
    this.visual = new THREE.Group();
    this.root.add(this.visual);
    this.phase = Math.random() * 10;
    this.t = Math.random() * 10;
    this.blink = 2 + Math.random() * 4;
    this.jawOpen = 0;
    this.legs = [];
    this.arms = [];
    this.tail = [];
    this.wings = [];
    this.eyes = [];
    this.headGroup = null;
    this.jawGroup = null;
    this.bodyMesh = null;
    this.isPlayer = !!opts.player;
    this.scale = opts.scale || 1;
    this.root.scale.setScalar(this.scale);
    this.build();
    this.setState({ speed: 0, state: 'idle' });
  }

  build() {
    const g = this.g, s = this.stats;
    const bw = g.bodyWidth * 0.52, bh = g.bodyHeight * 0.5, bl = g.bodyLength * 0.56;
    const legL = g.legLength;
    const hipY = legL * 1.02 + bh * 0.55;
    this.hipY = hipY;
    this.bodyY = hipY;
    const tex = skinTexture(g);
    const bodyMat = mat(`body_${g.hue1}_${g.hue2}_${g.saturation}_${g.lightness}_${g.pattern}_${g.texture}`, () => new THREE.MeshStandardMaterial({ map: tex, roughness: 0.74, metalness: 0.04 }));
    const secMat = mat(`sec_${Math.round(g.hue2)}_${Math.round(g.saturation)}_${Math.round(g.lightness)}`, () => new THREE.MeshStandardMaterial({ color: genomeColor(g, true), roughness: 0.62, metalness: 0.08 }));
    const boneMat = mat('bone', () => new THREE.MeshStandardMaterial({ color: 0xe9e4ce, roughness: 0.5 }));
    const clawMat = mat('claw', () => new THREE.MeshStandardMaterial({ color: 0x22261f, roughness: 0.35, metalness: 0.15 }));
    const eyeMat = mat('eye', () => new THREE.MeshStandardMaterial({ color: 0xf9f5d4, emissive: 0xffcf6c, emissiveIntensity: 0.45, roughness: 0.2 }));
    const pupilMat = mat('pupil', () => new THREE.MeshStandardMaterial({ color: 0x0a0d0b, roughness: 0.15 }));
    const mouthMat = mat('mouth', () => new THREE.MeshStandardMaterial({ color: 0x4a1418, roughness: 0.7 }));
    this.mats = { bodyMat, secMat, boneMat, clawMat, eyeMat, pupilMat, mouthMat };

    // ---- torso
    const bodyParts = [];
    bodyParts.push(ellipsoidAt(bw, bh, bl, 0, hipY, 0, 16, 12));
    bodyParts.push(ellipsoidAt(bw * 0.86, bh * 0.72, bl * 0.46, 0, hipY - bh * 0.28, bl * 0.36));
    bodyParts.push(ellipsoidAt(bw * 0.9, bh * 0.82, bl * 0.4, 0, hipY + bh * 0.1, -bl * 0.55));
    bodyParts.push(ellipsoidAt(bw * 0.62, bh * 0.55, bl * 0.3, 0, hipY - bh * 0.1, bl * 0.72));
    const headBase = new THREE.Vector3(0, hipY + g.neckLength * 0.42 + bh * 0.18, bl * 0.8 + g.neckLength * 0.22);
    bodyParts.push(cylBetween(new THREE.Vector3(0, hipY + bh * 0.12, bl * 0.55), headBase, bw * 0.42, bw * 0.26 + g.headSize * 0.1, 8));
    // hips
    for (let side = -1; side <= 1; side += 2) {
      bodyParts.push(ellipsoidAt(bw * 0.28, bh * 0.36, bh * 0.4, side * bw * 0.55, hipY - bh * 0.34, bl * 0.3, 8, 6));
      bodyParts.push(ellipsoidAt(bw * 0.26, bh * 0.32, bh * 0.36, side * bw * 0.55, hipY - bh * 0.3, -bl * 0.52, 8, 6));
    }
    const bodyGeo = merge(bodyParts);
    const bodyMesh = new THREE.Mesh(bodyGeo, bodyMat);
    bodyMesh.castShadow = true; bodyMesh.receiveShadow = true;
    this.visual.add(bodyMesh);
    this.bodyMesh = bodyMesh;

    // ---- secondary body: armor plates + dorsal spikes
    const secParts = [];
    if (g.armor > 0.12) {
      const n = 5;
      for (let i = 0; i < n; i++) {
        const t = (i / (n - 1) - 0.5) * 2;
        const plate = ellipsoid(bw * (0.62 - Math.abs(t) * 0.15), bh * 0.16, bl * 0.19, 8, 6);
        plate.rotateX(-0.08);
        plate.translate(0, hipY + bh * (0.82 + Math.sin(i * 1.2) * 0.05), t * bl * 0.55);
        secParts.push(plate);
      }
    }
    if (g.spikeSize > 0.1) {
      const n = Math.round(2 + g.spikeSize * 4);
      for (let i = 0; i < n; i++) {
        const z = (i / Math.max(1, n - 1) - 0.5) * bl * 1.3;
        const h = (0.12 + g.spikeSize * 0.3) * (0.8 + (i % 2) * 0.3);
        const dir = new THREE.Vector3(0, 1, -0.55);
        secParts.push(coneAt(bw * 0.08, h, 0, hipY + bh * 0.82, z, dir, 5));
      }
    }
    if (secParts.length) {
      const secMesh = new THREE.Mesh(merge(secParts), secMat);
      secMesh.castShadow = true;
      this.visual.add(secMesh);
    }

    // ---- head
    const head = new THREE.Group();
    head.position.copy(headBase);
    this.visual.add(head);
    this.headGroup = head;
    const hs = g.headSize;
    const headParts = [];
    headParts.push(ellipsoidAt(hs * 0.46, hs * 0.4, hs * 0.52, 0, 0, hs * 0.1, 14, 10));
    headParts.push(ellipsoidAt(hs * 0.55, hs * 0.3, hs * (0.35 + g.snoutLength * 0.35), 0, -hs * 0.05, hs * (0.52 + g.snoutLength * 0.1), 12, 8));
    headParts.push(ellipsoidAt(hs * 0.35, hs * 0.18, hs * 0.22, 0, hs * 0.24, -hs * 0.12, 8, 6));
    const headMesh = new THREE.Mesh(merge(headParts), bodyMat);
    headMesh.castShadow = true;
    head.add(headMesh);

    // upper teeth
    if (g.teethSize > 0.25) {
      const teeth = [];
      const n = Math.round(4 + g.teethSize * 4);
      for (let i = 0; i < n; i++) {
        const x = (i / (n - 1) - 0.5) * hs * 0.62;
        teeth.push(coneAt(hs * 0.035 + g.teethSize * 0.02, hs * (0.1 + g.teethSize * 0.13), x, -hs * 0.18, hs * (0.55 + g.snoutLength * 0.22), new THREE.Vector3(0, -1, 0.15), 4));
      }
      const upperTeeth = new THREE.Mesh(merge(teeth), boneMat);
      head.add(upperTeeth);
    }
    // horns
    if (g.hornSize > 0.08) {
      const horns = [];
      for (let side = -1; side <= 1; side += 2) {
        const base = new THREE.Vector3(side * hs * 0.3, hs * 0.28, -hs * 0.02);
        const tip = new THREE.Vector3(side * hs * (0.45 + g.hornSize * 0.3), hs * (0.55 + g.hornSize * 0.55), -hs * (0.3 + g.hornSize * 0.5));
        horns.push(coneAt(hs * (0.055 + g.hornSize * 0.045), base.distanceTo(tip), base.x, base.y, base.z, tip.clone().sub(base), 6));
      }
      const hornMesh = new THREE.Mesh(merge(horns), boneMat);
      hornMesh.castShadow = true;
      head.add(hornMesh);
    }
    // eyes
    const eyeCount = g.eyeSize > 1.45 ? 4 : 2;
    for (let e = 0; e < eyeCount; e++) {
      const side = e % 2 === 0 ? -1 : 1;
      const row = e < 2 ? 0 : 1;
      const eye = new THREE.Group();
      eye.position.set(side * hs * 0.3, hs * (0.10 + row * 0.14), hs * (0.38 + row * 0.03));
      const r = hs * (0.085 + g.eyeSize * 0.045);
      const white = new THREE.Mesh(new THREE.SphereGeometry(r, 10, 8), eyeMat);
      const pupil = new THREE.Mesh(new THREE.SphereGeometry(r * 0.46, 8, 6), pupilMat);
      pupil.position.set(side * r * 0.05, 0, r * 0.72);
      pupil.scale.z = 0.42;
      eye.add(white, pupil);
      head.add(eye);
      this.eyes.push({ group: eye, white, pupil });
    }
    // jaw
    const jaw = new THREE.Group();
    jaw.position.set(0, -hs * 0.18, hs * 0.08);
    head.add(jaw);
    this.jawGroup = jaw;
    const jawParts = [];
    jawParts.push(ellipsoidAt(hs * 0.42, hs * 0.15, hs * (0.35 + g.snoutLength * 0.28), 0, -hs * 0.02, hs * (0.3 + g.snoutLength * 0.15), 12, 8));
    jawParts.push(ellipsoidAt(hs * 0.28, hs * 0.2, hs * 0.22, 0, -hs * 0.08, hs * 0.08, 8, 6));
    const jawMesh = new THREE.Mesh(merge(jawParts), bodyMat);
    jawMesh.castShadow = true;
    jaw.add(jawMesh);
    if (g.teethSize > 0.25) {
      const teeth = [];
      const n = Math.round(4 + g.teethSize * 4);
      for (let i = 0; i < n; i++) {
        const x = (i / (n - 1) - 0.5) * hs * 0.58;
        teeth.push(coneAt(hs * 0.032 + g.teethSize * 0.018, hs * (0.09 + g.teethSize * 0.11), x, hs * 0.08, hs * (0.3 + g.snoutLength * 0.2), new THREE.Vector3(0, 1, 0.1), 4));
      }
      jaw.add(new THREE.Mesh(merge(teeth), boneMat));
    }
    // mouth cavity
    const mouth = new THREE.Mesh(new THREE.SphereGeometry(hs * 0.22, 8, 6), mouthMat);
    mouth.scale.set(1.4, 0.5, 1.1);
    mouth.position.set(0, -hs * 0.12, hs * 0.28);
    head.add(mouth);

    // ---- legs
    const pairCount = Math.round(g.legCount / 2);
    const upperLen = legL * 0.55, lowerLen = legL * 0.5;
    const lw = g.legThickness * 0.1 + 0.035;
    for (let p = 0; p < pairCount; p++) {
      const t = pairCount === 1 ? 0 : (p / (pairCount - 1) - 0.5) * 2;
      const z = pairCount === 1 ? -bl * 0.45 : t * bl * 0.62;
      for (let side = -1; side <= 1; side += 2) {
        const hip = new THREE.Group();
        hip.position.set(side * bw * 0.58, hipY - bh * 0.42, z);
        this.visual.add(hip);
        const upperParts = [cylBetween(new THREE.Vector3(0, 0, 0), new THREE.Vector3(0, -upperLen, 0), lw * 1.15, lw * 0.85, 7)];
        upperParts.push(ellipsoidAt(lw * 1.3, lw * 1.3, lw * 1.3, 0, 0, 0, 8, 6));
        const upperMesh = new THREE.Mesh(merge(upperParts), bodyMat);
        upperMesh.castShadow = true;
        hip.add(upperMesh);
        const knee = new THREE.Group();
        knee.position.y = -upperLen;
        hip.add(knee);
        const lowerParts = [cylBetween(new THREE.Vector3(0, 0, 0), new THREE.Vector3(0, -lowerLen, 0), lw * 0.82, lw * 0.56, 6)];
        const foot = ellipsoid(lw * 1.4, lw * 0.7, lw * 2.0, 8, 5);
        foot.translate(0, -lowerLen, lw * 0.5);
        lowerParts.push(foot);
        const lowerMesh = new THREE.Mesh(merge(lowerParts), bodyMat);
        lowerMesh.castShadow = true;
        knee.add(lowerMesh);
        if (g.clawSize > 0.15) {
          const claws = [];
          for (let c = -1; c <= 1; c++) {
            claws.push(coneAt(lw * 0.35, g.clawSize * 0.22, c * lw * 0.7, -lowerLen + 0.01, lw * 1.3, new THREE.Vector3(0, -0.45, 1), 4));
          }
          knee.add(new THREE.Mesh(merge(claws), clawMat));
        }
        this.legs.push({ hip, knee, baseZ: z, side, pair: p, injured: false });
      }
    }

    // ---- arms
    if (g.armLength > 0.16) {
      for (let side = -1; side <= 1; side += 2) {
        const arm = new THREE.Group();
        arm.position.set(side * bw * 0.72, hipY + bh * 0.18, bl * 0.48);
        this.visual.add(arm);
        const upper = new THREE.Mesh(cylBetween(new THREE.Vector3(0, 0, 0), new THREE.Vector3(side * 0.04, -g.armLength * 0.5, 0.04), lw * 0.85, lw * 0.65, 6), bodyMat);
        upper.castShadow = true;
        arm.add(upper);
        const elbow = new THREE.Group();
        elbow.position.set(side * 0.04, -g.armLength * 0.5, 0.04);
        arm.add(elbow);
        const lower = new THREE.Mesh(cylBetween(new THREE.Vector3(0, 0, 0), new THREE.Vector3(0, -g.armLength * 0.44, 0.06), lw * 0.62, lw * 0.42, 6), bodyMat);
        elbow.add(lower);
        if (g.clawSize > 0.2) {
          const claws = [];
          for (let c = -1; c <= 1; c++) claws.push(coneAt(lw * 0.3, g.clawSize * 0.24, c * lw * 0.55, -g.armLength * 0.44, 0.06, new THREE.Vector3(0, -0.3, 1), 4));
          elbow.add(new THREE.Mesh(merge(claws), clawMat));
        }
        this.arms.push({ arm, elbow, side });
      }
    }

    // ---- tail
    if (g.tailLength > 0.12) {
      const segs = 4;
      const segLen = g.tailLength * 0.32 + 0.06;
      let parent = new THREE.Group();
      parent.position.set(0, hipY + bh * 0.12, -bl * 0.88);
      parent.rotation.x = 0.18;
      this.visual.add(parent);
      for (let i = 0; i < segs; i++) {
        const seg = new THREE.Group();
        if (i > 0) seg.position.z = -segLen;
        const r = lw * (1.15 - i * 0.18);
        const geo = merge([
          new THREE.CylinderGeometry(r * 0.7, r, segLen, 6).rotateX(Math.PI / 2).translate(0, 0, -segLen / 2),
          bellySphere(r, segLen)
        ]);
        const m = new THREE.Mesh(geo, i % 2 === 0 ? bodyMat : secMat);
        m.castShadow = true;
        seg.add(m);
        parent.add(seg);
        this.tail.push(seg);
        parent = seg;
      }
      const tip = new THREE.Mesh(coneAt(lw * 0.35, g.tailLength * 0.16 + 0.05, 0, 0, -segLen, new THREE.Vector3(0, 0, -1), 5), secMat);
      parent.add(tip);
    }

    // ---- wings
    if (g.wings) {
      for (let side = -1; side <= 1; side += 2) {
        const wing = new THREE.Group();
        wing.position.set(side * bw * 0.48, hipY + bh * 0.28, bl * 0.05);
        wing.scale.x = side;
        this.visual.add(wing);
        const span = g.wingSpan * 1.5 + 0.4;
        const membrane = new THREE.Mesh(wingGeometry(span, bl * 1.15), mat(`wing_${g.hue1}_${g.hue2}_${g.saturation}`, () => new THREE.MeshStandardMaterial({
          color: genomeColor(g), transparent: true, opacity: 0.72, side: THREE.DoubleSide, roughness: 0.8, depthWrite: false
        })));
        membrane.castShadow = true;
        wing.add(membrane);
        const bones = [];
        bones.push(cylBetween(new THREE.Vector3(0, 0, 0), new THREE.Vector3(span * 0.9, 0.08, -bl * 0.5), 0.035, 0.02, 5));
        bones.push(cylBetween(new THREE.Vector3(0, 0, 0), new THREE.Vector3(span * 0.42, 0.1, -bl * 1.0), 0.03, 0.018, 5));
        wing.add(new THREE.Mesh(merge(bones), secMat));
        this.wings.push(wing);
      }
    }

    this.root.userData.rig = this;
  }

  setState(st) {
    this.state = { ...(this.state || {}), ...st };
  }

  setInjury(part) {
    if (part === 'leg' && this.legs.length) {
      const leg = this.legs[Math.floor(Math.random() * this.legs.length)];
      leg.injured = true;
    }
    if (part === 'eye' && this.eyes.length) this.eyes[Math.floor(Math.random() * this.eyes.length)].injured = true;
    if (part === 'jaw') this.jawInjured = true;
  }

  update(dt) {
    const st = this.state || {};
    this.t += dt;
    const speed = st.speed || 0;
    const moving = speed > 0.12;
    const flying = st.flying;
    const swimming = st.swimming;
    const sleeping = st.state === 'sleep';
    const dead = st.dead;
    const attacking = st.state === 'attack';
    const eating = st.state === 'eat' || st.state === 'graze';
    const hurt = st.hurt || 0;
    const fear = st.fear || 0;
    const strideRate = clamp(speed * 1.5 + 1.1, 1.1, 8.5);
    if (moving && !sleeping) this.phase += dt * strideRate * (flying ? 0.7 : 1);
    else this.phase += dt * 0.35;
    const amp = moving ? clamp(0.32 + speed * 0.075, 0.3, 0.8) : 0.03;
    const bob = moving ? Math.abs(Math.sin(this.phase)) * 0.045 * clamp(speed * 0.35, 0.3, 1.5) : Math.sin(this.t * 1.5) * 0.012;

    if (!dead) {
      this.visual.position.y = damp(this.visual.position.y, sleeping ? -this.g.legLength * 0.34 : bob, 12, dt);
      const leanTarget = flying ? -0.16 : swimming ? 0.05 : sleeping ? -0.05 : moving ? clamp(speed * 0.02, 0, 0.14) : 0;
      this.visual.rotation.x = damp(this.visual.rotation.x, leanTarget, 5, dt);
      this.visual.rotation.z = damp(this.visual.rotation.z, moving ? Math.sin(this.phase) * 0.035 + (st.injuredLeg ? 0.05 : 0) : 0, 6, dt);
      this.visual.rotation.y = damp(this.visual.rotation.y, st.turn ? clamp(st.turn * -0.2, -0.35, 0.35) : 0, 6, dt);
      if (fear > 0.5 && !sleeping) {
        this.visual.position.x = (Math.random() - 0.5) * 0.012 * fear;
      } else this.visual.position.x = damp(this.visual.position.x, 0, 14, dt);
    } else {
      this.visual.rotation.z = damp(this.visual.rotation.z, Math.PI * 0.48, 4, dt);
      this.visual.position.y = damp(this.visual.position.y, 0.08, 6, dt);
    }

    const phase = this.phase;
    for (let i = 0; i < this.legs.length; i++) {
      const leg = this.legs[i];
      const off = (leg.pair + (leg.side > 0 ? 1 : 0)) % 2 === 0 ? 0 : Math.PI;
      let swing = Math.sin(phase + off) * amp;
      let bend = Math.max(0, Math.sin(phase + off + 1.15)) * amp * 1.6;
      let sideSwing = 0;
      if (swimming) { swing = Math.sin(this.t * 2 + i) * 0.22; bend = 0.75; }
      if (flying) { swing = -0.55 + Math.sin(this.t * 2.5 + i) * 0.08; bend = 0.9; }
      if (sleeping) { swing = leg.side > 0 ? 0.9 : 0.7; bend = 1.65; sideSwing = leg.side * 0.25; }
      if (dead) { swing = 0.2; bend = 0.2; }
      if (leg.injured) { swing *= 0.35; bend += 0.35; }
      if (!moving && !sleeping && !flying && !swimming) { swing = 0.03; bend = 0.12; }
      leg.hip.rotation.x = damp(leg.hip.rotation.x, -swing * 0.6, 18, dt);
      leg.hip.rotation.z = damp(leg.hip.rotation.z, sideSwing + (leg.side > 0 ? -0.09 : 0.09), 10, dt);
      leg.knee.rotation.x = damp(leg.knee.rotation.x, bend * 0.7, 18, dt);
    }
    for (const a of this.arms) {
      const swing = Math.sin(phase + (a.side > 0 ? 0 : Math.PI)) * amp * 0.75;
      a.arm.rotation.x = damp(a.arm.rotation.x, moving ? -swing : 0.14, 10, dt);
      a.elbow.rotation.x = damp(a.elbow.rotation.x, 0.3 + Math.max(0, -swing) * 0.5, 10, dt);
      a.arm.rotation.z = damp(a.arm.rotation.z, a.side * 0.18, 6, dt);
    }
    for (let i = 0; i < this.tail.length; i++) {
      const seg = this.tail[i];
      const sway = Math.sin(phase * 0.8 - i * 0.55) * (moving ? 0.16 : 0.05) * (swimming ? 1.9 : 1);
      seg.rotation.y = damp(seg.rotation.y, sway, 10, dt);
      seg.rotation.x = damp(seg.rotation.x, swimming ? Math.sin(phase - i * 0.6) * 0.2 : (sleeping ? 0.25 : 0.03), 8, dt);
    }
    if (this.wings.length) {
      const flapRate = flying ? 7.5 : 1.4;
      const flap = flying ? Math.sin(this.t * flapRate) * 0.72 : Math.sin(this.t * 1.1) * 0.04;
      for (const wing of this.wings) {
        wing.rotation.z = damp(wing.rotation.z, (flying ? 0.18 + flap : 0.32) * (wing.scale.x > 0 ? 1 : 1), 8, dt);
        wing.rotation.y = damp(wing.rotation.y, flying ? 0.05 : 0.5, 5, dt);
      }
    }
    // head look / jaw / blink
    if (this.headGroup) {
      let pitch = 0, yaw = 0;
      if (eating) pitch = 0.55 + Math.sin(this.t * 7) * 0.08;
      else if (sleeping) pitch = 0.5;
      else if (attacking) pitch = -0.18;
      else if (st.roar) pitch = -0.45;
      else if (flying) pitch = -0.05;
      if (st.lookYaw) yaw = clamp(st.lookYaw, -0.5, 0.5);
      this.headGroup.rotation.x = damp(this.headGroup.rotation.x, pitch, 8, dt);
      this.headGroup.rotation.y = damp(this.headGroup.rotation.y, yaw + Math.sin(this.t * 0.4) * 0.04, 4, dt);
    }
    let jawTarget = 0.04 + Math.sin(this.t * 1.6) * 0.02;
    if (eating) jawTarget = 0.25 + Math.abs(Math.sin(this.t * 8)) * 0.55;
    if (attacking) jawTarget = 0.7;
    if (st.roar) jawTarget = 0.85;
    if (sleeping) jawTarget = 0.02;
    if (this.jawInjured) jawTarget *= 0.35;
    if (this.jawGroup) this.jawGroup.rotation.x = damp(this.jawGroup.rotation.x, jawTarget, 12, dt);

    this.blink -= dt;
    if (this.blink < 0) this.blink = 2 + Math.random() * 5;
    const blink = this.blink < 0.13 ? 0.15 : 1;
    for (const e of this.eyes) {
      e.white.scale.y = damp(e.white.scale.y, blink, 25, dt);
      e.pupil.scale.y = damp(e.pupil.scale.y, blink * 0.42, 25, dt);
      if (e.injured) e.white.material = this.mats.pupilMat;
    }
    const breathe = 1 + Math.sin(this.t * 1.8) * 0.012;
    if (this.bodyMesh) this.bodyMesh.scale.set(1, breathe, 1);
  }

  setScale(v) {
    this.scale = v;
    this.root.scale.setScalar(v);
  }

  dispose() {
    this.root.traverse(o => {
      if (o.geometry) o.geometry.dispose();
    });
    this.root.removeFromParent();
  }
}

function bellySphere(r, len) {
  return new THREE.SphereGeometry(r * 0.85, 6, 5).scale(1, 1, len * 0.6);
}

// Procedural world: terrain, biome, water, sky, weather, flora, food and shelters.
import * as THREE from 'three';
import { mergeGeometries } from 'three/addons/utils/BufferGeometryUtils.js';
import { clamp, lerp, damp, smoothstep, fbm, valueNoise, mulberry32, pick, chance, randRange, TAU } from './util.js';

export const WATER_LEVEL = 0.6;
export const WORLD_SIZE = 620;
const GRID = 200;
const HALF = WORLD_SIZE / 2;

const BIOME_INFO = {
  ocean: { label: 'Ocean', hue: 198, sat: 58, light: 31 },
  beach: { label: 'Shore', hue: 42, sat: 48, light: 58 },
  grassland: { label: 'Grassland', hue: 88, sat: 44, light: 42 },
  forest: { label: 'Forest', hue: 128, sat: 42, light: 32 },
  marsh: { label: 'Marsh', hue: 158, sat: 34, light: 29 },
  desert: { label: 'Desert', hue: 33, sat: 46, light: 52 },
  mountain: { label: 'Mountain', hue: 210, sat: 12, light: 42 }
};

function colorGeo(geo, color) {
  const c = new THREE.Color(color);
  const count = geo.attributes.position.count;
  const arr = new Float32Array(count * 3);
  for (let i = 0; i < count; i++) { arr[i * 3] = c.r; arr[i * 3 + 1] = c.g; arr[i * 3 + 2] = c.b; }
  geo.setAttribute('color', new THREE.BufferAttribute(arr, 3));
  return geo;
}

function instancedFrom(geo, material, entries, opts = {}) {
  const mesh = new THREE.InstancedMesh(geo, material, entries.length);
  const m = new THREE.Matrix4();
  const q = new THREE.Quaternion();
  const s = new THREE.Vector3();
  const p = new THREE.Vector3();
  const col = new THREE.Color();
  entries.forEach((e, i) => {
    p.set(e.x, e.y, e.z);
    q.setFromEuler(new THREE.Euler(0, e.rot || 0, 0));
    const sc = e.scale || 1;
    s.set(sc * (e.sx || 1), sc * (e.sy || 1), sc * (e.sz || 1));
    m.compose(p, q, s);
    mesh.setMatrixAt(i, m);
    if (e.color) mesh.setColorAt(i, col.set(e.color));
  });
  mesh.instanceMatrix.needsUpdate = true;
  if (mesh.instanceColor) mesh.instanceColor.needsUpdate = true;
  mesh.castShadow = opts.shadow !== false;
  mesh.receiveShadow = true;
  mesh.frustumCulled = opts.cull !== false;
  return mesh;
}

export class World {
  constructor(scene, seed = 424242, epoch = 0) {
    this.scene = scene;
    this.seed = seed;
    this.epoch = epoch;
    this.time = 0.28;
    this.day = 1;
    this.dayLength = 210;
    this.seasonTime = 0;
    this.seasonLength = 110;
    this.seasonNames = ['Spring', 'Summer', 'Autumn', 'Winter'];
    this.seasonIndex = 0;
    this.yearFloat = 0;
    this.baseYear = 1_000_000;
    this.focus = new THREE.Vector3();
    this.weather = { type: 'clear', intensity: 0, timer: 30, label: 'Clear', wind: 0.3 };
    this.rain = null;
    this.snow = null;
    this.flash = 0;
    this.hazard = null;
    this.biomeCache = new Map();
    this.heights = null;
    this.generateHeight();
    this.buildSky();
    this.buildLights();
    this.buildTerrain();
    this.buildWater();
    this.buildClouds();
    this.buildFoliage();
    this.buildShelters();
    this.buildPlants();
    this.buildParticles();
    this.applyEpoch(epoch);
    this.update(0.016, new THREE.Vector3(0, 0, 0));
  }

  generateHeight() {
    const n = GRID + 1;
    const heights = new Float32Array(n * n);
    for (let iz = 0; iz < n; iz++) {
      for (let ix = 0; ix < n; ix++) {
        const x = (ix / GRID - 0.5) * WORLD_SIZE;
        const z = (iz / GRID - 0.5) * WORLD_SIZE;
        const edge = Math.max(Math.abs(x), Math.abs(z)) / HALF;
        let h = (fbm(x * 0.0042, z * 0.0042, this.seed, 5) - 0.5) * 62 + 5.5;
        h += (fbm(x * 0.013, z * 0.013, this.seed + 41, 3) - 0.5) * 10;
        h += (fbm(x * 0.031, z * 0.031, this.seed + 77, 2) - 0.5) * 2.4;
        h -= smoothstep(0.62, 1.02, edge) * 24;
        heights[iz * n + ix] = h;
      }
    }
    this.heights = heights;
    this.gridN = n;
  }

  heightAt(x, z) {
    const fx = clamp((x / WORLD_SIZE + 0.5) * GRID, 0, GRID - 0.001);
    const fz = clamp((z / WORLD_SIZE + 0.5) * GRID, 0, GRID - 0.001);
    const ix = Math.floor(fx), iz = Math.floor(fz);
    const tx = fx - ix, tz = fz - iz;
    const n = this.gridN;
    const h00 = this.heights[iz * n + ix];
    const h10 = this.heights[iz * n + ix + 1];
    const h01 = this.heights[(iz + 1) * n + ix];
    const h11 = this.heights[(iz + 1) * n + ix + 1];
    return lerp(lerp(h00, h10, tx), lerp(h01, h11, tx), tz);
  }

  slopeAt(x, z) {
    const e = 1.5;
    const dx = this.heightAt(x + e, z) - this.heightAt(x - e, z);
    const dz = this.heightAt(x, z + e) - this.heightAt(x, z - e);
    return Math.sqrt(dx * dx + dz * dz) / (2 * e);
  }

  moistureAt(x, z) {
    return fbm(x * 0.0075, z * 0.0075, this.seed + 9, 3);
  }

  temperatureAt(x, z) {
    const h = this.heightAt(x, z);
    const seasonMod = [0.05, 0.16, -0.02, -0.22][this.seasonIndex];
    return clamp(1 - h * 0.021 + seasonMod - this.epoch * 0.06, -0.2, 1.2);
  }

  biomeAt(x, z) {
    const key = (x >> 2) + '_' + (z >> 2);
    if (this.biomeCache.has(key)) return this.biomeCache.get(key);
    const h = this.heightAt(x, z);
    const m = this.moistureAt(x, z);
    let biome;
    if (h < WATER_LEVEL + 0.4) biome = 'ocean';
    else if (h < WATER_LEVEL + 1.4) biome = 'beach';
    else if (h > 24) biome = 'mountain';
    else if (m < 0.36) biome = 'desert';
    else if (m > 0.64 && h < 7.5) biome = 'marsh';
    else if (m > 0.53) biome = 'forest';
    else biome = 'grassland';
    this.biomeCache.set(key, biome);
    if (this.biomeCache.size > 4000) this.biomeCache.clear();
    return biome;
  }

  biomeInfo(biome) { return BIOME_INFO[biome] || BIOME_INFO.grassland; }

  buildTerrain() {
    const n = GRID + 1;
    const positions = new Float32Array(n * n * 3);
    const colors = new Float32Array(n * n * 3);
    const indexes = [];
    const color = new THREE.Color();
    for (let iz = 0; iz < n; iz++) {
      for (let ix = 0; ix < n; ix++) {
        const i = iz * n + ix;
        const x = (ix / GRID - 0.5) * WORLD_SIZE;
        const z = (iz / GRID - 0.5) * WORLD_SIZE;
        const y = this.heights[i];
        positions[i * 3] = x;
        positions[i * 3 + 1] = y;
        positions[i * 3 + 2] = z;
        let biome = 'mountain';
        const m = this.moistureAt(x, z);
        if (y < WATER_LEVEL + 0.35) biome = 'ocean';
        else if (y < WATER_LEVEL + 1.3) biome = 'beach';
        else if (y > 24) biome = 'mountain';
        else if (m < 0.36) biome = 'desert';
        else if (m > 0.64 && y < 7.5) biome = 'marsh';
        else if (m > 0.53) biome = 'forest';
        else biome = 'grassland';
        const info = BIOME_INFO[biome];
        const variance = (valueNoise(x * 0.09, z * 0.09, this.seed + 5) - 0.5) * 0.12;
        const slope = this.slopeAt(x, z);
        const rocky = smoothstep(1.1, 2.6, slope);
        color.setHSL((info.hue + (biome === 'mountain' ? 0 : (valueNoise(x * 0.03, z * 0.03, 3) - 0.5) * 14)) / 360, info.sat / 100, clamp(info.light / 100 + variance - rocky * 0.08, 0.08, 0.78));
        if (biome === 'mountain') color.offsetHSL(0, 0, -rocky * 0.06);
        colors[i * 3] = color.r; colors[i * 3 + 1] = color.g; colors[i * 3 + 2] = color.b;
      }
    }
    for (let iz = 0; iz < GRID; iz++) {
      for (let ix = 0; ix < GRID; ix++) {
        const a = iz * n + ix, b = a + 1, c = a + n, d = c + 1;
        indexes.push(a, c, b, b, c, d);
      }
    }
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    geo.setAttribute('color', new THREE.BufferAttribute(colors, 3));
    geo.setIndex(indexes);
    geo.computeVertexNormals();
    const material = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.96, metalness: 0.01 });
    this.terrain = new THREE.Mesh(geo, material);
    this.terrain.receiveShadow = true;
    this.terrain.castShadow = false;
    this.scene.add(this.terrain);
  }

  buildWater() {
    const geo = new THREE.PlaneGeometry(WORLD_SIZE * 1.5, WORLD_SIZE * 1.5, 110, 110);
    geo.rotateX(-Math.PI / 2);
    this.waterUniforms = {
      uTime: { value: 0 },
      uDeep: { value: new THREE.Color(0x0b3b45) },
      uShallow: { value: new THREE.Color(0x2c8b8c) },
      uSun: { value: new THREE.Color(0xffe9c0) }
    };
    const material = new THREE.ShaderMaterial({
      uniforms: this.waterUniforms,
      transparent: true,
      depthWrite: false,
      side: THREE.DoubleSide,
      vertexShader: `
        uniform float uTime;
        varying vec3 vWorld;
        void main() {
          vec3 p = position;
          p.y += sin(p.x * 0.19 + uTime * 0.9) * 0.09 + sin(p.z * 0.23 - uTime * 0.7) * 0.07;
          vec4 wp = modelMatrix * vec4(p, 1.0);
          vWorld = wp.xyz;
          gl_Position = projectionMatrix * viewMatrix * wp;
        }
      `,
      fragmentShader: `
        uniform float uTime;
        uniform vec3 uDeep;
        uniform vec3 uShallow;
        uniform vec3 uSun;
        varying vec3 vWorld;
        void main() {
          float ripple = sin(vWorld.x * 0.45 + uTime * 1.3) * sin(vWorld.z * 0.39 - uTime * 0.9);
          float ripple2 = sin(vWorld.x * 0.11 - uTime * 0.4 + vWorld.z * 0.08) * 0.5 + 0.5;
          vec3 col = mix(uDeep, uShallow, 0.35 + ripple * 0.12 + ripple2 * 0.22);
          vec3 viewDir = normalize(cameraPosition - vWorld);
          float fres = pow(1.0 - abs(viewDir.y), 2.4);
          col = mix(col, vec3(0.74, 0.93, 0.93), fres * 0.45);
          col += uSun * pow(max(0.0, ripple * 0.5 + 0.5), 12.0) * 0.12;
          gl_FragColor = vec4(col, 0.86);
        }
      `
    });
    this.water = new THREE.Mesh(geo, material);
    this.water.position.y = WATER_LEVEL;
    this.water.renderOrder = 1;
    this.scene.add(this.water);

    // shore foam ring
    const foamGeo = new THREE.RingGeometry(WORLD_SIZE * 0.32, WORLD_SIZE * 0.34, 96, 1);
    foamGeo.rotateX(-Math.PI / 2);
    this.foam = new THREE.Mesh(foamGeo, new THREE.MeshBasicMaterial({ color: 0xbfe7df, transparent: true, opacity: 0.0, depthWrite: false }));
    this.foam.position.y = WATER_LEVEL + 0.02;
    this.scene.add(this.foam);
  }

  buildSky() {
    const geo = new THREE.SphereGeometry(900, 32, 20);
    this.skyUniforms = {
      topColor: { value: new THREE.Color(0x3f78a8) },
      bottomColor: { value: new THREE.Color(0xcfe5d4) },
      sunColor: { value: new THREE.Color(0xffe6ad) },
      sunDir: { value: new THREE.Vector3(0.4, 0.7, 0.2) },
      haze: { value: 0.4 }
    };
    const material = new THREE.ShaderMaterial({
      uniforms: this.skyUniforms,
      side: THREE.BackSide,
      depthWrite: false,
      vertexShader: `varying vec3 vDir; void main(){ vDir = normalize(position); gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0); }`,
      fragmentShader: `
        uniform vec3 topColor; uniform vec3 bottomColor; uniform vec3 sunColor; uniform vec3 sunDir; uniform float haze;
        varying vec3 vDir;
        void main(){
          float h = clamp(vDir.y * 0.5 + 0.5, 0.0, 1.0);
          vec3 col = mix(bottomColor, topColor, pow(h, 0.65));
          float sun = max(0.0, dot(normalize(vDir), normalize(sunDir)));
          col += sunColor * pow(sun, 260.0) * 1.6;
          col += sunColor * pow(sun, 8.0) * 0.12 * haze;
          gl_FragColor = vec4(col, 1.0);
        }
      `
    });
    this.sky = new THREE.Mesh(geo, material);
    this.scene.add(this.sky);

    const starGeo = new THREE.BufferGeometry();
    const starPos = [];
    const rng = mulberry32(this.seed + 91);
    for (let i = 0; i < 1100; i++) {
      const theta = rng() * TAU, phi = Math.acos(randRange(rng, -0.05, 0.98));
      const r = 760;
      starPos.push(Math.cos(theta) * Math.sin(phi) * r, Math.cos(phi) * r, Math.sin(theta) * Math.sin(phi) * r);
    }
    starGeo.setAttribute('position', new THREE.Float32BufferAttribute(starPos, 3));
    this.stars = new THREE.Points(starGeo, new THREE.PointsMaterial({ color: 0xdcecff, size: 2.0, transparent: true, opacity: 0, depthWrite: false, sizeAttenuation: false }));
    this.scene.add(this.stars);

    const glowTexture = makeGlowTexture();
    this.sunSprite = new THREE.Sprite(new THREE.SpriteMaterial({ map: glowTexture, color: 0xffe9b0, transparent: true, blending: THREE.AdditiveBlending, depthWrite: false }));
    this.sunSprite.scale.set(120, 120, 1);
    this.scene.add(this.sunSprite);
    this.moonSprite = new THREE.Sprite(new THREE.SpriteMaterial({ map: glowTexture, color: 0xdde8ff, transparent: true, depthWrite: false, opacity: 0.7 }));
    this.moonSprite.scale.set(48, 48, 1);
    this.scene.add(this.moonSprite);
  }

  buildLights() {
    this.hemi = new THREE.HemisphereLight(0xcfe8ff, 0x3c4a2a, 1.1);
    this.scene.add(this.hemi);
    this.sun = new THREE.DirectionalLight(0xfff0c8, 2.6);
    this.sun.castShadow = true;
    this.sun.shadow.mapSize.set(2048, 2048);
    this.sun.shadow.camera.near = 1;
    this.sun.shadow.camera.far = 190;
    this.sun.shadow.camera.left = -52;
    this.sun.shadow.camera.right = 52;
    this.sun.shadow.camera.top = 52;
    this.sun.shadow.camera.bottom = -52;
    this.sun.shadow.bias = -0.0007;
    this.sun.shadow.normalBias = 0.06;
    this.scene.add(this.sun);
    this.sun.target = new THREE.Object3D();
    this.scene.add(this.sun.target);
    this.fill = new THREE.DirectionalLight(0x8fcad4, 0.35);
    this.scene.add(this.fill);
    this.scene.fog = new THREE.FogExp2(0xb8d4c8, 0.0034);
  }

  buildClouds() {
    const puff = new THREE.SphereGeometry(1, 8, 6);
    const entries = [];
    const rng = mulberry32(this.seed + 301);
    const geoParts = [];
    for (let i = 0; i < 8; i++) {
      const g = puff.clone().scale(randRange(rng, 5, 14), randRange(rng, 2, 5), randRange(rng, 5, 12));
      g.translate(randRange(rng, -14, 14), randRange(rng, -1.5, 1.5), randRange(rng, -9, 9));
      geoParts.push(g);
    }
    const merged = mergeGeometries(geoParts.map(g => g.index ? g.toNonIndexed() : g));
    const material = new THREE.MeshStandardMaterial({ color: 0xf5fbff, transparent: true, opacity: 0.7, roughness: 1, depthWrite: false, flatShading: true });
    for (let i = 0; i < 26; i++) {
      entries.push({ x: randRange(rng, -HALF, HALF), y: randRange(rng, 52, 92), z: randRange(rng, -HALF, HALF), rot: rng() * TAU, scale: randRange(rng, 0.7, 1.5) });
    }
    this.cloudMesh = instancedFrom(merged, material, entries, { shadow: false, cull: false });
    this.cloudMesh.renderOrder = 2;
    this.scene.add(this.cloudMesh);
  }

  treeGeometry(variant) {
    const trunk = colorGeo(new THREE.CylinderGeometry(0.22, 0.38, 3.4, 6).translate(0, 1.7, 0), 0x5c4531);
    const parts = [trunk];
    const greens = variant === 1 ? [0x3f6b3d, 0x527c46, 0x335c37] : variant === 2 ? [0x4a5d3c, 0x5d7246, 0x3c5234] : [0x2f5d43, 0x3d704e, 0x28523b];
    const rng = mulberry32(this.seed + variant * 71);
    const n = variant === 2 ? 5 : 3;
    for (let i = 0; i < n; i++) {
      const r = randRange(rng, 1.2, 2.2);
      const canopy = new THREE.IcosahedronGeometry(r, 0);
      canopy.scale(1, randRange(rng, 0.7, 1.1), 1);
      canopy.translate(randRange(rng, -1.1, 1.1), 3.1 + i * 0.7 + randRange(rng, -0.3, 0.3), randRange(rng, -0.9, 0.9));
      parts.push(colorGeo(canopy, greens[i % greens.length]));
    }
    const merged = mergeGeometries(parts.map(g => g.index ? g.toNonIndexed() : g));
    merged.computeVertexNormals();
    return merged;
  }

  rockGeometry() {
    const parts = [];
    const rng = mulberry32(this.seed + 55);
    for (let i = 0; i < 3; i++) {
      const g = new THREE.DodecahedronGeometry(randRange(rng, 0.7, 1.4), 0);
      g.scale(randRange(rng, 0.7, 1.3), randRange(rng, 0.5, 1.0), randRange(rng, 0.7, 1.3));
      g.rotateY(rng() * TAU);
      g.translate(randRange(rng, -0.6, 0.6), randRange(rng, 0.1, 0.6), randRange(rng, -0.6, 0.6));
      parts.push(colorGeo(g, new THREE.Color().setHSL(0.12, 0.06, randRange(rng, 0.28, 0.42))));
    }
    return mergeGeometries(parts.map(g => g.index ? g.toNonIndexed() : g));
  }

  grassGeometry() {
    const parts = [];
    for (let i = 0; i < 4; i++) {
      const g = new THREE.ConeGeometry(0.055, randRange(0.35, 0.8), 3);
      g.translate((i % 2 ? 0.12 : -0.1) * (i + 1) * 0.25, 0.25, (i % 3 - 1) * 0.12);
      g.rotateZ((i - 1.5) * 0.18);
      parts.push(colorGeo(g, i % 2 ? 0x6d8a3c : 0x4f7133));
    }
    return mergeGeometries(parts.map(g => g.index ? g.toNonIndexed() : g));
  }

  buildFoliage() {
    const rng = mulberry32(this.seed + 1234);
    const treeEntries = [[], [], []];
    const rockEntries = [];
    const grassEntries = [];
    const bushEntries = [];
    const glowEntries = [];
    for (let i = 0; i < 1400; i++) {
      const x = randRange(rng, -HALF * 0.94, HALF * 0.94);
      const z = randRange(rng, -HALF * 0.94, HALF * 0.94);
      const h = this.heightAt(x, z);
      if (h < WATER_LEVEL + 1.2) continue;
      const biome = this.biomeAt(x, z);
      const slope = this.slopeAt(x, z);
      if (slope > 1.1) continue;
      if (biome === 'forest' && treeEntries[0].length + treeEntries[1].length + treeEntries[2].length < 300) {
        if (chance(rng, 0.55)) {
          treeEntries[Math.floor(rng() * 3)].push({ x, y: h - 0.2, z, rot: rng() * TAU, scale: randRange(rng, 0.75, 1.65), color: new THREE.Color().setHSL(0.27, 0.25, randRange(rng, 0.85, 1.1)) });
        } else bushEntries.push({ x, y: h, z, rot: rng() * TAU, scale: randRange(rng, 0.5, 1.1) });
      } else if (biome === 'grassland') {
        if (chance(rng, 0.13) && treeEntries[2].length < 100) treeEntries[2].push({ x, y: h - 0.2, z, rot: rng() * TAU, scale: randRange(rng, 0.65, 1.1) });
        else grassEntries.push({ x, y: h, z, rot: rng() * TAU, scale: randRange(rng, 0.7, 1.4) });
      } else if (biome === 'marsh') {
        if (chance(rng, 0.25)) treeEntries[1].push({ x, y: h - 0.1, z, rot: rng() * TAU, scale: randRange(rng, 0.7, 1.2) });
        else grassEntries.push({ x, y: h, z, rot: rng() * TAU, scale: randRange(rng, 0.6, 1.2), color: new THREE.Color().setHSL(0.36, 0.3, 0.65) });
        if (chance(rng, 0.08)) glowEntries.push({ x, y: h + 0.35, z, rot: rng() * TAU, scale: randRange(rng, 0.4, 0.9) });
      } else if (biome === 'desert') {
        if (chance(rng, 0.05)) rockEntries.push({ x, y: h, z, rot: rng() * TAU, scale: randRange(rng, 0.5, 1.4) });
        else if (chance(rng, 0.08)) grassEntries.push({ x, y: h, z, rot: rng() * TAU, scale: randRange(rng, 0.4, 0.7), color: new THREE.Color().setHSL(0.16, 0.4, 0.8) });
      } else if (biome === 'mountain') {
        rockEntries.push({ x, y: h, z, rot: rng() * TAU, scale: randRange(rng, 0.6, 2.2) });
      } else if (biome === 'beach') {
        if (chance(rng, 0.12)) rockEntries.push({ x, y: h, z, rot: rng() * TAU, scale: randRange(rng, 0.3, 0.8) });
      }
    }
    // extra grass near spawn basin
    for (let i = 0; i < 500; i++) {
      const x = randRange(rng, -HALF * 0.75, HALF * 0.75), z = randRange(rng, -HALF * 0.75, HALF * 0.75);
      const h = this.heightAt(x, z);
      if (h > WATER_LEVEL + 1 && this.slopeAt(x, z) < 0.9) grassEntries.push({ x, y: h, z, rot: rng() * TAU, scale: randRange(rng, 0.6, 1.3) });
    }
    const leafMat = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.92, metalness: 0 });
    for (let v = 0; v < 3; v++) {
      if (!treeEntries[v].length) continue;
      const mesh = instancedFrom(this.treeGeometry(v), leafMat, treeEntries[v]);
      mesh.userData.type = 'tree';
      this.scene.add(mesh);
      this.treeMeshes = this.treeMeshes || [];
      this.treeMeshes.push(mesh);
    }
    const rockMat = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.95, flatShading: true });
    this.rockMesh = instancedFrom(this.rockGeometry(), rockMat, rockEntries);
    this.scene.add(this.rockMesh);
    const grassMat = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 1, side: THREE.DoubleSide });
    this.grassMesh = instancedFrom(this.grassGeometry(), grassMat, grassEntries, { shadow: false });
    this.scene.add(this.grassMesh);
    const bushGeo = new THREE.IcosahedronGeometry(1, 0).scale(1.1, 0.6, 1.1);
    const bushMat = new THREE.MeshStandardMaterial({ color: 0x3e6039, roughness: 0.95, flatShading: true });
    this.bushMesh = instancedFrom(bushGeo, bushMat, bushEntries, { shadow: false });
    this.scene.add(this.bushMesh);
    const glowGeo = new THREE.IcosahedronGeometry(0.18, 0).translate(0, 0.2, 0);
    const glowMat = new THREE.MeshStandardMaterial({ color: 0x7ef0c0, emissive: 0x2fc98a, emissiveIntensity: 1.8, roughness: 0.4 });
    this.glowMesh = instancedFrom(glowGeo, glowMat, glowEntries, { shadow: false });
    this.scene.add(this.glowMesh);
  }

  buildShelters() {
    this.shelters = [];
    const rng = mulberry32(this.seed + 888);
    const rockMat = new THREE.MeshStandardMaterial({ color: 0x4c5148, roughness: 0.96, flatShading: true });
    const darkMat = new THREE.MeshBasicMaterial({ color: 0x070b0a });
    for (let i = 0; i < 9; i++) {
      let pos = null;
      for (let tries = 0; tries < 120; tries++) {
        const x = randRange(rng, -HALF * 0.8, HALF * 0.8);
        const z = randRange(rng, -HALF * 0.8, HALF * 0.8);
        const h = this.heightAt(x, z);
        const b = this.biomeAt(x, z);
        if (h > WATER_LEVEL + 2 && this.slopeAt(x, z) < 0.6 && ['forest', 'mountain', 'grassland', 'marsh'].includes(b)) { pos = { x, y: h, z, biome: b }; break; }
      }
      if (!pos) continue;
      const g = new THREE.Group();
      g.position.set(pos.x, pos.y, pos.z);
      const rot = rng() * TAU;
      g.rotation.y = rot;
      const arch = new THREE.Mesh(new THREE.TorusGeometry(2.6, 0.82, 5, 8, Math.PI), rockMat);
      arch.position.y = 0.4;
      arch.rotation.z = 0;
      arch.castShadow = true; arch.receiveShadow = true;
      g.add(arch);
      const sideL = new THREE.Mesh(new THREE.DodecahedronGeometry(1.6, 0), rockMat);
      sideL.position.set(-2.7, 0.9, 0); sideL.scale.set(0.9, 1.5, 1.1); sideL.castShadow = true; g.add(sideL);
      const sideR = sideL.clone(); sideR.position.x = 2.7; g.add(sideR);
      const hollow = new THREE.Mesh(new THREE.CircleGeometry(1.9, 12), darkMat);
      hollow.position.set(0, 1.3, -1.1);
      hollow.rotation.y = Math.PI;
      g.add(hollow);
      this.scene.add(g);
      this.shelters.push({ ...pos, group: g, radius: 5 });
    }
  }

  buildPlants() {
    const rng = mulberry32(this.seed + 4321);
    this.plantNodes = [];
    this.plantMax = 170;
    const entries = [];
    let tries = 0;
    while (this.plantNodes.length < this.plantMax && tries++ < 4000) {
      const x = randRange(rng, -HALF * 0.92, HALF * 0.92), z = randRange(rng, -HALF * 0.92, HALF * 0.92);
      const h = this.heightAt(x, z);
      if (h < WATER_LEVEL + 0.8 || this.slopeAt(x, z) > 1.0) continue;
      const b = this.biomeAt(x, z);
      if (!['grassland', 'forest', 'marsh', 'beach'].includes(b)) continue;
      const kind = b === 'marsh' ? 'fungus' : b === 'beach' ? 'kelp' : chance(rng, 0.45) ? 'berry' : 'frond';
      const color = kind === 'berry' ? new THREE.Color().setHSL(randRange(rng, 0.9, 1.02) % 1, 0.6, 0.55) : kind === 'fungus' ? new THREE.Color(0x7fe6c7) : new THREE.Color().setHSL(0.24, 0.45, 0.48);
      const node = { id: this.plantNodes.length, x, y: h, z, kind, nutrition: 8 + rng() * 8, available: true, regrow: 0, color, index: entries.length, scale: 0.8 + rng() * 0.6 };
      this.plantNodes.push(node);
      entries.push({ x, y: h, z, rot: rng() * TAU, scale: node.scale, color });
    }
    const fruitGeo = new THREE.IcosahedronGeometry(0.22, 0).translate(0, 0.45, 0);
    const fruitMat = new THREE.MeshStandardMaterial({ color: 0xffffff, emissive: 0x1d451c, emissiveIntensity: 0.35, roughness: 0.45, vertexColors: false });
    this.fruitMesh = instancedFrom(fruitGeo, fruitMat, entries, { shadow: false });
    this.scene.add(this.fruitMesh);
    const stemGeo = new THREE.CylinderGeometry(0.025, 0.04, 0.55, 4).translate(0, 0.27, 0);
    const stemMat = new THREE.MeshStandardMaterial({ color: 0x3f6b35, roughness: 0.9 });
    this.stemMesh = instancedFrom(stemGeo, stemMat, entries.map(e => ({ ...e, scale: e.scale * 0.8 })), { shadow: false });
    this.scene.add(this.stemMesh);
    this._plantMatrix = new THREE.Matrix4();
  }

  buildParticles() {
    const makePoints = (count, color, size, opacity) => {
      const geo = new THREE.BufferGeometry();
      const arr = new Float32Array(count * 3);
      for (let i = 0; i < count; i++) { arr[i * 3] = (Math.random() - 0.5) * 90; arr[i * 3 + 1] = Math.random() * 40; arr[i * 3 + 2] = (Math.random() - 0.5) * 90; }
      geo.setAttribute('position', new THREE.BufferAttribute(arr, 3));
      const mat = new THREE.PointsMaterial({ color, size, transparent: true, opacity, depthWrite: false, sizeAttenuation: true });
      const pts = new THREE.Points(geo, mat);
      pts.frustumCulled = false;
      return pts;
    };
    this.rain = makePoints(2200, 0xa9d8e8, 0.10, 0.55);
    this.rain.visible = false;
    this.scene.add(this.rain);
    this.snow = makePoints(1500, 0xffffff, 0.16, 0.8);
    this.snow.visible = false;
    this.scene.add(this.snow);
    this.fireflies = makePoints(110, 0xc8ff9a, 0.16, 0.0);
    this.fireflies.visible = true;
    this.scene.add(this.fireflies);
    this.pollen = makePoints(140, 0xfff0b8, 0.075, 0.5);
    this.scene.add(this.pollen);
  }

  applyEpoch(epoch) {
    this.epoch = epoch;
    const palettes = [
      { top: 0x3f78a8, bottom: 0xcfe5d4, fog: 0xb8d4c8, water: [0x0b3b45, 0x2c8b8c] },
      { top: 0x557f96, bottom: 0xd8cfb2, fog: 0xc9c2a8, water: [0x194a52, 0x3f948d] },
      { top: 0x6b5a7a, bottom: 0xd9b7a0, fog: 0xc9a99a, water: [0x2a3c53, 0x4f8e96] },
      { top: 0x2d3e63, bottom: 0xa7c6c8, fog: 0x9cb7b7, water: [0x0a2838, 0x2d6e7c] }
    ];
    const pal = palettes[epoch % palettes.length];
    this.palette = pal;
    this.waterUniforms.uDeep.value.setHex(pal.water[0]);
    this.waterUniforms.uShallow.value.setHex(pal.water[1]);
    if (this.scene.fog) this.scene.fog.color.setHex(pal.fog);
  }

  randomLandPoint(rng, biomeList, near = null, radius = 9999) {
    for (let i = 0; i < 160; i++) {
      let x, z;
      if (near) { const a = rng() * TAU, r = Math.sqrt(rng()) * radius; x = near.x + Math.cos(a) * r; z = near.z + Math.sin(a) * r; }
      else { x = randRange(rng, -HALF * 0.92, HALF * 0.92); z = randRange(rng, -HALF * 0.92, HALF * 0.92); }
      const h = this.heightAt(x, z);
      if (h < WATER_LEVEL + 0.9 || h > 30) continue;
      const b = this.biomeAt(x, z);
      if (biomeList && !biomeList.includes(b)) continue;
      if (this.slopeAt(x, z) > 1.0) continue;
      return { x, y: h, z, biome: b };
    }
    return { x: 0, y: Math.max(WATER_LEVEL + 2, this.heightAt(0, 0)), z: 0, biome: this.biomeAt(0, 0) };
  }

  findSpawn() {
    const rng = mulberry32(this.seed + 999);
    let best = null;
    for (let i = 0; i < 400; i++) {
      const x = randRange(rng, -HALF * 0.6, HALF * 0.6), z = randRange(rng, -HALF * 0.6, HALF * 0.6);
      const h = this.heightAt(x, z);
      if (h < WATER_LEVEL + 1.4 || h > 16) continue;
      const b = this.biomeAt(x, z);
      if (!['grassland', 'forest', 'beach'].includes(b)) continue;
      if (this.slopeAt(x, z) > 0.35) continue;
      const nearWater = this.nearestWater(x, z, 55);
      if (!nearWater) continue;
      const score = -Math.abs(h - 7) - (nearWater.dist * 0.05) + (b === 'grassland' ? 2 : 0);
      if (!best || score > best.score) best = { x, y: h, z, score, biome: b };
    }
    return best || { x: 0, y: Math.max(2, this.heightAt(0, 0)), z: 0, biome: 'grassland' };
  }

  nearestWater(x, z, maxDist = 60) {
    let best = null;
    for (let r = 2; r < maxDist; r += 4) {
      for (let a = 0; a < 16; a++) {
        const ang = a / 16 * TAU;
        const sx = x + Math.cos(ang) * r, sz = z + Math.sin(ang) * r;
        if (this.heightAt(sx, sz) < WATER_LEVEL - 0.2) {
          const score = r;
          if (!best || score < best.dist) best = { x: sx, z: sz, dist: r };
        }
      }
      if (best) return best;
    }
    return null;
  }

  nearestShelter(pos) {
    let best = null, bd = Infinity;
    for (const s of this.shelters) {
      const d = (s.x - pos.x) ** 2 + (s.z - pos.z) ** 2;
      if (d < bd) { bd = d; best = s; }
    }
    return best ? { ...best, dist: Math.sqrt(bd) } : null;
  }

  nearestPlant(pos, radius = 7) {
    let best = null, bd = radius * radius;
    for (const p of this.plantNodes) {
      if (!p.available) continue;
      const d = (p.x - pos.x) ** 2 + (p.z - pos.z) ** 2;
      if (d < bd) { bd = d; best = p; }
    }
    return best;
  }

  consumePlant(node) {
    if (!node || !node.available) return 0;
    node.available = false;
    node.regrow = 50 + Math.random() * 40;
    this.updatePlantInstance(node);
    return node.nutrition;
  }

  updatePlantInstance(node) {
    const m = this._plantMatrix;
    const scale = node.available ? node.scale : 0.0001;
    m.makeScale(scale, scale, scale);
    m.setPosition(node.x, node.y, node.z);
    this.fruitMesh.setMatrixAt(node.index, m);
    this.fruitMesh.instanceMatrix.needsUpdate = true;
    this.stemMesh.setMatrixAt(node.index, m);
    this.stemMesh.instanceMatrix.needsUpdate = true;
  }

  update(dt, focus) {
    this.focus.copy(focus);
    this.time += dt / this.dayLength;
    if (this.time >= 1) { this.time -= 1; this.day++; }
    this.seasonTime += dt;
    if (this.seasonTime > this.seasonLength) {
      this.seasonTime = 0;
      this.seasonIndex = (this.seasonIndex + 1) % 4;
    }
    this.yearFloat += dt * 0.012;
    const sunAngle = (this.time - 0.25) * TAU;
    const sunY = Math.sin(sunAngle);
    const sunX = Math.cos(sunAngle) * 0.7;
    const sunZ = Math.cos(sunAngle) * 0.45;
    const dayAmt = smoothstep(-0.12, 0.22, sunY);
    const dusk = clamp(1 - Math.abs(sunY) * 3.2, 0, 1);
    const pal = this.palette;
    const top = new THREE.Color(pal.top).lerp(new THREE.Color(0x070c1c), 1 - dayAmt);
    const bottom = new THREE.Color(pal.bottom).lerp(new THREE.Color(0x111a2c), 1 - dayAmt).lerp(new THREE.Color(0xe8a06a), dusk * 0.45 * dayAmt);
    this.skyUniforms.topColor.value.copy(top);
    this.skyUniforms.bottomColor.value.copy(bottom);
    this.skyUniforms.sunDir.value.set(sunX, sunY, sunZ).normalize();
    this.skyUniforms.sunColor.value.copy(new THREE.Color(0xffcf82).lerp(new THREE.Color(0xff8c4d), dusk));
    this.stars.material.opacity = clamp(1 - dayAmt * 1.4, 0, 0.95);
    this.stars.position.copy(focus);
    this.sunSprite.position.copy(focus).add(new THREE.Vector3(sunX, sunY, sunZ).multiplyScalar(620));
    this.sunSprite.material.opacity = clamp(dayAmt * 1.6, 0, 1);
    this.sunSprite.material.color.setHex(dusk > 0.4 ? 0xffa060 : 0xfff0c0);
    this.moonSprite.position.copy(focus).add(new THREE.Vector3(-sunX, -sunY, -sunZ).multiplyScalar(620));
    this.moonSprite.material.opacity = clamp((1 - dayAmt) * 0.85, 0, 0.85);

    this.sun.position.copy(focus).add(new THREE.Vector3(sunX, Math.max(0.15, sunY), sunZ).multiplyScalar(80));
    this.sun.target.position.copy(focus);
    this.sun.target.updateMatrixWorld();
    this.sun.intensity = 0.15 + dayAmt * 2.6;
    this.sun.color.copy(new THREE.Color(0xfff0c8).lerp(new THREE.Color(0xff9b5a), dusk * 0.7));
    this.hemi.intensity = 0.18 + dayAmt * 1.05;
    this.hemi.color.copy(new THREE.Color(0xcfe8ff).lerp(new THREE.Color(0x495377), 1 - dayAmt));
    this.fill.position.copy(focus).add(new THREE.Vector3(-40, 30, -30));

    this.waterUniforms.uTime.value += dt;
    this.waterUniforms.uSun.value.copy(this.skyUniforms.sunColor.value);
    this.water.position.y = WATER_LEVEL + Math.sin(performance.now() * 0.0006) * 0.02;

    // flora seasonal tint
    if (this.treeMeshes) {
      const tint = [new THREE.Color(0xffffff), new THREE.Color(0xeaf2c8), new THREE.Color(0xe9c08c), new THREE.Color(0xcfd8ea)][this.seasonIndex];
      for (const m of this.treeMeshes) m.material.color.copy(tint);
    }
    if (this.grassMesh) {
      const tint = [new THREE.Color(0xffffff), new THREE.Color(0xe9e6b5), new THREE.Color(0xdcc090), new THREE.Color(0xc6cddd)][this.seasonIndex];
      this.grassMesh.material.color.copy(tint);
    }
    if (this.fireflies) {
      this.fireflies.material.opacity = (1 - dayAmt) * 0.75 * (this.seasonIndex === 3 ? 0.2 : 1);
      this.fireflies.position.set(focus.x, 0, focus.z);
      const pos = this.fireflies.geometry.attributes.position;
      for (let i = 0; i < pos.count; i++) {
        const y = pos.getY(i);
        pos.setY(i, y + dt * 0.18);
        if (y > 18) pos.setY(i, this.heightAt(focus.x + pos.getX(i), focus.z + pos.getZ(i)) + 0.5 + Math.random() * 3);
      }
      pos.needsUpdate = true;
    }
    if (this.pollen) this.pollen.position.set(focus.x, 0, focus.z);
    if (this.cloudMesh) {
      this.cloudMesh.rotation.y += dt * 0.0018;
      this.cloudMesh.position.x = ((this.cloudMesh.position.x + dt * 0.8) + 200) % 100 - 50;
    }
    this.updateWeather(dt, focus, dayAmt);
    // plant regrowth
    for (const p of this.plantNodes) {
      if (!p.available) {
        p.regrow -= dt;
        if (p.regrow <= 0) { p.available = true; this.updatePlantInstance(p); }
      }
    }
    // hazard label
    const biome = this.biomeAt(focus.x, focus.z);
    if (biome === 'desert' && dayAmt > 0.5) this.hazard = { label: 'Scorching heat', drain: 'thirst', rate: 0.35 };
    else if (this.seasonIndex === 3 && sunY < 0.1) this.hazard = { label: 'Freezing night', drain: 'stamina', rate: 0.25 };
    else if (biome === 'marsh') this.hazard = { label: 'Toxic spores', drain: 'health', rate: 0.02 };
    else this.hazard = null;
    if (this.sunSprite.material.opacity < 0.05) this.sunSprite.visible = false; else this.sunSprite.visible = true;
    this.stars.visible = this.stars.material.opacity > 0.02;
  }

  updateWeather(dt, focus, dayAmt) {
    const w = this.weather;
    w.timer -= dt;
    if (w.timer <= 0) {
      w.timer = 35 + Math.random() * 60;
      const r = Math.random();
      const season = this.seasonIndex;
      if (season === 3) w.type = r < 0.48 ? 'snow' : r < 0.7 ? 'overcast' : r < 0.9 ? 'fog' : 'storm';
      else if (season === 2) w.type = r < 0.28 ? 'rain' : r < 0.5 ? 'overcast' : r < 0.64 ? 'fog' : 'clear';
      else if (season === 1) w.type = r < 0.14 ? 'storm' : r < 0.32 ? 'rain' : 'clear';
      else w.type = r < 0.3 ? 'rain' : r < 0.48 ? 'overcast' : r < 0.58 ? 'fog' : 'clear';
      w.label = { clear: 'Clear skies', overcast: 'Overcast', rain: 'Rain', storm: 'Thunderstorm', fog: 'Mist', snow: 'Snowfall' }[w.type];
      w.intensity = w.type === 'clear' ? 0 : w.type === 'overcast' ? 0.3 : w.type === 'fog' ? 0.55 : w.type === 'snow' ? 0.8 : 1;
    }
    const rainOn = w.type === 'rain' || w.type === 'storm';
    this.rain.visible = rainOn;
    this.snow.visible = w.type === 'snow';
    if (rainOn) {
      const pos = this.rain.geometry.attributes.position;
      const intensity = w.type === 'storm' ? 1 : 0.65;
      for (let i = 0; i < pos.count; i++) {
        let y = pos.getY(i) - dt * (22 + (i % 7) * 2);
        if (y < -2) y = 34 + Math.random() * 10;
        pos.setY(i, y);
      }
      pos.needsUpdate = true;
      this.rain.position.set(focus.x, 0, focus.z);
      this.rain.material.opacity = 0.5 * intensity;
    }
    if (w.type === 'snow') {
      const pos = this.snow.geometry.attributes.position;
      for (let i = 0; i < pos.count; i++) {
        let y = pos.getY(i) - dt * 2.2;
        if (y < -1) y = 30 + Math.random() * 8;
        pos.setY(i, y);
        pos.setX(i, pos.getX(i) + Math.sin(performance.now() * 0.001 + i) * dt * 0.6);
        if (Math.abs(pos.getX(i)) > 45) pos.setX(i, (Math.random() - 0.5) * 90);
      }
      pos.needsUpdate = true;
      this.snow.position.set(focus.x, 0, focus.z);
    }
    if (w.type === 'storm') {
      this.flash = Math.max(0, this.flash - dt * 3.5);
      if (Math.random() < dt * 0.35) { this.flash = 1; this.lightningAt = focus.clone(); }
      if (this.flash > 0) this.hemi.intensity += this.flash * 3.2;
    } else this.flash = Math.max(0, this.flash - dt * 3);
    const fogBase = { clear: 0.0026, overcast: 0.0036, rain: 0.0055, storm: 0.0075, fog: 0.012, snow: 0.008 }[w.type] || 0.003;
    const fogColor = new THREE.Color(this.palette.fog).lerp(new THREE.Color(0x28323a), 1 - dayAmt * 0.8);
    this.scene.fog.color.copy(fogColor);
    this.scene.fog.density = damp(this.scene.fog.density, fogBase, 0.3, dt);
    this.foam.material.opacity = 0;
  }
}

function makeGlowTexture() {
  const c = document.createElement('canvas');
  c.width = c.height = 128;
  const ctx = c.getContext('2d');
  const g = ctx.createRadialGradient(64, 64, 0, 64, 64, 64);
  g.addColorStop(0, 'rgba(255,255,255,1)');
  g.addColorStop(0.25, 'rgba(255,255,255,0.9)');
  g.addColorStop(0.55, 'rgba(255,255,255,0.25)');
  g.addColorStop(1, 'rgba(255,255,255,0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, 128, 128);
  const tex = new THREE.CanvasTexture(c);
  return tex;
}

// Living ecosystem: individual creatures, fear, decisions, combat, feeding, breeding.
import * as THREE from 'three';
import { mergeGeometries } from 'three/addons/utils/BufferGeometryUtils.js';
import { CreatureRig } from './creature.js';
import { deriveStats, mutateGenome, crossoverGenome, normalizeGenome, makeSpecies, buildStartingSpecies, genomeColor, geneticDistance } from './genome.js';
import { clamp, lerp, damp, mulberry32, randRange, chance, pick, TAU, fmt, makeSpeciesName, makeCommonName, avg } from './util.js';
import { WATER_LEVEL } from './world.js';

export const FEAR_LEVELS = [
  { max: 0.14, label: 'Calm', color: '#7fe0a8', icon: '○' },
  { max: 0.3, label: 'Alert', color: '#d8e876', icon: '◔' },
  { max: 0.48, label: 'Nervous', color: '#f0c15a', icon: '◑' },
  { max: 0.68, label: 'Frightened', color: '#f08a4b', icon: '◕' },
  { max: 0.86, label: 'Panicked', color: '#ef5b4c', icon: '●' },
  { max: 1.01, label: 'Terrorized', color: '#d92c6b', icon: '✸' }
];
export function fearInfo(v) { return FEAR_LEVELS.find(l => v < l.max) || FEAR_LEVELS[FEAR_LEVELS.length - 1]; }

const STATE_LABEL = {
  idle: 'Resting', wander: 'Roaming', graze: 'Grazing', drink: 'Drinking', hunt: 'Hunting',
  chase: 'Chasing', flee: 'Fleeing', sleep: 'Sleeping', seekShelter: 'Seeking shelter',
  mate: 'Courting', follow: 'Following parent', socialize: 'Socialising', scavenge: 'Scavenging',
  eat: 'Feeding', attack: 'Fighting', dead: 'Dead', drink: 'Drinking', protect: 'Protecting'
};

const rng = mulberry32(20261111);

export class Agent {
  constructor(eco, species, genome, pos, opts = {}) {
    this.eco = eco;
    this.game = eco.game;
    this.world = eco.world;
    this.species = species;
    this.genome = normalizeGenome(genome);
    this.stats = deriveStats(this.genome);
    this.id = 'a' + Math.floor(Math.random() * 1e9).toString(36);
    this.sex = Math.random() < 0.5 ? 'F' : 'M';
    this.age = opts.age ?? randRange(Math.random, 0.8, Math.max(1, this.stats.adultAge * 2.2));
    this.growth = opts.growth ?? clamp(0.42 + this.age / this.stats.adultAge * 0.58, 0.35, 1);
    this.health = opts.health ?? this.stats.maxHealth;
    this.stamina = this.stats.maxStamina;
    this.hunger = opts.hunger ?? randRange(Math.random, 8, 40);
    this.thirst = opts.thirst ?? randRange(Math.random, 8, 40);
    this.fatigue = randRange(Math.random, 0, 24);
    this.fear = 0;
    this.fearTarget = 0;
    this.pain = 0;
    this.memory = { pain: 0, playerTerror: 0 };
    this.state = opts.state || 'wander';
    this.stateTimer = randRange(Math.random, 1, 4);
    this.scanTimer = Math.random() * 0.4;
    this.attackTimer = 0;
    this.breedCooldown = randRange(Math.random, 8, 24);
    this.eatCooldown = 0;
    this.speed = 0;
    this.heading = Math.random() * TAU;
    this.turn = 0;
    this.position = new THREE.Vector3(pos.x, this.world.heightAt(pos.x, pos.z), pos.z);
    this.home = new THREE.Vector3(pos.x, 0, pos.z);
    this.territoryRadius = 18 + Math.random() * 38;
    this.parentId = opts.parentId || null;
    this.offspring = 0;
    this.kills = 0;
    this.attacks = 0;
    this.injuries = { leg: 0, eye: 0, jaw: 0, body: 0 };
    this.dead = false;
    this.deadTimer = 0;
    this.flying = !!this.genome.wings && species.habitat === 'mountain' && (opts.fly ?? Math.random() < 0.75);
    this.swimming = false;
    this.selected = false;
    this.target = null;
    this.threat = null;
    this.prey = null;
    this.waterPoint = null;
    this.carcass = null;
    this.plants = null;
    this.mateTarget = null;
    this.groupCenter = null;
    this.attackFlash = 0;
    this.callTimer = randRange(Math.random, 2, 12);
    this.vocal = opts.vocal || 1;
    this.scaleBase = 0.95 * Math.pow(this.genome.size, 0.84);
    this.rig = new CreatureRig(this.genome, { scale: this.scaleBase * this.growth });
    this.rig.root.position.copy(this.position);
    this.rig.root.rotation.y = this.heading;
    this.rig.root.userData.agent = this;
    if (this.flying) this.altitude = 5 + Math.random() * 4;
    this.eco.scene.add(this.rig.root);
    this.nickname = opts.nickname || (this.species.common.split(' ')[0] + ' ' + ['I', 'II', 'III', 'IV', 'V', 'VI', 'VII', 'VIII'][Math.floor(Math.random() * 8)]);
  }

  get displayName() { return this.nickname; }
  get fearLevel() { return fearInfo(this.fear); }
  get stateLabel() { return STATE_LABEL[this.state] || this.state; }
  get isPredator() { return this.genome.diet === 'carnivore'; }
  get isPrey() { return this.genome.diet === 'herbivore'; }
  get sizeRatio() { return this.genome.size; }
  get canBreed() { return this.age >= this.stats.adultAge * 0.82 && this.health > this.stats.maxHealth * 0.55 && this.hunger < 62 && this.thirst < 65 && this.breedCooldown <= 0; }

  update(dt) {
    if (this.dead) {
      this.deadTimer -= dt;
      this.rig.update(dt);
      if (this.deadTimer <= 0 && this.rig.root.parent) {
        this.rig.dispose();
      }
      return;
    }
    this.attackFlash = Math.max(0, this.attackFlash - dt * 3);
    const yRate = 0.012; // game-years per real second
    this.age += dt * yRate;
    this.breedCooldown -= dt;
    this.eatCooldown -= dt;
    this.attackTimer -= dt;
    this.scanTimer -= dt;
    this.stateTimer -= dt;
    this.pain = Math.max(0, this.pain - dt * 0.16);
    this.memory.pain = Math.max(0, this.memory.pain - dt * 0.002);
    this.breedCooldown = Math.max(-1, this.breedCooldown);

    const sizeFactor = clamp(this.genome.size, 0.6, 2.4);
    const foodNeed = this.state === 'sleep' ? 0.35 : 1;
    this.hunger = clamp(this.hunger + dt * this.stats.metabolismRate * 1.35 * foodNeed, 0, 110);
    this.thirst = clamp(this.thirst + dt * (0.85 + this.stats.metabolismRate * 0.9) * foodNeed, 0, 110);
    if (this.state !== 'sleep') this.fatigue = clamp(this.fatigue + dt * 0.55, 0, 105);
    if (this.hunger < 25 && this.thirst < 30 && this.health > 0) this.health = clamp(this.health + dt * 0.65, 0, this.stats.maxHealth);
    if (this.hunger > 92) this.health = clamp(this.health - dt * 0.7, 0, this.stats.maxHealth);
    if (this.thirst > 94) this.health = clamp(this.health - dt * 1.1, 0, this.stats.maxHealth);
    if (this.state === 'sleep') { this.fatigue = clamp(this.fatigue - dt * 4.5, 0, 100); this.stamina = clamp(this.stamina + dt * 8, 0, this.stats.maxStamina); }
    else if (this.speed > this.stats.walk * 0.8) this.stamina = clamp(this.stamina - dt * 1.8, 0, this.stats.maxStamina);
    else this.stamina = clamp(this.stamina + dt * 1.5, 0, this.stats.maxStamina);

    if (this.scanTimer <= 0) {
      this.scanTimer = 0.28 + Math.random() * 0.26;
      this.scan();
    }
    this.updateFear(dt);
    this.decide(dt);
    this.move(dt);
    this.updateRig(dt);

    if (this.health <= 0) this.die('wounds');
    if (this.age > this.stats.lifeSpan) this.die('old age');
  }

  scan() {
    const vision = this.stats.vision * (1 - clamp(this.fear * 0.2, 0, 0.2));
    let threat = null, threatScore = 0;
    let prey = null, preyScore = -Infinity;
    let mate = null, mateDist = Infinity;
    let herdSum = new THREE.Vector3();
    let herdCount = 0;
    let groupThreat = 0;
    for (const other of this.eco.agents) {
      if (other === this || other.dead) continue;
      const dx = other.position.x - this.position.x, dz = other.position.z - this.position.z;
      const d2 = dx * dx + dz * dz;
      if (d2 > vision * vision) continue;
      const d = Math.sqrt(d2);
      const same = other.species.id === this.species.id;
      if (same) {
        if (other.age < other.stats.adultAge * 0.8) herdSum.add(other.position); else herdSum.add(other.position);
        herdCount++;
        if (other.state === 'flee' && d < 14) groupThreat = Math.max(groupThreat, 0.35);
        if (!mate && other.canBreed && this.canBreed && d < 22 && other.sex !== this.sex) { mate = other; mateDist = d; }
        continue;
      }
      const otherStats = other.stats;
      const sizeDiff = other.genome.size / this.genome.size;
      const dangerous = (other.isPredator || other.genome.diet === 'omnivore' && other.genome.aggression > 0.55) && sizeDiff > 0.78;
      if (dangerous) {
        let score = (1 - d / vision) * (0.5 + Math.min(1.8, sizeDiff) * 0.65) * (0.4 + other.genome.aggression);
        if (other.state === 'hunt' || other.state === 'chase' || other.state === 'attack') score *= 1.6;
        if (other.fear > 0.4) score *= 0.7;
        if (score > threatScore) { threatScore = score; threat = other; }
      }
      const canEat = this.genome.diet === 'carnivore' || (this.genome.diet === 'omnivore' && this.hunger > 55);
      if (canEat && other.genome.size < this.genome.size * 1.04 && other.genome.size > this.genome.size * 0.28) {
        const score = (1 - d / vision) * 2 - other.genome.size * 0.6 + (other.health < other.stats.maxHealth * 0.5 ? 0.6 : 0);
        if (score > preyScore) { preyScore = score; prey = other; }
      }
    }
    // Player is a powerful, unpredictable apex presence.
    const p = this.eco.game.player;
    if (p && p.alive && p.position) {
      const dx = p.position.x - this.position.x, dz = p.position.z - this.position.z;
      const d = Math.hypot(dx, dz);
      if (d < vision * 1.25) {
        const danger = p.danger || 0;
        const playerThreat = (1 - clamp(d / (vision * 1.25), 0, 1)) * (0.38 + danger * 1.55 + (p.genome.size / this.genome.size) * 0.2);
        if (playerThreat > threatScore) { threatScore = playerThreat; threat = p; }
        if ((this.genome.diet === 'carnivore' || this.genome.diet === 'omnivore' && this.hunger > 60) && danger < 0.65 && p.genome.size < this.genome.size * 1.2 && d < this.stats.huntRadius) {
          const score = (1 - d / this.stats.huntRadius) * 2.2 + (p.health < p.maxHealth * 0.5 ? 0.8 : 0);
          if (score > preyScore) { preyScore = score; prey = p; }
        }
      }
    }
    if (herdCount) this.groupCenter = herdSum.multiplyScalar(1 / herdCount);
    else this.groupCenter = null;
    this.threat = threat;
    this.threatScore = threatScore;
    this.prey = prey;
    this.mateTarget = mate;
    this.groupThreat = groupThreat;
    this.waterPoint = this.thirst > 30 || this.state === 'drink' ? this.world.nearestWater(this.position.x, this.position.z, 70) : this.waterPoint;
    this.plants = this.world.nearestPlant(this.position, 13);
    this.carcass = this.eco.nearestCarcass(this.position, 24);
    this.shelter = this.world.nearestShelter(this.position);
  }

  updateFear(dt) {
    let target = this.stats.fearBias * 0.18;
    if (this.threat) target += this.threatScore * (0.9 + this.stats.fearBias * 0.4);
    if (this.groupThreat) target += this.groupThreat;
    if (this.pain > 0) target += this.pain * 0.55;
    if (this.injuries.leg || this.injuries.body) target += 0.16;
    if (this.health < this.stats.maxHealth * 0.35) target += 0.18;
    if (this.memory.playerTerror > 0) target += this.memory.playerTerror * 0.2;
    const courage = this.genome.aggression * 0.22 + this.genome.boldness * 0.16;
    if (this.threat && this.genome.aggression > 0.7 && this.genome.size > (this.threat.genome?.size || 1) * 0.92) target *= 0.64;
    target = clamp(target - courage, 0, 1);
    const panicGain = target > this.fear ? 1.5 + this.genome.fearfulness * 1.2 : 0.45 + this.stats.fearDecay;
    this.fear = damp(this.fear, target, panicGain, dt);
    if (this.fear > 0.82) this.memory.playerTerror = clamp(this.memory.playerTerror + dt * 0.3, 0, 1);
    if (this.threat === this.eco.game.player && this.fear > 0.5) this.eco.game.playerDanger = Math.min(1, this.eco.game.playerDanger + dt * 0.06);
  }

  decide(dt) {
    if (this.dead) return;
    const threat = this.threat;
    const threatDist = threat ? Math.hypot(threat.position.x - this.position.x, threat.position.z - this.position.z) : Infinity;
    const panic = this.fear > 0.58;
    if (this.stateTimer > 0 && !['flee', 'attack', 'chase'].includes(this.state)) {
      // keep current low-priority action until its timer expires
    } else {
      this.stateTimer = 1 + Math.random() * 2.4;
      if (panic && threat && threatDist < 34) {
        this.setState(this.genome.aggression > 0.75 && this.genome.size > (threat.genome?.size || 1) * 1.02 && this.fear < 0.8 ? 'attack' : 'flee');
        this.target = threat;
      } else if (this.fatigue > 74 && this.fear < 0.35) {
        const shelter = this.world.nearestShelter(this.position);
        if (shelter && shelter.dist < 30 && this.world.temperatureAt(this.position.x, this.position.z) < 0.42) {
          this.setState('seekShelter'); this.target = shelter;
        } else this.setState('sleep');
      } else if (this.thirst > 58 && this.waterPoint) {
        this.setState('drink'); this.target = this.waterPoint;
      } else if (this.hunger > 48) {
        if (this.genome.diet === 'scavenger' && this.carcass) { this.setState('scavenge'); this.target = this.carcass; }
        else if ((this.genome.diet === 'carnivore' || this.genome.diet === 'omnivore') && this.prey) { this.setState('hunt'); this.target = this.prey; }
        else if (this.plants) { this.setState('graze'); this.target = this.plants; }
        else if (this.carcass) { this.setState('scavenge'); this.target = this.carcass; }
        else this.setState('wander');
      } else if (this.canBreed && this.mateTarget) {
        this.setState('mate'); this.target = this.mateTarget;
      } else if (this.parentId && this.eco.agents.some(a => a.id === this.parentId && !a.dead)) {
        const parent = this.eco.agents.find(a => a.id === this.parentId);
        if (parent && Math.hypot(parent.position.x - this.position.x, parent.position.z - this.position.z) < 30) { this.setState('follow'); this.target = parent; }
        else this.setState('wander');
      } else if (this.genome.sociability > 0.62 && this.groupCenter && Math.random() < 0.65) {
        this.setState('socialize'); this.target = this.groupCenter;
      } else if (this.state === 'sleep' || this.state === 'drink') {
        this.setState('wander');
      } else {
        this.setState(Math.random() < 0.52 ? 'wander' : 'idle');
      }
    }
    // persistent actions
    if (!threat || threatDist > 40) {
      if (this.state === 'flee') { this.stateTimer = 0; }
    }
    if (this.state === 'hunt' && this.prey) {
      this.target = this.prey;
      const d = Math.hypot(this.prey.position.x - this.position.x, this.prey.position.z - this.position.z);
      if (d < this.stats.reach + 1.5 && this.attackTimer <= 0) this.attack(this.prey);
      if (!this.prey || this.prey.dead) { this.stateTimer = 0; this.prey = null; }
    }
    if (this.state === 'attack' && this.target) {
      const target = this.target;
      const d = Math.hypot(target.position.x - this.position.x, target.position.z - this.position.z);
      if (d > 2.4 && d < 26) { this.state = 'chase'; }
      if (d <= this.stats.reach + 1.8 && this.attackTimer <= 0) this.attack(target);
      if (this.fear > 0.92) this.setState('flee');
      if (!target || target.dead || target.health <= 0) this.stateTimer = 0;
    }
    if (this.state === 'chase') {
      if (!this.target || this.target.dead) this.stateTimer = 0;
      else {
        const d = Math.hypot(this.target.position.x - this.position.x, this.target.position.z - this.position.z);
        if (d < this.stats.reach + 1.6 && this.attackTimer <= 0) this.attack(this.target);
        if (d > 45) { this.state = 'wander'; this.stateTimer = 0; }
      }
    }
    if (this.state === 'graze') {
      if (!this.plants || !this.plants.available) this.plants = this.world.nearestPlant(this.position, 18);
      if (this.plants) this.target = this.plants;
    }
    if (this.state === 'drink') {
      if (!this.waterPoint) this.waterPoint = this.world.nearestWater(this.position.x, this.position.z, 60);
      if (this.waterPoint) this.target = this.waterPoint;
    }
    if (this.state === 'scavenge') {
      this.carcass = this.eco.nearestCarcass(this.position, 30);
      if (this.carcass) this.target = this.carcass; else this.stateTimer = 0;
    }
    if (this.state === 'mate' && this.mateTarget) {
      const d = Math.hypot(this.mateTarget.position.x - this.position.x, this.mateTarget.position.z - this.position.z);
      this.target = this.mateTarget;
      if (d < this.stats.bodyRadius * 2 + 2 && this.breedCooldown <= 0) this.breed(this.mateTarget);
    }
    if (this.state === 'follow' && this.target && this.target.dead) this.stateTimer = 0;
  }

  setState(state) {
    if (this.state === state) { this.stateTimer = 1.5 + Math.random() * 2; return; }
    this.state = state;
    this.stateTimer = 1.2 + Math.random() * 2.8;
  }

  move(dt) {
    let desired = new THREE.Vector3();
    let targetSpeed = 1.1;
    const threat = this.threat;
    if (this.state === 'flee' && threat) {
      desired.set(this.position.x - threat.position.x, 0, this.position.z - threat.position.z);
      targetSpeed = this.stats.sprint * (0.82 + this.fear * 0.35);
      if (this.groupCenter && this.genome.sociability > 0.6) desired.addScaledVector(this.groupCenter.clone().sub(this.position), 0.25);
    } else if (['hunt', 'chase', 'attack'].includes(this.state) && this.target) {
      desired.set(this.target.position.x - this.position.x, 0, this.target.position.z - this.position.z);
      targetSpeed = this.stats.sprint * (0.82 + this.genome.aggression * 0.25);
    } else if (this.state === 'sleep') {
      targetSpeed = 0;
    } else if (this.state === 'drink') {
      if (this.waterPoint) {
        desired.set(this.waterPoint.x - this.position.x, 0, this.waterPoint.z - this.position.z);
        const d = desired.length();
        targetSpeed = d > 2.5 ? this.stats.walk * 0.85 : 0;
        if (d < 3.2) {
          this.consumeWater(dt);
          desired.set(0, 0, 0);
        }
      } else targetSpeed = 0;
    } else if (this.state === 'graze' && this.plants) {
      desired.set(this.plants.x - this.position.x, 0, this.plants.z - this.position.z);
      const d = desired.length();
      targetSpeed = d > 1.8 ? this.stats.walk * 0.9 : 0;
      if (d < 2.4) this.consumePlant(this.plants);
    } else if (this.state === 'scavenge' && this.carcass) {
      desired.set(this.carcass.position.x - this.position.x, 0, this.carcass.position.z - this.position.z);
      const d = desired.length();
      targetSpeed = d > 2 ? this.stats.walk * 1.2 : 0;
      if (d < 2.6) this.consumeCarcass(this.carcass, dt);
    } else if (this.state === 'mate' && this.target) {
      desired.set(this.target.position.x - this.position.x, 0, this.target.position.z - this.position.z);
      targetSpeed = desired.length() > 2.5 ? this.stats.walk * 0.8 : 0;
    } else if (this.state === 'seekShelter' && this.target) {
      desired.set(this.target.x - this.position.x, 0, this.target.z - this.position.z);
      const d = desired.length();
      targetSpeed = d > 2 ? this.stats.walk : 0;
      if (d < 3) { this.setState('sleep'); this.stateTimer = 10; }
    } else if ((this.state === 'socialize' || this.state === 'follow') && this.target) {
      const tx = this.target.position?.x ?? this.target.x, tz = this.target.position?.z ?? this.target.z;
      desired.set(tx - this.position.x, 0, tz - this.position.z);
      const d = desired.length();
      targetSpeed = d > 4 ? this.stats.walk * 0.9 : 0;
    } else if (this.state === 'wander') {
      if (!this._wanderTarget || this._wanderTimer <= 0 || Math.hypot(this._wanderTarget.x - this.position.x, this._wanderTarget.z - this.position.z) < 2) {
        const r = 8 + Math.random() * 22;
        const a = Math.random() * TAU;
        this._wanderTarget = { x: this.home.x + Math.cos(a) * r, z: this.home.z + Math.sin(a) * r };
        this._wanderTimer = 6 + Math.random() * 8;
      }
      this._wanderTimer -= dt;
      desired.set(this._wanderTarget.x - this.position.x, 0, this._wanderTarget.z - this.position.z);
      targetSpeed = this.stats.walk * 0.6;
    } else {
      targetSpeed = 0;
      if (this.groupCenter && this.genome.sociability > 0.6 && Math.random() < 0.02) {
        desired.set(this.groupCenter.x - this.position.x, 0, this.groupCenter.z - this.position.z);
        targetSpeed = this.stats.walk * 0.4;
      }
    }
    // separation
    for (const other of this.eco.nearbyAgents(this.position, 7)) {
      if (other === this || other.dead) continue;
      const dx = this.position.x - other.position.x, dz = this.position.z - other.position.z;
      const d2 = dx * dx + dz * dz;
      if (d2 < 0.001) continue;
      const d = Math.sqrt(d2);
      const push = (2.4 + (this.genome.size + other.genome.size) * 0.6) / d;
      if (d < 7) desired.add(new THREE.Vector3(dx / d * push, 0, dz / d * push));
    }
    const pp = this.eco.game.player;
    if (pp && pp.alive) {
      const dx = this.position.x - pp.position.x, dz = this.position.z - pp.position.z;
      const d = Math.hypot(dx, dz);
      if (d < 4 + pp.genome.size * 1.5 && d > 0.01) desired.add(new THREE.Vector3(dx / d * 2, 0, dz / d * 2));
    }
    const nextX = this.position.x + Math.sin(this.heading) * this.speed * dt;
    const nextZ = this.position.z + Math.cos(this.heading) * this.speed * dt;
    if (this.world.slopeAt(nextX, nextZ) > 1.8 && !this.flying) targetSpeed *= 0.35;
    const terrain = this.world.heightAt(this.position.x, this.position.z);
    const waterDepth = WATER_LEVEL - terrain;
    if (waterDepth > 0.8) {
      this.swimming = true;
      if (this.state !== 'flee' && this.state !== 'drink' && waterDepth > 2.2) {
        // steer back toward land
        const w = this.world.nearestWater(this.position.x, this.position.z, 12);
        if (w) desired.set(this.position.x - w.x, 0, this.position.z - w.z);
      }
    } else this.swimming = false;
    if (this.injuries.leg) targetSpeed *= 0.62;
    if (this.fear > 0.7) targetSpeed *= 1.08;
    if (this.fatigue > 85) targetSpeed *= 0.65;
    if (this.state === 'sleep') targetSpeed = 0;
    const desiredLen = desired.length();
    if (desiredLen > 0.001) {
      desired.normalize();
      const targetHeading = Math.atan2(desired.x, desired.z);
      let delta = ((targetHeading - this.heading + Math.PI * 3) % (Math.PI * 2)) - Math.PI;
      const turnRate = (1.5 + this.stats.agility * 4.2) * (this.swimming ? 0.65 : 1);
      const turn = clamp(delta, -turnRate * dt, turnRate * dt);
      this.heading += turn;
      this.turn = damp(this.turn, turn / Math.max(dt, 0.001), 8, dt);
      this.speed = damp(this.speed, targetSpeed, 3, dt);
      this.position.x += Math.sin(this.heading) * this.speed * dt;
      this.position.z += Math.cos(this.heading) * this.speed * dt;
    } else {
      this.speed = damp(this.speed, 0, 4, dt);
      this.turn = damp(this.turn, 0, 6, dt);
    }
    const lim = 298;
    this.position.x = clamp(this.position.x, -lim, lim);
    this.position.z = clamp(this.position.z, -lim, lim);
    const h = this.world.heightAt(this.position.x, this.position.z);
    const depth = WATER_LEVEL - h;
    if (this.flying) {
      const base = Math.max(h, WATER_LEVEL);
      this.altitude = damp(this.altitude, this.state === 'flee' ? 10 : 5.5, 1.4, dt);
      this.position.y = base + this.altitude + Math.sin(performance.now() * 0.001 + this.heading) * 0.35;
      this.swimming = false;
    } else if (depth > 0.4) {
      this.position.y = WATER_LEVEL - 0.4 + Math.sin(performance.now() * 0.0012 + this.heading) * 0.06;
      this.swimming = true;
    } else {
      this.position.y = h;
      this.swimming = false;
    }
    this.rig.root.position.copy(this.position);
    // smooth clamp in water to avoid drowning
    if (this.swimming) this.fatigue = clamp(this.fatigue + dt * 0.25, 0, 100);
  }

  updateRig(dt) {
    this.rig.setState({
      speed: this.speed,
      state: this.state === 'graze' ? 'eat' : this.state === 'scavenge' ? 'eat' : this.state,
      fear: this.fear,
      turn: this.turn,
      swimming: this.swimming,
      flying: this.flying && this.state !== 'sleep',
      injuredLeg: this.injuries.leg,
      hurt: this.attackFlash
    });
    this.rig.root.rotation.y = this.heading;
    this.rig.update(dt);
    if (this.growth < 1) {
      this.growth = clamp(this.growth + dt * 0.00055, 0.35, 1);
      this.rig.setScale(this.scaleBase * this.growth);
    }
  }

  consumeWater(dt) {
    this.thirst = clamp(this.thirst - dt * 16, 0, 110);
    this.stamina = clamp(this.stamina + dt * 6, 0, this.stats.maxStamina);
  }

  consumePlant(node) {
    if (this.eatCooldown > 0 || !node || !node.available) return;
    this.eatCooldown = 1.4;
    const nut = this.world.consumePlant(node);
    this.hunger = clamp(this.hunger - nut * 0.8, 0, 110);
    this.health = clamp(this.health + num(2), 0, this.stats.maxHealth);
    this.eco.populationFood -= nut;
  }

  consumeCarcass(carcass, dt) {
    if (!carcass || carcass.consumed || this.eatCooldown > 0) return;
    this.eatCooldown = 0.9;
    const nut = Math.min(carcass.nutrition, 9);
    carcass.nutrition -= nut;
    carcass.eat(2.2);
    this.hunger = clamp(this.hunger - nut * 0.85, 0, 110);
    this.health = clamp(this.health + 1.5, 0, this.stats.maxHealth);
    if (carcass.nutrition <= 0.5) carcass.destroy();
    this.eco.emit('feed', `${this.species.common} scavenges ${carcass.sourceName}.`, this.species);
  }

  attack(target) {
    if (target.dead || this.attackTimer > 0) return;
    this.attackTimer = this.stats.attackCooldown;
    this.attacks++;
    this.attackFlash = 1;
    const dmg = this.stats.bite * (0.7 + Math.random() * 0.5) + (this.genome.clawSize > 0.5 ? this.stats.claw * 0.5 : 0);
    if (target === this.eco.game.player || target.takeDamage) {
      if (target.takeDamage) target.takeDamage(dmg, this, pick(Math.random, ['leg', 'body', 'body', 'eye', 'jaw']));
      else if (target === this.eco.game.player) {
        target.takeDamage(dmg, this);
        this.eco.game.playerDanger = Math.min(1, this.eco.game.playerDanger + 0.22);
      }
    }
    this.eco.emit('attack', `${this.species.common} bites ${target.displayName || 'the player'} for ${Math.round(dmg)} damage.`, this.species);
    this.eco.spawnHit(target.position, Math.round(dmg), this.genome.hue1);
    if (target.health <= 0) {
      this.kills++;
      this.hunger = clamp(this.hunger - 24, 0, 110);
      this.eco.emit('kill', `${this.species.common} kills ${target.displayName || 'its prey'}.`, this.species);
    }
  }

  breed(mate) {
    if (this.breedCooldown > 0 || mate.breedCooldown > 0 || this.dead || mate.dead) return;
    if (this.eco.agents.length >= this.eco.cap) return;
    this.breedCooldown = 28 + Math.random() * 35;
    mate.breedCooldown = 28 + Math.random() * 35;
    this.offspring++;
    this.eco.reproduce(this, mate);
    this.eco.emit('birth', `${this.species.common} produces offspring with ${mate.displayName}.`, this.species);
    this.eco.game.ui?.toast(`New ${this.species.common} born`, 'birth');
  }

  takeDamage(amount, attacker, part) {
    if (this.dead) return;
    const armor = clamp(this.stats.armorRating, 0, 0.75);
    const dmg = Math.max(1, amount * (1 - armor));
    this.health -= dmg;
    this.pain = clamp(this.pain + 0.18, 0, 1);
    this.attackFlash = 1;
    this.fear = clamp(this.fear + 0.45, 0, 1);
    this.memory.pain = clamp(this.memory.pain + 0.35, 0, 1);
    if (part && Math.random() < 0.28) {
      if (part === 'leg' && !this.injuries.leg) { this.injuries.leg = 1; this.rig.setInjury('leg'); this.eco.emit('injury', `${this.displayName} is lamed by a bite.`, this.species); }
      else if (part === 'eye' && !this.injuries.eye) { this.injuries.eye = 1; this.rig.setInjury('eye'); this.eco.emit('injury', `${this.displayName} loses an eye.`, this.species); }
      else if (part === 'jaw' && !this.injuries.jaw) { this.injuries.jaw = 1; this.rig.setInjury('jaw'); this.eco.emit('injury', `${this.displayName}'s jaw is broken.`, this.species); }
      else this.injuries.body++;
    }
    if (attacker && attacker !== this) {
      this.threat = attacker;
      this.threatScore = 0.9;
      if (this.genome.aggression > 0.6 && !this.dead) { this.state = 'attack'; this.target = attacker; this.stateTimer = 4; }
      else { this.state = 'flee'; this.stateTimer = 6; this.target = attacker; }
    }
    this.eco.spawnHit(this.position, Math.round(dmg), 8);
    if (this.health <= 0) this.die('killed');
  }

  die(cause) {
    if (this.dead) return;
    this.dead = true;
    this.deadTimer = 3;
    this.health = 0;
    this.speed = 0;
    this.state = 'dead';
    this.rig.setState({ state: 'dead', dead: true, speed: 0 });
    this.eco.onDeath(this, cause);
  }

  inspect() {
    return {
      name: this.displayName, species: this.species, genome: this.genome, stats: this.stats,
      health: this.health, maxHealth: this.stats.maxHealth, hunger: this.hunger, thirst: this.thirst,
      stamina: this.stamina, maxStamina: this.stats.maxStamina, fatigue: this.fatigue,
      fear: this.fear, fearLabel: this.fearLevel.label, fearColor: this.fearLevel.color,
      state: this.stateLabel, age: this.age, injuries: this.injuries, sex: this.sex,
      growth: this.growth, offspring: this.offspring, kills: this.kills,
      canBreed: this.canBreed, flying: this.flying, swimming: this.swimming
    };
  }
}

function num(n) { return n; }

export class Carcass {
  constructor(eco, pos, sourceName, nutrition, genome) {
    this.eco = eco;
    this.position = pos.clone();
    this.position.y = eco.world.heightAt(pos.x, pos.z);
    this.sourceName = sourceName;
    this.nutrition = nutrition;
    this.consumed = false;
    this.age = 0;
    this.group = new THREE.Group();
    this.group.position.copy(this.position);
    const boneMat = new THREE.MeshStandardMaterial({ color: 0xcfc6ac, roughness: 0.7 });
    const meatMat = new THREE.MeshStandardMaterial({ color: 0x7d2b2b, roughness: 0.7 });
    const parts = [];
    const n = 5;
    for (let i = 0; i < n; i++) {
      const rib = new THREE.CylinderGeometry(0.04, 0.05, 0.8, 4);
      rib.rotateZ(Math.PI / 2);
      rib.translate((i - n / 2) * 0.18, 0.25 + Math.sin(i) * 0.08, 0);
      parts.push(rib);
    }
    parts.push(new THREE.SphereGeometry(0.3, 6, 5).scale(1.3, 0.7, 1.6).translate(0, 0.2, 0));
    const boneMesh = new THREE.Mesh(mergeGeometries(parts.map(p => p.index ? p.toNonIndexed() : p)), boneMat);
    boneMesh.castShadow = true;
    boneMesh.receiveShadow = true;
    const meat = new THREE.Mesh(new THREE.DodecahedronGeometry(0.28, 0), meatMat);
    meat.scale.set(1.4, 0.7, 1.1);
    meat.position.set(0.05, 0.2, 0.15);
    this.group.add(boneMesh, meat);
    this.group.rotation.y = Math.random() * TAU;
    eco.scene.add(this.group);
  }
  eat(amount) { this.nutrition -= amount; if (this.nutrition <= 0) this.destroy(); }
  update(dt) {
    this.age += dt;
    if (this.age > 90) this.destroy();
    if (this.age > 30) this.group.position.y -= dt * 0.004;
  }
  destroy() {
    if (this.consumed) return;
    this.consumed = true;
    this.eco.scene.remove(this.group);
    this.group.traverse(o => { if (o.geometry) o.geometry.dispose(); });
  }
}

export class Ecosystem {
  constructor(game, world, seed = 1234) {
    this.game = game;
    this.scene = game.scene;
    this.world = world;
    this.seed = seed;
    this.rng = mulberry32(seed + 77);
    this.agents = [];
    this.carcasses = [];
    this.events = [];
    this.species = [];
    this.lineage = [];
    this.cap = 34;
    this.populationFood = 100;
    this.abstractTimer = 0;
    this.genesisYear = world.baseYear;
    this.onEvent = null;
    this.hitParticles = [];
    this.playerDanger = 0;
    this.stats = { births: 0, deaths: 0, kills: 0, speciesCount: 0, extinctCount: 0 };
    this.initSpecies();
  }

  initSpecies() {
    const species = buildStartingSpecies(this.rng);
    // compact species names to feel like a real survey catalogue
    for (const s of species) {
      s.originYear = this.genesisYear;
      s.lineageId = s.id;
      s.genome.id = s.id;
      this.lineage.push(this.lineageNode(s, null, this.genesisYear));
    }
    this.species = species;
  }

  registerPlayerSpecies(genome, name) {
    const g = normalizeGenome(genome);
    const sp = makeSpecies(this.rng, g, {
      name: 'Homo Aetheris', common: name || 'Aetherling', population: 1, generation: 1,
      originYear: this.world.baseYear + this.world.yearFloat, playerLineage: true, discovered: true,
      habitat: 'grassland', id: 'player_species'
    });
    sp.genome.id = sp.id;
    sp.lineageId = sp.id;
    this.playerSpecies = sp;
    this.species.unshift(sp);
    this.lineage.push(this.lineageNode(sp, null, this.world.baseYear));
    return sp;
  }

  lineageNode(sp, parentId, year) {
    return {
      id: sp.lineageId || sp.id, name: sp.name, common: sp.common, parentId: parentId || null,
      year, endYear: null, diet: sp.diet, color: sp.color, genome: sp.genome, population: sp.population,
      generation: sp.generation, extinct: false, isPlayer: !!sp.playerLineage, habitat: sp.habitat,
      event: sp.lineageEvent || ''
    };
  }

  spawnInitial(playerPos) {
    for (const sp of this.species) {
      if (sp.playerLineage) continue;
      const count = sp.population > 35 ? 5 : sp.population > 20 ? 4 : 2;
      for (let i = 0; i < count; i++) {
        this.spawnSpeciesAgent(sp, playerPos, 32 + Math.random() * 130);
      }
    }
  }

  spawnSpeciesAgent(sp, center, radius = 120) {
    if (this.agents.length >= this.cap) return null;
    const habitat = [sp.habitat, 'grassland', 'forest'].filter(Boolean);
    let pos = this.world.randomLandPoint(this.rng, habitat, center, radius);
    if (sp.genome.wings) pos = this.world.randomLandPoint(this.rng, ['mountain', 'grassland'], center, radius);
    const agent = new Agent(this, sp, mutateGenome(sp.genome, this.rng, 0.12), pos, {
      parentId: null
    });
    if (sp.diet === 'carnivore' && center) {
      const d = Math.hypot(agent.position.x - center.x, agent.position.z - center.z);
      if (d < 45) {
        agent.position.x += (agent.position.x - center.x) * 1.8;
        agent.position.z += (agent.position.z - center.z) * 1.8;
      }
    }
    this.agents.push(agent);
    return agent;
  }

  reproduce(parentA, parentB) {
    if (this.agents.length >= this.cap) return null;
    const childGenome = crossoverGenome(parentA.genome, parentB.genome, this.rng, 0.22);
    const child = new Agent(this, parentA.species, childGenome, {
      x: parentA.position.x + randRange(this.rng, -2, 2),
      z: parentA.position.z + randRange(this.rng, -2, 2)
    }, { age: 0.05, growth: 0.32, parentId: parentA.id, health: 25, hunger: 0, thirst: 0 });
    this.agents.push(child);
    parentA.species.population++;
    this.stats.births++;
    this.speciesDrift(parentA.species, childGenome);
    return child;
  }

  speciesDrift(sp, childGenome) {
    sp.generation++;
    if (this.rng() < 0.22) {
      const blended = {};
      for (const key of Object.keys(sp.genome)) {
        if (typeof sp.genome[key] === 'number') blended[key] = lerp(sp.genome[key], childGenome[key], 0.06);
      }
      blended.diet = sp.genome.diet;
      sp.genome = normalizeGenome(blended);
      sp.color = genomeColor(sp.genome);
    }
  }

  onDeath(agent, cause) {
    agent.species.population = Math.max(0, agent.species.population - 1);
    this.stats.deaths++;
    const carcass = new Carcass(this, agent.position, agent.species.common, 22 + agent.genome.size * 34, agent.genome);
    this.carcasses.push(carcass);
    if (this.carcasses.length > 9) { const old = this.carcasses.shift(); old.destroy(); }
    this.emit('death', `${agent.displayName} (${agent.species.common}) dies — ${cause}.`, agent.species);
    this.game.ui?.toast(`${agent.species.common} died`, 'death');
    if (agent.species.population <= 0) {
      agent.species.population = 0;
      this.emit('extinct', `Population of ${agent.species.name} has collapsed.`, agent.species);
    }
  }

  nearestAgent(pos, radius = 20, filter = null) {
    let best = null, bd = radius * radius;
    for (const a of this.agents) {
      if (a.dead) continue;
      if (filter && !filter(a)) continue;
      const d = (a.position.x - pos.x) ** 2 + (a.position.z - pos.z) ** 2;
      if (d < bd) { bd = d; best = a; }
    }
    return best ? { agent: best, dist: Math.sqrt(bd) } : null;
  }

  nearbyAgents(pos, radius = 8) {
    const out = [];
    const r2 = radius * radius;
    for (const a of this.agents) {
      if (a.dead) continue;
      const d = (a.position.x - pos.x) ** 2 + (a.position.z - pos.z) ** 2;
      if (d < r2) out.push(a);
    }
    return out;
  }

  nearestCarcass(pos, radius = 30) {
    let best = null, bd = radius * radius;
    for (const c of this.carcasses) {
      if (c.consumed) continue;
      const d = (c.position.x - pos.x) ** 2 + (c.position.z - pos.z) ** 2;
      if (d < bd) { bd = d; best = c; }
    }
    return best;
  }

  update(dt) {
    this.playerDanger = Math.max(0, this.playerDanger - dt * 0.018);
    for (const a of this.agents) a.update(dt);
    for (const c of this.carcasses) c.update(dt);
    this.updateHits(dt);
    this.abstractTimer -= dt;
    if (this.abstractTimer <= 0) {
      this.abstractTimer = 6 + Math.random() * 6;
      this.abstractPopulation(dt);
      this.cullDistant();
    }
    this.agents = this.agents.filter(a => !a.dead || a.deadTimer > 0 || a.rig.root.parent);
    this.carcasses = this.carcasses.filter(c => !c.consumed);
    this.species.forEach(sp => { sp.population = Math.max(0, sp.population); if (sp.population <= 2 && !sp.extinct && !sp.playerLineage) { sp.extinct = true; sp.extinctYear = this.world.baseYear + this.world.yearFloat; this.stats.extinctCount++; } });
    for (const node of this.lineage) {
      if (node.endYear == null && node.id !== (this.playerSpecies?.lineageId)) {
        const sp = this.species.find(s => (s.lineageId || s.id) === node.id);
        if (sp?.extinct) node.extinct = true;
      }
    }
    this.stats.speciesCount = this.species.filter(s => !s.extinct).length;
  }

  abstractPopulation(dt) {
    const player = this.game.player;
    for (const sp of this.species) {
      if (sp.extinct || sp.playerLineage) continue;
      const agents = this.agents.filter(a => a.species === sp && !a.dead).length;
      if (agents < 4 && sp.population > 13 && Math.random() < 0.6 && this.agents.length < this.cap) {
        const pos = player ? player.position : new THREE.Vector3();
        const a = this.spawnSpeciesAgent(sp, pos, 90 + Math.random() * 110);
        if (a) sp.population++;
      }
      sp.population += (Math.random() - 0.49) * 0.8;
      if (sp.population > 160) sp.population = 160;
    }
    if (this.carcasses.length > 6) { const old = this.carcasses.shift(); old.destroy(); }
  }

  cullDistant() {
    if (!this.game.player) return;
    for (let i = this.agents.length - 1; i >= 0; i--) {
      const a = this.agents[i];
      if (a.dead || a.species.playerLineage) continue;
      const d = a.position.distanceTo(this.game.player.position);
      if (d > 290 && this.agents.length > 22) {
        a.rig.dispose();
        this.agents.splice(i, 1);
      }
    }
  }

  spawnHit(pos, amount, hue) {
    this.game.particles?.burst(pos.clone().add(new THREE.Vector3(0, 1, 0)), amount > 10 ? 10 : 6, new THREE.Color().setHSL((hue % 360) / 360, 0.7, 0.5), 1.4);
  }

  updateHits(dt) {
    // flashes handled by particles; placeholder for future blood decals
  }

  emit(type, text, species, silent = false) {
    const ev = { id: Math.random().toString(36).slice(2), type, text, species: species?.name || null, common: species?.common || null, time: this.world.baseYear + this.world.yearFloat, day: this.world.day };
    this.events.unshift(ev);
    if (this.events.length > 80) this.events.pop();
    if (this.onEvent) this.onEvent(ev);
  }

  getSpecies(id) { return this.species.find(s => s.id === id || s.lineageId === id); }

  ecosystemReport() {
    const plants = this.world.plantNodes.filter(p => p.available).length;
    const herb = this.agents.filter(a => !a.dead && a.genome.diet === 'herbivore').length;
    const carn = this.agents.filter(a => !a.dead && a.genome.diet === 'carnivore').length;
    return {
      plants, herb, carn, carcasses: this.carcasses.length, agents: this.agents.filter(a => !a.dead).length,
      avgFear: avg(this.agents.filter(a => !a.dead).map(a => a.fear)),
      species: this.species.filter(s => !s.extinct)
    };
  }

  // ---------- Deep time ----------
  advanceEra(years, player) {
    const oldSpecies = this.species.map(s => ({ ...s, genome: { ...s.genome } }));
    const report = {
      years, fromYear: this.world.baseYear + this.world.yearFloat, toYear: this.world.baseYear + this.world.yearFloat + years,
      events: [], extinctions: [], splits: [], adaptations: [], playerAncestor: null, playerDescendant: null,
      climate: this.world.epoch
    };
    const epoch = Math.min(3, this.world.epoch + (years >= 1e6 ? 1 : years >= 1e5 ? 1 : 0));
    this.world.epoch = epoch;
    this.world.applyEpoch(epoch);
    this.world.baseYear += years;
    this.world.yearFloat = Math.max(0, this.world.yearFloat - years * 0.0001);
    const pressureCycle = [
      { predators: 0.6, competition: 0.5 },
      { cold: 0.5, scarcity: 0.6 },
      { arid: 0.7, scarcity: 0.4 },
      { predators: 0.4, competition: 0.8, cold: 0.4 }
    ][epoch];
    const gens = Math.max(2, Math.round(Math.log10(Math.max(10, years)) * 7));
    const newSpecies = [];
    for (const old of oldSpecies) {
      if (old.extinct) {
        report.extinctions.push(old);
        continue;
      }
      const isPlayer = old.playerLineage;
      let sp = { ...old, genome: { ...old.genome }, population: old.population };
      const localPressures = { ...pressureCycle };
      if (sp.habitat === 'desert') localPressures.arid = 0.9;
      if (sp.habitat === 'mountain') localPressures.cold = 0.8;
      if (sp.habitat === 'marsh') localPressures.competition = 0.7;
      const oldGenome = { ...sp.genome };
      for (let g = 0; g < gens; g++) sp.genome = mutateGenome(sp.genome, this.rng, 0.85, localPressures);
      // population dynamics across deep time
      const foodFactor = 0.55 + this.rng() * 1.25 - (localPressures.scarcity || 0) * 0.15;
      sp.population = Math.round(sp.population * foodFactor + this.rng() * 12);
      const extinct = sp.population < 9 && !isPlayer && this.rng() < 0.34;
      // lineages
      const parentNodeId = old.lineageId || old.id;
      for (const n of this.lineage) if (n.id === parentNodeId) n.endYear = report.toYear;
      if (extinct) {
        sp.extinct = true;
        sp.extinctYear = report.toYear;
        sp.population = 0;
        report.extinctions.push(sp);
        this.lineage.push(this.lineageNode({ ...sp, lineageEvent: 'extinction' }, parentNodeId, report.toYear));
        continue;
      }
      let evolved = sp;
      const split = !isPlayer && old.population > 24 && this.rng() < 0.34 && newSpecies.length < 5;
      if (split) {
        const daughterGenome = mutateGenome(sp.genome, this.rng, 1.3, localPressures);
        const daughter = makeSpecies(this.rng, daughterGenome, {
          name: makeSpeciesName(this.rng), common: makeCommonName(this.rng, daughterGenome.diet),
          population: Math.max(10, Math.round(sp.population * 0.4)), generation: 1,
          originYear: report.toYear, ancestorId: parentNodeId, habitat: pick(this.rng, ['forest', 'grassland', 'marsh', 'desert', 'mountain']),
          discovered: false, lineageEvent: 'speciation'
        });
        daughter.lineageId = 'sp_' + Math.floor(this.rng() * 1e9).toString(36);
        daughter.genome.id = daughter.lineageId;
        daughter.ancestorId = parentNodeId;
        daughter.population = Math.max(10, Math.round(daughter.population));
        newSpecies.push(daughter);
        this.lineage.push(this.lineageNode(daughter, parentNodeId, report.toYear));
        report.splits.push(daughter);
      }
      evolved = { ...sp, ancestorId: parentNodeId, originYear: report.toYear, generation: old.generation + gens };
      evolved.lineageId = 'sp_' + Math.floor(this.rng() * 1e9).toString(36);
      evolved.genome.id = evolved.lineageId;
      evolved.color = genomeColor(evolved.genome);
      evolved.diet = evolved.genome.diet;
      if (this.rng() < 0.45) {
        const oldName = evolved.common;
        evolved.common = makeCommonName(this.rng, evolved.genome.diet);
        if (this.rng() < 0.5) evolved.name = makeSpeciesName(this.rng);
        report.adaptations.push({ species: evolved, oldName, changes: this.describeChanges(oldGenome, evolved.genome) });
      } else {
        report.adaptations.push({ species: evolved, oldName: old.common, changes: this.describeChanges(oldGenome, evolved.genome) });
      }
      evolved.extinct = false;
      newSpecies.push(evolved);
      this.lineage.push(this.lineageNode(evolved, parentNodeId, report.toYear));
      if (isPlayer) {
        report.playerAncestor = old;
        report.playerDescendant = evolved;
      }
    }
    // ensure the player's lineage persists even if population crashed
    if (!report.playerDescendant) {
      const old = oldSpecies.find(s => s.playerLineage) || oldSpecies[0];
      const evolved = { ...old, genome: mutateGenome(old.genome, this.rng, 1.2, pressureCycle), population: Math.max(12, old.population), extinct: false, originYear: report.toYear, generation: old.generation + gens, lineageId: 'sp_' + Math.floor(this.rng() * 1e9).toString(36) };
      evolved.genome.id = evolved.lineageId;
      evolved.color = genomeColor(evolved.genome);
      evolved.diet = evolved.genome.diet;
      report.playerAncestor = old;
      report.playerDescendant = evolved;
      newSpecies.push(evolved);
      this.lineage.push(this.lineageNode(evolved, old.lineageId || old.id, report.toYear));
    }
    // migrate remaining living species before replacing current
    for (const s of this.species) {
      if (s.extinct) continue;
      if (!newSpecies.some(n => n.id === s.id || n.lineageId === s.lineageId)) newSpecies.push(s);
    }
    this.species = newSpecies;
    this.playerSpecies = this.species.find(s => s.playerLineage) || this.playerSpecies;
    if (this.playerSpecies) {
      this.playerSpecies.playerLineage = true;
      this.playerSpecies.population = Math.max(1, this.playerSpecies.population);
    }
    this.stats.speciesCount = this.species.filter(s => !s.extinct).length;
    report.speciesCount = this.stats.speciesCount;
    report.extinctCount = this.species.filter(s => s.extinct).length;
    report.epoch = epoch;
    report.newSpecies = newSpecies.filter(s => !oldSpecies.some(o => o.lineageId === s.lineageId));
    this.emit('era', `An era passes. ${fmt(years)} years reshape the world.`, null);
    return report;
  }

  describeChanges(a, b) {
    const out = [];
    const check = (key, label, fmtFn) => {
      const diff = b[key] - a[key];
      if (Math.abs(diff) > 0.12) out.push({ label, dir: diff > 0 ? 'up' : 'down', amount: Math.abs(diff), text: `${label} ${diff > 0 ? '+' : ''}${(diff * 100).toFixed(0)}%` });
    };
    check('size', 'body mass');
    check('speed', 'speed');
    check('armor', 'armor');
    check('teethSize', 'teeth');
    check('legLength', 'leg length');
    check('intelligence', 'intelligence');
    check('sociability', 'sociability');
    check('fearfulness', 'fear response');
    check('metabolism', 'metabolism');
    if (a.diet !== b.diet) out.push({ label: 'diet', text: `${a.diet} → ${b.diet}`, dir: 'shift' });
    if (a.wings !== b.wings) out.push({ label: 'wings', text: b.wings ? 'wings emerged' : 'wings lost', dir: 'shift' });
    if (out.length === 0) out.push({ label: 'microevolution', text: 'subtle drift in body proportions', dir: 'drift' });
    return out.slice(0, 4);
  }

  clearAgents() {
    for (const a of this.agents) { a.rig.dispose(); }
    this.agents = [];
    for (const c of this.carcasses) c.destroy();
    this.carcasses = [];
  }

  repopulate(playerPos) {
    this.clearAgents();
    for (const sp of this.species) {
      if (sp.extinct || sp.playerLineage) continue;
      const count = sp.population > 40 ? 5 : sp.population > 18 ? 4 : 2;
      for (let i = 0; i < count; i++) this.spawnSpeciesAgent(sp, playerPos, 45 + Math.random() * 150);
    }
  }
}

// Unified keyboard / mouse / touch input.
export class Input {
  constructor(canvas) {
    this.canvas = canvas;
    this.keys = new Set();
    this.pressed = new Set();
    this.move = { x: 0, y: 0 };
    this.look = { x: 0, y: 0 };
    this.zoom = 0;
    this.dragging = false;
    this.last = { x: 0, y: 0 };
    this.touch = { active: false, id: null, ox: 0, oy: 0, x: 0, y: 0 };
    this.camTouch = { id: null, x: 0, y: 0 };
    this.actionQueue = new Set();
    this.enabled = true;
    this.bind();
  }

  bind() {
    window.addEventListener('keydown', (e) => {
      if (!this.enabled) return;
      if (['Space', 'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'].includes(e.code)) e.preventDefault();
      if (!this.keys.has(e.code)) this.pressed.add(e.code);
      this.keys.add(e.code);
    });
    window.addEventListener('keyup', (e) => this.keys.delete(e.code));
    window.addEventListener('blur', () => this.keys.clear());
    const el = this.canvas;
    el.addEventListener('pointerdown', (e) => {
      if (e.pointerType === 'touch') return;
      this.dragging = true;
      this.last.x = e.clientX; this.last.y = e.clientY;
      el.setPointerCapture?.(e.pointerId);
    });
    window.addEventListener('pointerup', () => { this.dragging = false; });
    window.addEventListener('pointermove', (e) => {
      if (!this.dragging || e.pointerType === 'touch') return;
      this.look.x += e.clientX - this.last.x;
      this.look.y += e.clientY - this.last.y;
      this.last.x = e.clientX; this.last.y = e.clientY;
    });
    el.addEventListener('wheel', (e) => { this.zoom += Math.sign(e.deltaY) * 0.7; e.preventDefault(); }, { passive: false });
    el.addEventListener('contextmenu', (e) => e.preventDefault());

    // touch: left half joystick, right half camera drag
    el.addEventListener('touchstart', (e) => {
      for (const t of e.changedTouches) {
        if (t.clientX < window.innerWidth * 0.45 && this.touch.id === null) {
          this.touch = { active: true, id: t.identifier, ox: t.clientX, oy: t.clientY, x: t.clientX, y: t.clientY };
          this.showJoystick?.(t.clientX, t.clientY);
        } else if (this.camTouch.id === null) {
          this.camTouch = { id: t.identifier, x: t.clientX, y: t.clientY };
        }
      }
    }, { passive: true });
    el.addEventListener('touchmove', (e) => {
      for (const t of e.changedTouches) {
        if (t.identifier === this.touch.id) {
          this.touch.x = t.clientX; this.touch.y = t.clientY;
          this.moveJoystick?.(t.clientX, t.clientY);
        } else if (t.identifier === this.camTouch.id) {
          this.look.x += t.clientX - this.camTouch.x;
          this.look.y += t.clientY - this.camTouch.y;
          this.camTouch.x = t.clientX; this.camTouch.y = t.clientY;
        }
      }
    }, { passive: true });
    const end = (e) => {
      for (const t of e.changedTouches) {
        if (t.identifier === this.touch.id) { this.touch.id = null; this.touch.active = false; this.hideJoystick?.(); }
        if (t.identifier === this.camTouch.id) this.camTouch.id = null;
      }
    };
    el.addEventListener('touchend', end, { passive: true });
    el.addEventListener('touchcancel', end, { passive: true });
  }

  bindActions() {
    document.querySelectorAll('[data-action]').forEach(btn => {
      btn.addEventListener('pointerdown', (e) => {
        e.preventDefault();
        this.actionQueue.add(btn.dataset.action);
      });
    });
  }

  get forward() { return (this.keys.has('KeyW') || this.keys.has('ArrowUp')) ? 1 : (this.keys.has('KeyS') || this.keys.has('ArrowDown')) ? -1 : 0; }
  get strafe() { return (this.keys.has('KeyD') || this.keys.has('ArrowRight')) ? 1 : (this.keys.has('KeyA') || this.keys.has('ArrowLeft')) ? -1 : 0; }
  get sprint() { return this.keys.has('ShiftLeft') || this.keys.has('ShiftRight'); }
  get jump() { return this.keys.has('Space'); }
  get jumpPressed() { return this.pressed.has('Space'); }

  axis() {
    let x = this.strafe, y = this.forward;
    if (this.touch.active) {
      const dx = this.touch.x - this.touch.ox, dy = this.touch.y - this.touch.oy;
      const max = 58;
      x = Math.max(-1, Math.min(1, dx / max));
      y = Math.max(-1, Math.min(1, -dy / max));
    }
    const len = Math.hypot(x, y);
    if (len > 1) { x /= len; y /= len; }
    return { x, y };
  }

  consume() {
    const p = new Set(this.pressed);
    this.pressed.clear();
    const actions = new Set(this.actionQueue);
    this.actionQueue.clear();
    return { pressed: p, actions };
  }

  resetLook() { this.look.x = 0; this.look.y = 0; }
}

// Tiny procedural audio engine (WebAudio, no assets).
export class AudioEngine {
  constructor() {
    this.ctx = null;
    this.muted = false;
    this.master = null;
    this.ambient = null;
    this.stage = 'creature';
  }

  init() {
    if (this.ctx) { if (this.ctx.state === 'suspended') this.ctx.resume(); return; }
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    this.ctx = new AC();
    this.master = this.ctx.createGain();
    this.master.gain.value = 0.55;
    this.master.connect(this.ctx.destination);
    this.noiseBuffer = this.makeNoise(2);
    this.startAmbient();
  }

  makeNoise(seconds) {
    const len = this.ctx.sampleRate * seconds;
    const buf = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
    const data = buf.getChannelData(0);
    for (let i = 0; i < len; i++) data[i] = Math.random() * 2 - 1;
    return buf;
  }

  startAmbient() {
    if (!this.ctx) return;
    this.stopAmbient();
    const g = this.ctx.createGain();
    g.gain.value = 0.05;
    g.connect(this.master);
    // wind: filtered noise
    const src = this.ctx.createBufferSource();
    src.buffer = this.noiseBuffer;
    src.loop = true;
    const filter = this.ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = 420;
    const lfo = this.ctx.createOscillator();
    lfo.frequency.value = 0.08;
    const lfoGain = this.ctx.createGain();
    lfoGain.gain.value = 160;
    lfo.connect(lfoGain);
    lfoGain.connect(filter.frequency);
    src.connect(filter);
    filter.connect(g);
    src.start();
    lfo.start();
    // drone
    const osc = this.ctx.createOscillator();
    osc.type = 'sine';
    osc.frequency.value = 58;
    const og = this.ctx.createGain();
    og.gain.value = 0.018;
    osc.connect(og);
    og.connect(this.master);
    osc.start();
    this.ambient = { src, lfo, osc, g, filter };
  }

  stopAmbient() {
    if (!this.ambient) return;
    try { this.ambient.src.stop(); this.ambient.lfo.stop(); this.ambient.osc.stop(); } catch {}
    this.ambient = null;
  }

  setStage(stage) {
    this.stage = stage;
    if (this.ambient) {
      this.ambient.filter.frequency.value = stage === 'cell' ? 220 : 420;
      this.ambient.g.frequency = 0;
    }
  }

  setMuted(v) {
    this.muted = v;
    if (this.master) this.master.gain.value = v ? 0 : 0.55;
  }

  tone(freq, dur, type = 'sine', gain = 0.2, slides = 0) {
    if (!this.ctx || this.muted) return;
    const t = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, t);
    if (slides) osc.frequency.exponentialRampToValueAtTime(Math.max(20, freq + slides), t + dur);
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(gain, t + Math.min(0.03, dur * 0.25));
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    osc.connect(g); g.connect(this.master);
    osc.start(t); osc.stop(t + dur + 0.02);
  }

  noise(dur, freq = 1000, gain = 0.2, type = 'bandpass') {
    if (!this.ctx || this.muted) return;
    const t = this.ctx.currentTime;
    const src = this.ctx.createBufferSource();
    src.buffer = this.noiseBuffer;
    const filter = this.ctx.createBiquadFilter();
    filter.type = type;
    filter.frequency.value = freq;
    filter.Q.value = 0.8;
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(gain, t);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    src.connect(filter); filter.connect(g); g.connect(this.master);
    src.start(t); src.stop(t + dur);
  }

  play(name) {
    if (!this.ctx || this.muted) return;
    switch (name) {
      case 'step': this.noise(0.09, 220, 0.09); break;
      case 'stepBig': this.noise(0.16, 120, 0.18); this.tone(55, 0.14, 'sine', 0.12, -15); break;
      case 'eat': this.noise(0.18, 600, 0.12); this.tone(220, 0.1, 'triangle', 0.08, 40); break;
      case 'bite': this.noise(0.12, 1500, 0.18); this.tone(140, 0.12, 'square', 0.08, -60); break;
      case 'roar': this.tone(110, 0.7, 'sawtooth', 0.16, -60); this.tone(74, 0.8, 'square', 0.08, -30); this.noise(0.6, 300, 0.08); break;
      case 'hit': this.noise(0.1, 900, 0.22); this.tone(90, 0.15, 'triangle', 0.1, -40); break;
      case 'hurt': this.tone(180, 0.3, 'sawtooth', 0.12, -90); this.noise(0.2, 500, 0.1); break;
      case 'drink': this.tone(300, 0.12, 'sine', 0.08, 120); this.noise(0.2, 1200, 0.04); break;
      case 'ui': this.tone(660, 0.06, 'sine', 0.05, 40); break;
      case 'open': this.tone(330, 0.08, 'triangle', 0.06, 110); break;
      case 'evolve': [0, 0.12, 0.24, 0.42].forEach((d, i) => setTimeout(() => this.tone([330, 440, 554, 660][i], 0.5, 'sine', 0.12, 20), d * 1000)); break;
      case 'death': this.tone(180, 1.3, 'sawtooth', 0.16, -140); this.tone(90, 1.5, 'sine', 0.14, -60); break;
      case 'spawn': this.tone(520, 0.22, 'sine', 0.06, 220); break;
      case 'era': [0, 0.18, 0.36].forEach((d, i) => setTimeout(() => this.tone([196, 262, 392][i], 1.4, 'sine', 0.1, 5), d * 1000)); break;
      case 'click': this.tone(880, 0.04, 'square', 0.03, -120); break;
      case 'cellEat': this.tone(420, 0.12, 'sine', 0.08, 180); break;
      default: break;
    }
  }
}

// Directly controlled player creature.
import * as THREE from 'three';
import { CreatureRig } from './creature.js';
import { deriveStats, normalizeGenome, genomeColor } from './genome.js';
import { clamp, damp, lerp, TAU } from './util.js';
import { WATER_LEVEL } from './world.js';

export class Player {
  constructor(game, genome, pos) {
    this.game = game;
    this.world = game.world;
    this.genome = normalizeGenome(genome);
    this.stats = deriveStats(this.genome);
    this.id = 'player';
    this.displayName = 'You';
    this.sex = 'F';
    this.alive = true;
    this.dead = false;
    this.age = 2.1;
    this.health = this.stats.maxHealth;
    this.stamina = this.stats.maxStamina;
    this.hunger = 22;
    this.thirst = 18;
    this.fatigue = 6;
    this.dna = 0;
    this.evolutionPoints = 0;
    this.fear = 0;
    this.danger = 0;
    this.localThreat = 0;
    this.injuries = { leg: 0, eye: 0, jaw: 0, body: 0 };
    this.inventory = { berries: 3, meat: 0, herbs: 0, crystal: 0 };
    this.discoveredBiomes = new Set();
    this.discoveredSpecies = new Set();
    this.position = new THREE.Vector3(pos.x, this.world.heightAt(pos.x, pos.z), pos.z);
    this.heading = Math.PI * 0.35;
    this.velocityY = 0;
    this.airHeight = 0;
    this.grounded = true;
    this.flying = false;
    this.flightStamina = 0;
    this.swimming = false;
    this.speed = 0;
    this.turn = 0;
    this.animTimer = 0;
    this.attackTimer = 0;
    this.attackCooldown = 0;
    this.roarCooldown = 0;
    this.eatCooldown = 0;
    this.resting = false;
    this.restTime = 0;
    this.stepTimer = 0;
    this.deathTimer = 0;
    this.respawnTimer = 0;
    this.targetAgent = null;
    this.targetCarcass = null;
    this.targetPlant = null;
    this.targetWater = null;
    this.targetShelter = null;
    this.trackedSpecies = null;
    this.hurtFlash = 0;
    this.healFlash = 0;
    this.lastDamageAt = 0;
    this.scaleBase = 0.98 * Math.pow(this.genome.size, 0.84);
    this.rig = new CreatureRig(this.genome, { player: true, scale: this.scaleBase });
    this.rig.root.position.copy(this.position);
    this.rig.root.rotation.y = this.heading;
    game.scene.add(this.rig.root);
    this.spawnPoint = this.position.clone();
    this.scanTimer = 0;
  }

  get species() { return this.game.ecosystem.playerSpecies; }
  get fearLevel() { return { label: 'Calm', color: '#7fe0a8' }; }
  get maxHealth() { return this.stats.maxHealth; }

  applyGenome(g) {
    this.genome = normalizeGenome(g);
    this.stats = deriveStats(this.genome);
    this.scaleBase = 0.98 * Math.pow(this.genome.size, 0.84);
    this.rig.dispose();
    this.rig = new CreatureRig(this.genome, { player: true, scale: this.scaleBase });
    this.rig.root.position.copy(this.position);
    this.rig.root.rotation.y = this.heading;
    this.game.scene.add(this.rig.root);
    this.health = Math.min(this.stats.maxHealth, this.health + this.stats.maxHealth * 0.5);
    this.stamina = this.stats.maxStamina;
  }

  update(dt, input, camYaw) {
    if (!this.alive) {
      this.deathTimer += dt;
      this.rig.setState({ dead: true, state: 'dead', speed: 0 });
      this.rig.update(dt);
      return;
    }
    this.attackCooldown = Math.max(0, this.attackCooldown - dt);
    this.roarCooldown = Math.max(0, this.roarCooldown - dt);
    this.eatCooldown = Math.max(0, this.eatCooldown - dt);
    this.attackTimer = Math.max(0, this.attackTimer - dt);
    this.hurtFlash = Math.max(0, this.hurtFlash - dt * 2.5);
    this.healFlash = Math.max(0, this.healFlash - dt * 2);
    this.danger = Math.max(0, this.danger - dt * 0.03);
    this.age += dt * 0.012;
    this.animTimer += dt;

    const metabolic = this.resting ? 0.32 : 1;
    this.hunger = clamp(this.hunger + dt * 0.34 * metabolic, 0, 110);
    this.thirst = clamp(this.thirst + dt * 0.46 * metabolic, 0, 110);
    if (this.resting) {
      this.fatigue = clamp(this.fatigue - dt * 7, 0, 100);
      this.health = clamp(this.health + dt * this.stats.maxHealth * 0.035, 0, this.stats.maxHealth);
      this.stamina = clamp(this.stamina + dt * 16, 0, this.stats.maxStamina);
      this.restTime += dt;
    } else {
      this.fatigue = clamp(this.fatigue + dt * 0.5, 0, 100);
      if (this.hunger < 55 && this.thirst < 60) this.health = clamp(this.health + dt * 0.55, 0, this.stats.maxHealth);
    }
    if (this.hunger > 96) this.health = clamp(this.health - dt * 0.8, 0, this.stats.maxHealth);
    if (this.thirst > 97) this.health = clamp(this.health - dt * 1.2, 0, this.stats.maxHealth);
    if (this.hunger > 75 && this.thirst > 75) this.fatigue = clamp(this.fatigue + dt * 0.5, 0, 100);

    // injuries recover slowly when healthy
    if (this.hunger < 50 && this.thirst < 55) {
      for (const k of Object.keys(this.injuries)) {
        if (this.injuries[k] > 0) this.injuries[k] = Math.max(0, this.injuries[k] - dt * 0.0035);
      }
    }

    const axis = input.axis();
    const forward = new THREE.Vector3(-Math.sin(camYaw), 0, -Math.cos(camYaw));
    const right = new THREE.Vector3(Math.cos(camYaw), 0, -Math.sin(camYaw));
    const wish = forward.multiplyScalar(axis.y).add(right.multiplyScalar(axis.x));
    const wishLen = wish.length();
    const terrain = this.world.heightAt(this.position.x, this.position.z);
    const depth = WATER_LEVEL - terrain;
    this.swimming = depth > 0.9 && this.airHeight <= 0.02;
    const groundedNow = this.airHeight <= 0.02;
    this.grounded = groundedNow && !this.swimming;

    let targetSpeed = 0;
    const canSprint = input.sprint && this.stamina > 4 && this.fatigue < 92;
    const speedCap = this.swimming ? this.stats.swim : this.flying ? this.stats.fly : canSprint ? this.stats.sprint : this.stats.walk * 0.92;
    if (wishLen > 0.02) {
      wish.normalize();
      const targetHeading = Math.atan2(wish.x, wish.z);
      let delta = ((targetHeading - this.heading + Math.PI * 3) % (Math.PI * 2)) - Math.PI;
      const turnRate = (2.2 + this.stats.agility * 5.2) * (this.swimming ? 0.7 : 1);
      this.heading += clamp(delta, -turnRate * dt, turnRate * dt);
      this.turn = damp(this.turn, delta * 3, 8, dt);
      targetSpeed = speedCap;
      if (this.injuries.leg > 0.3) targetSpeed *= 0.68;
      if (this.fatigue > 82) targetSpeed *= 0.82;
      const aheadX = this.position.x + Math.sin(this.heading) * 1.4;
      const aheadZ = this.position.z + Math.cos(this.heading) * 1.4;
      const rise = this.world.heightAt(aheadX, aheadZ) - terrain;
      if (!this.swimming && !this.flying && rise > 0.35) targetSpeed *= 0.72;
      if (this.resting) { targetSpeed = 0; this.resting = false; this.game.ui?.toast('You wake up', 'info'); }
    } else {
      this.turn = damp(this.turn, 0, 6, dt);
    }
    if (this.swimming) {
      targetSpeed = Math.min(targetSpeed, this.stats.swim);
      this.stamina = clamp(this.stamina - dt * 0.9, 0, this.stats.maxStamina);
      this.flying = false;
    }
    if (this.flying) {
      this.stamina = clamp(this.stamina - dt * 1.4, 0, this.stats.maxStamina);
      if (this.stamina <= 0) this.flying = false;
    }
    this.speed = damp(this.speed, targetSpeed, 4, dt);
    if (this.speed > 0.05) {
      this.position.x += Math.sin(this.heading) * this.speed * dt;
      this.position.z += Math.cos(this.heading) * this.speed * dt;
    }
    this.position.x = clamp(this.position.x, -300, 300);
    this.position.z = clamp(this.position.z, -300, 300);

    // jump / flight / gravity
    if (input.pressed.has('Space') && this.grounded && !this.resting) {
      this.velocityY = this.stats.jump * 0.75;
      this.airHeight = 0.02;
      this.grounded = false;
      this.game.audio.play(this.genome.size > 1.6 ? 'stepBig' : 'step');
    }
    if (!this.grounded) {
      this.animTimer += 0;
      const flyingSpecies = this.genome.wings > 0;
      if (flyingSpecies && input.jump && this.stamina > 2) {
        this.velocityY = damp(this.velocityY, 3.2, 3, dt);
        this.flying = true;
      } else {
        this.velocityY -= 24 * dt;
        if (this.flying && this.velocityY < -1) this.flying = false;
      }
      this.airHeight += this.velocityY * dt;
      if (this.airHeight <= 0) {
        this.airHeight = 0; this.velocityY = 0; this.grounded = true; this.flying = false;
        if (this.speed > 3) this.game.audio.play('stepBig');
      }
    } else {
      this.airHeight = 0;
    }

    const groundY = this.world.heightAt(this.position.x, this.position.z);
    const depth2 = WATER_LEVEL - groundY;
    if (this.swimming) {
      this.position.y = WATER_LEVEL - 0.42 + Math.sin(performance.now() * 0.0014) * 0.05;
    } else {
      this.position.y = groundY + this.airHeight;
    }
    if (this.flying) this.position.y = groundY + this.airHeight + 1.2;
    if (depth2 > 5 && this.swimming) this.health = clamp(this.health - dt * 2, 0, this.stats.maxHealth);

    // footsteps
    if (this.speed > 0.7 && this.grounded) {
      this.stepTimer -= dt * (0.8 + this.speed * 0.25);
      if (this.stepTimer <= 0) {
        this.stepTimer = 1;
        this.game.audio.play(this.genome.size > 1.6 ? 'stepBig' : 'step');
      }
    }

    // scan interactions
    this.scanTimer -= dt;
    if (this.scanTimer <= 0) { this.scanTimer = 0.18; this.scan(); }
    this.checkBiome();

    this.rig.root.position.copy(this.position);
    this.rig.root.rotation.y = this.heading;
    this.rig.setState({
      speed: this.speed,
      state: this.resting ? 'sleep' : this.attackTimer > 0.12 ? 'attack' : this.eatCooldown > 0.6 ? 'eat' : 'idle',
      fear: this.localThreat * 0.3,
      turn: this.turn,
      swimming: this.swimming,
      flying: this.flying,
      injuredLeg: this.injuries.leg > 0.3,
      hurt: this.hurtFlash
    });
    this.rig.update(dt);

    if (this.health <= 0) this.die();
    if (this.resting && this.localThreat > 0.55) { this.resting = false; this.game.ui?.toast('Something is near — you wake!', 'danger'); }
  }

  scan() {
    const eco = this.game.ecosystem;
    if (!eco) return;
    const near = eco.nearestAgent(this.position, 34);
    if (near && near.agent !== this) this.targetAgent = near.agent; else this.targetAgent = null;
    this.targetCarcass = eco.nearestCarcass(this.position, 6.5);
    this.targetPlant = this.world.nearestPlant(this.position, 5.2);
    this.targetWater = this.world.nearestWater(this.position.x, this.position.z, 5);
    this.targetShelter = this.world.nearestShelter(this.position);
    if (this.targetShelter && this.targetShelter.dist > 7) this.targetShelter = null;
    let threat = 0;
    for (const a of eco.nearbyAgents(this.position, 18)) {
      if (a.dead) continue;
      const d = a.position.distanceTo(this.position);
      if (a.genome.diet === 'carnivore' && a.health > 0) threat = Math.max(threat, 1 - d / 18);
      if (a.state === 'hunt' || a.state === 'chase') threat = Math.max(threat, 0.65);
    }
    this.localThreat = damp(this.localThreat, threat, 2, this.game.lastDt || 0.016);
    if (this.targetAgent && !this.discoveredSpecies.has(this.targetAgent.species.id)) {
      this.discoveredSpecies.add(this.targetAgent.species.id);
      this.targetAgent.species.discovered = true;
      this.gainDNA(3);
      this.game.ui?.toast(`New species recorded: ${this.targetAgent.species.common}`, 'discovery');
    }
  }

  checkBiome() {
    const b = this.world.biomeAt(this.position.x, this.position.z);
    if (!this.discoveredBiomes.has(b)) {
      this.discoveredBiomes.add(b);
      this.gainDNA(4);
      this.game.ui?.toast(`New habitat charted: ${this.world.biomeInfo(b).label}`, 'discovery');
    }
  }

  get interactLabel() {
    if (this.targetPlant && this.targetPlant.available) return { key: 'E', label: `Eat ${this.targetPlant.kind}`, icon: 'plant' };
    if (this.targetCarcass) return { key: 'E', label: 'Scavenge remains', icon: 'meat' };
    if (this.targetWater) return { key: 'E', label: 'Drink water', icon: 'water' };
    if (this.targetShelter) return { key: 'E', label: 'Rest at shelter', icon: 'rest' };
    if (this.targetAgent) return { key: 'E', label: `Observe ${this.targetAgent.species.common}`, icon: 'scan' };
    return null;
  }

  interact() {
    if (!this.alive) return;
    if (this.targetPlant && this.targetPlant.available) {
      const n = this.world.consumePlant(this.targetPlant);
      this.hunger = clamp(this.hunger - (this.genome.diet === 'carnivore' ? n * 0.35 : n * 0.9), 0, 110);
      this.inventory.berries++;
      this.eatCooldown = 1.2;
      this.gainDNA(this.genome.diet === 'carnivore' ? 0.8 : 1.4);
      this.game.audio.play('eat');
      this.game.ui?.toast(`Ate ${this.targetPlant.kind}`, 'food');
      this.game.particles?.burst(this.targetPlant.position || new THREE.Vector3(this.targetPlant.x, this.targetPlant.y + 0.5, this.targetPlant.z), 5, new THREE.Color(0x9be37c), 0.8);
      return true;
    }
    if (this.targetCarcass && !this.targetCarcass.consumed) {
      const carcass = this.targetCarcass;
      const nut = Math.min(carcass.nutrition, 16);
      carcass.nutrition -= nut;
      carcass.eat(0);
      this.hunger = clamp(this.hunger - nut * (this.genome.diet === 'herbivore' ? 0.35 : 0.95), 0, 110);
      this.health = clamp(this.health + 6, 0, this.stats.maxHealth);
      this.inventory.meat++;
      this.gainDNA(2.5);
      this.game.audio.play('eat');
      this.game.ui?.toast('Scavenged meat', 'food');
      if (carcass.nutrition <= 0.5) carcass.destroy();
      return true;
    }
    if (this.targetWater) {
      this.thirst = clamp(this.thirst - 34, 0, 110);
      this.stamina = clamp(this.stamina + 8, 0, this.stats.maxStamina);
      this.gainDNA(0.4);
      this.game.audio.play('drink');
      this.game.ui?.toast('Drank fresh water', 'water');
      return true;
    }
    if (this.targetShelter) {
      this.resting = true;
      this.targetShelter = null;
      this.health = clamp(this.health + 10, 0, this.stats.maxHealth);
      this.game.ui?.toast('You settle into the shelter', 'rest');
      return true;
    }
    if (this.targetAgent) {
      this.discoveredSpecies.add(this.targetAgent.species.id);
      this.targetAgent.species.discovered = true;
      this.gainDNA(1);
      this.game.ui?.inspectAgent(this.targetAgent);
      return true;
    }
    return false;
  }

  attack() {
    if (!this.alive || this.attackCooldown > 0) return false;
    this.attackCooldown = this.stats.attackCooldown;
    this.attackTimer = 0.4;
    this.stamina = clamp(this.stamina - 7, 0, this.stats.maxStamina);
    this.danger = clamp(this.danger + 0.3, 0, 1);
    this.game.ecosystem.playerDanger = Math.min(1, this.game.ecosystem.playerDanger + 0.25);
    this.game.audio.play('bite');
    let best = null, bestD = this.stats.reach + 3.2;
    for (const a of this.game.ecosystem.nearbyAgents(this.position, bestD)) {
      if (a.dead) continue;
      const dx = a.position.x - this.position.x, dz = a.position.z - this.position.z;
      const d = Math.hypot(dx, dz);
      const dot = (dx * Math.sin(this.heading) + dz * Math.cos(this.heading)) / Math.max(0.001, d);
      if (d < bestD && dot > 0.15) { bestD = d; best = a; }
    }
    if (best) {
      const dmg = this.stats.bite + this.stats.claw * 0.65;
      const wasAlive = !best.dead;
      best.takeDamage(dmg, this, ['body', 'leg', 'jaw', 'eye'][Math.floor(Math.random() * 4)]);
      this.game.ui?.damageNumber(best.position, Math.round(dmg));
      this.game.shake(0.18);
      if (wasAlive && best.health <= 0) {
        this.gainDNA(14);
        this.game.ui?.toast(`Killed ${best.species.common} — DNA +14`, 'kill');
        this.game.audio.play('kill');
      }
      return true;
    }
    this.game.shake(0.05);
    return false;
  }

  roar() {
    if (!this.alive || this.roarCooldown > 0) return false;
    this.roarCooldown = 9;
    this.stamina = clamp(this.stamina - 10, 0, this.stats.maxStamina);
    this.danger = clamp(this.danger + 0.25, 0, 1);
    this.game.audio.play('roar');
    this.game.shake(0.35);
    for (const a of this.game.ecosystem.nearbyAgents(this.position, 30)) {
      if (a.dead) continue;
      a.fear = clamp(a.fear + 0.35, 0, 1);
      a.memory.playerTerror = clamp(a.memory.playerTerror + 0.3, 0, 1);
      if (a.fear > 0.55 && a.state !== 'attack') { a.state = 'flee'; a.stateTimer = 5; a.threat = this; }
    }
    this.game.ecosystem.playerDanger = Math.min(1, this.game.ecosystem.playerDanger + 0.2);
    this.game.ui?.toast('You unleash a territorial roar', 'roar');
    this.game.particles?.ring(this.position, 30);
    return true;
  }

  toggleRest() {
    if (!this.alive) return;
    this.resting = !this.resting;
    this.game.ui?.toast(this.resting ? 'Resting… press R to rise' : 'You wake', 'rest');
    if (this.resting) this.game.audio.play('open');
  }

  eatInventory(kind) {
    if (kind === 'berries' && this.inventory.berries > 0) {
      this.inventory.berries--;
      this.hunger = clamp(this.hunger - 18, 0, 110);
      this.health = clamp(this.health + 4, 0, this.stats.maxHealth);
      this.game.audio.play('eat');
      this.game.ui?.toast('Ate stored berries', 'food');
    } else if (kind === 'meat' && this.inventory.meat > 0) {
      this.inventory.meat--;
      this.hunger = clamp(this.hunger - 30, 0, 110);
      this.health = clamp(this.health + 10, 0, this.stats.maxHealth);
      this.game.audio.play('eat');
      this.game.ui?.toast('Ate stored meat', 'food');
    } else if (kind === 'herbs' && this.inventory.herbs > 0) {
      this.inventory.herbs--;
      this.health = clamp(this.health + 18, 0, this.stats.maxHealth);
      for (const k of Object.keys(this.injuries)) this.injuries[k] = Math.max(0, this.injuries[k] - 0.35);
      this.game.ui?.toast('Applied healing herbs', 'heal');
      this.game.audio.play('evolve');
    } else if (kind === 'crystal' && this.inventory.crystal > 0) {
      this.inventory.crystal--;
      this.gainDNA(18);
      this.game.ui?.toast('Channeled a DNA crystal', 'discovery');
      this.game.audio.play('evolve');
    }
  }

  gainDNA(amount) {
    this.dna += amount;
    this.evolutionPoints += amount;
    this.healFlash = Math.min(1, this.healFlash + 0.2);
    this.game.ui?.syncHUD();
  }

  takeDamage(amount, attacker, part = 'body') {
    if (!this.alive) return;
    const armor = clamp(this.stats.armorRating, 0, 0.65);
    const dmg = Math.max(1, amount * (1 - armor));
    this.health = clamp(this.health - dmg, 0, this.stats.maxHealth);
    this.hurtFlash = 1;
    this.lastDamageAt = performance.now();
    this.game.shake(0.4);
    this.game.audio.play('hurt');
    this.game.ui?.damageFlash(dmg);
    if (Math.random() < 0.3) {
      if (part === 'leg' && this.injuries.leg < 1) { this.injuries.leg = 1; this.game.ui?.toast('Your leg is injured — movement slowed', 'danger'); }
      else if (part === 'eye' && this.injuries.eye < 1) { this.injuries.eye = 1; this.game.ui?.toast('Your eye is injured — vision blurred', 'danger'); }
      else if (part === 'jaw' && this.injuries.jaw < 1) { this.injuries.jaw = 1; this.game.ui?.toast('Your jaw is injured — bite weakened', 'danger'); }
      else this.injuries.body = Math.min(1, this.injuries.body + 0.3);
    }
    if (this.resting) this.resting = false;
    if (attacker) this.danger = Math.max(this.danger, 0.2);
    if (this.health <= 0) this.die();
  }

  die() {
    if (!this.alive) return;
    this.alive = false;
    this.dead = true;
    this.resting = false;
    this.rig.setState({ dead: true, state: 'dead', speed: 0 });
    this.game.audio.play('death');
    this.game.onPlayerDeath();
  }

  respawn(pos) {
    this.alive = true;
    this.dead = false;
    this.health = this.stats.maxHealth * 0.7;
    this.stamina = this.stats.maxStamina * 0.6;
    this.hunger = Math.max(20, this.hunger - 30);
    this.thirst = Math.max(20, this.thirst - 30);
    this.injuries = { leg: 0, eye: 0, jaw: 0, body: 0 };
    this.resting = false;
    const p = pos || this.spawnPoint;
    this.position.set(p.x, this.world.heightAt(p.x, p.z), p.z);
    this.airHeight = 0; this.velocityY = 0; this.flying = false;
    this.rig.setState({ dead: false, state: 'idle', speed: 0 });
    this.rig.visual.rotation.z = 0;
    this.rig.dispose();
    this.rig = new CreatureRig(this.genome, { player: true, scale: this.scaleBase });
    this.rig.root.position.copy(this.position);
    this.rig.root.rotation.y = this.heading;
    this.game.scene.add(this.rig.root);
    this.game.ui?.hideDeath();
    this.game.ui?.toast('You awaken at your nest, weakened but alive', 'rest');
  }

  reproduce() {
    if (this.dna < 25) return false;
    const eco = this.game.ecosystem;
    const sp = eco.playerSpecies;
    if (!sp) return false;
    if (eco.agents.length >= eco.cap) return false;
    const mateGenome = this.genome;
    const childGenome = normalizeGenome({ ...this.genome, size: this.genome.size * 0.85 + Math.random() * 0.1 });
    // use Agent via import-free factory on ecosystem
    const child = eco.spawnPlayerOffspring(childGenome, this.position, this);
    if (!child) return false;
    this.dna -= 25;
    sp.population++;
    this.health = Math.max(1, this.health - this.stats.maxHealth * 0.15);
    this.game.ui?.toast('Your offspring hatches. Guard it well.', 'birth');
    this.game.audio.play('spawn');
    return true;
  }
}

// Pooled particle bursts and shockwave rings.
import * as THREE from 'three';

export class Particles {
  constructor(scene) {
    this.scene = scene;
    this.max = 700;
    this.pos = new Float32Array(this.max * 3);
    this.col = new Float32Array(this.max * 3);
    this.vel = new Float32Array(this.max * 3);
    this.life = new Float32Array(this.max);
    this.maxLife = new Float32Array(this.max);
    this.cursor = 0;
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(this.pos, 3));
    geo.setAttribute('color', new THREE.BufferAttribute(this.col, 3));
    for (let i = 0; i < this.max; i++) this.pos[i * 3 + 1] = -999;
    this.points = new THREE.Points(geo, new THREE.PointsMaterial({
      size: 0.34, vertexColors: true, transparent: true, opacity: 0.95, depthWrite: false,
      blending: THREE.AdditiveBlending, sizeAttenuation: true
    }));
    this.points.frustumCulled = false;
    scene.add(this.points);
    this.rings = [];
    this.dustTimer = 0;
  }

  burst(pos, count = 6, color = new THREE.Color(0xff6a4a), speed = 1.2, life = 0.8) {
    for (let n = 0; n < count; n++) {
      const i = this.cursor++ % this.max;
      this.pos[i * 3] = pos.x + (Math.random() - 0.5) * 0.4;
      this.pos[i * 3 + 1] = pos.y + (Math.random() - 0.3) * 0.5;
      this.pos[i * 3 + 2] = pos.z + (Math.random() - 0.5) * 0.4;
      const a = Math.random() * Math.PI * 2;
      const s = speed * (0.4 + Math.random());
      this.vel[i * 3] = Math.cos(a) * s;
      this.vel[i * 3 + 1] = (Math.random() * 1.8 + 0.4) * speed * 0.6;
      this.vel[i * 3 + 2] = Math.sin(a) * s;
      this.col[i * 3] = color.r; this.col[i * 3 + 1] = color.g; this.col[i * 3 + 2] = color.b;
      this.life[i] = life * (0.5 + Math.random() * 0.7);
      this.maxLife[i] = this.life[i];
    }
    this.points.geometry.attributes.position.needsUpdate = true;
    this.points.geometry.attributes.color.needsUpdate = true;
  }

  ring(pos, radius = 20, color = 0xffe6a0) {
    const geo = new THREE.RingGeometry(0.4, 0.55, 48);
    geo.rotateX(-Math.PI / 2);
    const mat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.85, side: THREE.DoubleSide, depthWrite: false, blending: THREE.AdditiveBlending });
    const mesh = new THREE.Mesh(geo, mat);
    mesh.position.copy(pos);
    mesh.position.y += 0.4;
    this.scene.add(mesh);
    this.rings.push({ mesh, t: 0, radius, color });
  }

  dust(pos, speed = 1) {
    if (Math.random() > 0.4) return;
    this.dustTimer = 0.12;
    this.burst(new THREE.Vector3(pos.x, pos.y + 0.12, pos.z), 2, new THREE.Color(0x9d9070), 0.5 * speed, 0.5);
  }

  update(dt) {
    for (let i = 0; i < this.max; i++) {
      if (this.life[i] <= 0) continue;
      this.life[i] -= dt;
      if (this.life[i] <= 0) { this.pos[i * 3 + 1] = -999; continue; }
      this.vel[i * 3 + 1] -= 6.5 * dt;
      this.pos[i * 3] += this.vel[i * 3] * dt;
      this.pos[i * 3 + 1] += this.vel[i * 3 + 1] * dt;
      this.pos[i * 3 + 2] += this.vel[i * 3 + 2] * dt;
    }
    this.points.geometry.attributes.position.needsUpdate = true;
    for (let i = this.rings.length - 1; i >= 0; i--) {
      const r = this.rings[i];
      r.t += dt;
      const k = r.t / 1.1;
      r.mesh.scale.setScalar(1 + k * r.radius);
      r.mesh.material.opacity = Math.max(0, 0.85 * (1 - k));
      if (k >= 1) { this.scene.remove(r.mesh); r.mesh.geometry.dispose(); r.mesh.material.dispose(); this.rings.splice(i, 1); }
    }
  }
}

// Cell Stage: a playable microscopic pond with feeding, predators and evolution.
import * as THREE from 'three';
import { clamp, damp, mulberry32, randRange, TAU, lerp } from './util.js';
import { normalizeGenome } from './genome.js';

function glowTexture() {
  const c = document.createElement('canvas'); c.width = c.height = 128;
  const ctx = c.getContext('2d');
  const g = ctx.createRadialGradient(64, 64, 0, 64, 64, 64);
  g.addColorStop(0, 'rgba(255,255,255,1)');
  g.addColorStop(0.22, 'rgba(220,255,245,0.9)');
  g.addColorStop(0.55, 'rgba(120,255,220,0.25)');
  g.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = g; ctx.fillRect(0, 0, 128, 128);
  return new THREE.CanvasTexture(c);
}

class CellRig {
  constructor(color = 0x7bf0d0, size = 1, predator = false) {
    this.group = new THREE.Group();
    this.size = size;
    this.t = Math.random() * 10;
    this.membraneMat = new THREE.MeshStandardMaterial({
      color, transparent: true, opacity: 0.62, roughness: 0.18, metalness: 0.05,
      emissive: color, emissiveIntensity: 0.22, side: THREE.DoubleSide
    });
    this.innerMat = new THREE.MeshStandardMaterial({ color: 0x0c4a48, emissive: 0x1c8b72, emissiveIntensity: 0.4, roughness: 0.5 });
    this.membrane = new THREE.Mesh(new THREE.SphereGeometry(1, 20, 14), this.membraneMat);
    this.membrane.scale.set(1, 0.78, 1.15);
    this.group.add(this.membrane);
    this.nucleus = new THREE.Mesh(new THREE.SphereGeometry(0.37, 12, 8), this.innerMat);
    this.nucleus.position.set(-0.05, 0.04, 0.05);
    this.group.add(this.nucleus);
    this.vacuoles = [];
    for (let i = 0; i < 4; i++) {
      const v = new THREE.Mesh(new THREE.SphereGeometry(0.1 + Math.random() * 0.06, 8, 6), this.innerMat);
      v.position.set(randRange(Math.random, -0.5, 0.5), randRange(Math.random, -0.25, 0.25), randRange(Math.random, -0.5, 0.5));
      this.group.add(v); this.vacuoles.push(v);
    }
    this.cilia = [];
    for (let i = 0; i < 16; i++) {
      const a = i / 16 * TAU;
      const c = new THREE.Mesh(new THREE.ConeGeometry(0.035, 0.45, 4), this.membraneMat);
      c.position.set(Math.cos(a) * 1.02, Math.sin(a) * 0.7, 0);
      c.rotation.z = a + Math.PI / 2;
      this.group.add(c); this.cilia.push({ mesh: c, phase: a });
    }
    this.flagella = [];
    let parent = this.group;
    for (let i = 0; i < 5; i++) {
      const seg = new THREE.Group();
      seg.position.set(0, 0, i === 0 ? -1.1 : -0.38);
      const m = new THREE.Mesh(new THREE.CylinderGeometry(0.025, 0.018, 0.4, 4).rotateX(Math.PI / 2).translate(0, 0, -0.2), this.membraneMat);
      seg.add(m); parent.add(seg); this.flagella.push(seg); parent = seg;
    }
    if (predator) {
      for (let i = 0; i < 7; i++) {
        const a = i / 7 * TAU;
        const spike = new THREE.Mesh(new THREE.ConeGeometry(0.09, 0.8, 4), this.innerMat);
        spike.position.set(Math.cos(a) * 0.95, Math.sin(a) * 0.65, 0);
        spike.rotation.z = Math.PI / 2 - a;
        this.group.add(spike);
      }
    }
    const tex = glowTexture();
    const glow = new THREE.Sprite(new THREE.SpriteMaterial({ map: tex, color, transparent: true, opacity: 0.4, blending: THREE.AdditiveBlending, depthWrite: false }));
    glow.scale.set(3.4, 3.4, 1);
    this.group.add(glow);
    this.group.scale.setScalar(size);
  }
  update(dt, speed) {
    this.t += dt;
    this.membrane.scale.set(1 + Math.sin(this.t * 3) * 0.03, 0.78 + Math.cos(this.t * 2.4) * 0.025, 1.15);
    for (const c of this.cilia) {
      c.mesh.rotation.x = Math.sin(this.t * 10 + c.phase * 3) * 0.5 * (0.4 + speed);
    }
    for (let i = 0; i < this.flagella.length; i++) {
      this.flagella[i].rotation.y = Math.sin(this.t * 6 - i * 0.7) * 0.25;
      this.flagella[i].rotation.x = Math.sin(this.t * 5 - i * 0.5) * 0.12;
    }
    this.group.rotation.y += dt * 0.1;
  }
}

export class CellStage {
  constructor(game) {
    this.game = game;
    this.scene = new THREE.Scene();
    this.scene.fog = new THREE.FogExp2(0x04262c, 0.038);
    this.scene.background = new THREE.Color(0x041e24);
    this.camera = new THREE.PerspectiveCamera(55, window.innerWidth / window.innerHeight, 0.1, 300);
    this.camera.position.set(0, 8, 13);
    this.biomass = 0;
    this.dna = 0;
    this.eaten = 0;
    this.health = 100;
    this.alive = true;
    this.time = 0;
    this.damageCooldown = 0;
    this.dashCooldown = 0;
    this.evolveAvailable = false;
    this.buildLights();
    this.buildPond();
    this.buildPlayer();
    this.buildFood();
    this.buildPredators();
    this.spawnPos = new THREE.Vector3(0, 1.1, 0);
    this.playerPos = this.spawnPos.clone();
    this.playerVel = new THREE.Vector3();
    this.heading = 0;
    this.scene.add(this.playerRig.group);
  }

  buildLights() {
    this.scene.add(new THREE.HemisphereLight(0x8de8e0, 0x062a2e, 1.5));
    const dir = new THREE.DirectionalLight(0x9df5e0, 2.2);
    dir.position.set(6, 20, 4);
    this.scene.add(dir);
    this.rim = new THREE.PointLight(0x54ffd2, 20, 30);
    this.rim.position.set(0, 6, -8);
    this.scene.add(this.rim);
  }

  buildPond() {
    const floor = new THREE.Mesh(new THREE.CircleGeometry(70, 48), new THREE.MeshStandardMaterial({ color: 0x0a3c3a, roughness: 1 }));
    floor.rotation.x = -Math.PI / 2;
    floor.position.y = -2.4;
    this.scene.add(floor);
    // caustic rings
    const rng = mulberry32(8821);
    const ringMat = new THREE.MeshBasicMaterial({ color: 0x2c7d70, transparent: true, opacity: 0.18, side: THREE.DoubleSide, depthWrite: false, blending: THREE.AdditiveBlending });
    for (let i = 0; i < 20; i++) {
      const r = randRange(rng, 1, 6);
      const ring = new THREE.Mesh(new THREE.RingGeometry(r * 0.9, r, 32), ringMat);
      ring.rotation.x = -Math.PI / 2;
      ring.position.set(randRange(rng, -40, 40), -2.35, randRange(rng, -40, 40));
      this.scene.add(ring);
    }
    // rocks and kelp silhouettes
    const rockMat = new THREE.MeshStandardMaterial({ color: 0x0b2d30, roughness: 0.9, flatShading: true });
    for (let i = 0; i < 18; i++) {
      const rock = new THREE.Mesh(new THREE.DodecahedronGeometry(randRange(rng, 0.7, 2.6), 0), rockMat);
      rock.position.set(randRange(rng, -40, 40), -2.1, randRange(rng, -40, 40));
      rock.scale.y = randRange(rng, 0.4, 1.3);
      this.scene.add(rock);
    }
    const kelpMat = new THREE.MeshStandardMaterial({ color: 0x0e4a3c, transparent: true, opacity: 0.55, side: THREE.DoubleSide, roughness: 1 });
    this.kelp = [];
    for (let i = 0; i < 26; i++) {
      const h = randRange(rng, 4, 14);
      const kelp = new THREE.Mesh(new THREE.ConeGeometry(randRange(rng, 0.3, 1.1), h, 4), kelpMat);
      kelp.position.set(randRange(rng, -38, 38), -2 + h / 2, randRange(rng, -38, 38));
      this.scene.add(kelp);
      this.kelp.push({ mesh: kelp, phase: rng() * TAU });
    }
    // light shafts
    const shaftTex = glowTexture();
    for (let i = 0; i < 10; i++) {
      const shaft = new THREE.Mesh(new THREE.PlaneGeometry(randRange(rng, 2, 7), 26), new THREE.MeshBasicMaterial({
        color: 0x74e8d0, transparent: true, opacity: 0.035, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide
      }));
      shaft.position.set(randRange(rng, -30, 30), 10, randRange(rng, -30, 30));
      shaft.rotation.z = 0.12;
      this.scene.add(shaft);
    }
    // motes
    const motesGeo = new THREE.BufferGeometry();
    const motes = [];
    for (let i = 0; i < 500; i++) motes.push(randRange(rng, -45, 45), randRange(rng, -2, 20), randRange(rng, -45, 45));
    motesGeo.setAttribute('position', new THREE.Float32BufferAttribute(motes, 3));
    this.motes = new THREE.Points(motesGeo, new THREE.PointsMaterial({ color: 0x9fffe6, size: 0.09, transparent: true, opacity: 0.55, depthWrite: false, blending: THREE.AdditiveBlending }));
    this.scene.add(this.motes);
  }

  buildPlayer() {
    this.playerRig = new CellRig(0x7bf0d0, 1);
    this.playerRig.group.position.copy(new THREE.Vector3(0, 1.1, 0));
    this.playerGlow = new THREE.PointLight(0x5cffd8, 10, 16);
    this.playerRig.group.add(this.playerGlow);
  }

  buildFood() {
    this.food = [];
    this.foodGroup = new THREE.Group();
    this.scene.add(this.foodGroup);
    this.glowTex = glowTexture();
    const rng = mulberry32(6042);
    for (let i = 0; i < 46; i++) {
      const color = [0x9bffcf, 0xfff29b, 0x9befff, 0xffb3e0][i % 4];
      const group = new THREE.Group();
      const core = new THREE.Mesh(new THREE.IcosahedronGeometry(0.17, 1), new THREE.MeshStandardMaterial({ color, emissive: color, emissiveIntensity: 1.7, roughness: 0.3 }));
      group.add(core);
      const sprite = new THREE.Sprite(new THREE.SpriteMaterial({ map: this.glowTex, color, transparent: true, opacity: 0.8, blending: THREE.AdditiveBlending, depthWrite: false }));
      sprite.scale.set(1.4, 1.4, 1);
      group.add(sprite);
      const a = rng() * TAU, r = 3 + Math.sqrt(rng()) * 34;
      group.position.set(Math.cos(a) * r, randRange(rng, 0.4, 7), Math.sin(a) * r);
      group.userData = { baseY: group.position.y, phase: rng() * TAU, eaten: false, color };
      this.foodGroup.add(group);
      this.food.push(group);
    }
  }

  buildPredators() {
    this.predators = [];
    const rng = mulberry32(771);
    for (let i = 0; i < 4; i++) {
      const rig = new CellRig(i % 2 ? 0xff7b95 : 0xd870ff, randRange(rng, 1.3, 2.2), true);
      const a = rng() * TAU, r = 10 + rng() * 22;
      const pos = new THREE.Vector3(Math.cos(a) * r, 1.1, Math.sin(a) * r);
      rig.group.position.copy(pos);
      this.scene.add(rig.group);
      this.predators.push({ rig, pos, home: pos.clone(), speed: randRange(rng, 1.2, 2.4), size: rig.size, heading: rng() * TAU, timer: 0 });
    }
  }

  reset() {
    this.biomass = 0;
    this.eaten = 0;
    this.health = 100;
    this.alive = true;
    this.dna = 0;
    this.evolveAvailable = false;
    this.playerPos.copy(this.spawnPos);
    this.playerVel.set(0, 0, 0);
    this.playerRig.group.scale.setScalar(1);
    for (const f of this.food) { f.visible = true; f.userData.eaten = false; }
    for (const p of this.predators) { p.pos.copy(p.home); p.rig.group.position.copy(p.pos); }
  }

  update(dt, input) {
    if (!this.alive) {
      this.deathTimer = (this.deathTimer || 0) + dt;
      if (this.deathTimer > 1.6) { this.deathTimer = 0; this.reset(); this.game.ui?.toast('A new cell divides — try again', 'birth'); }
      this.updateCamera(dt);
      this.playerRig.update(dt, 0);
      return;
    }
    this.time += dt;
    this.damageCooldown = Math.max(0, this.damageCooldown - dt);
    this.dashCooldown = Math.max(0, this.dashCooldown - dt);
    const axis = input.axis();
    const accel = 10 + this.biomass * 0.12;
    this.playerVel.x += axis.x * accel * dt;
    this.playerVel.z += -axis.y * accel * dt;
    if (input.pressed.has('Space') && this.dashCooldown <= 0) {
      this.dashCooldown = 2.2;
      const len = Math.hypot(this.playerVel.x, this.playerVel.z) || 1;
      this.playerVel.x += (this.playerVel.x / len) * 9;
      this.playerVel.z += (this.playerVel.z / len) * 9;
      this.game.audio.play('cellEat');
      this.game.particles?.burst(this.playerPos, 8, new THREE.Color(0x7bf0d0), 1.2);
    }
    const friction = Math.exp(-2.6 * dt);
    this.playerVel.x *= friction; this.playerVel.z *= friction;
    const maxSpeed = 4.4 + this.biomass * 0.05;
    const sp = Math.hypot(this.playerVel.x, this.playerVel.z);
    if (sp > maxSpeed) { this.playerVel.x *= maxSpeed / sp; this.playerVel.z *= maxSpeed / sp; }
    this.playerPos.x += this.playerVel.x * dt;
    this.playerPos.z += this.playerVel.z * dt;
    const r = Math.hypot(this.playerPos.x, this.playerPos.z);
    if (r > 44) { this.playerPos.x *= 44 / r; this.playerPos.z *= 44 / r; }
    this.playerPos.y = 1.1 + Math.sin(this.time * 1.5) * 0.08;
    if (sp > 0.25) this.heading = Math.atan2(this.playerVel.x, this.playerVel.z);
    this.playerRig.group.position.copy(this.playerPos);
    this.playerRig.group.rotation.y = this.heading + Math.PI;
    this.playerRig.update(dt, sp * 0.3);
    const scale = 1 + this.biomass * 0.022;
    this.playerRig.group.scale.setScalar(scale);
    this.playerRig.group.children.forEach(c => { if (c.material === this.playerRig.membraneMat) {} });

    // eat plankton
    for (const f of this.food) {
      if (f.userData.eaten) continue;
      f.position.y = f.userData.baseY + Math.sin(this.time * 1.2 + f.userData.phase) * 0.3;
      f.rotation.y += dt * 0.6;
      const d = f.position.distanceTo(this.playerPos);
      if (d < 1.1 + scale * 0.6) {
        f.userData.eaten = true; f.visible = false;
        this.biomass += 1; this.eaten++; this.dna += 2;
        this.game.audio.play('cellEat');
        this.game.particles?.burst(f.position, 7, new THREE.Color(f.userData.color), 1.1);
        this.game.ui?.cellHUD(this);
        if (this.biomass >= 14 && !this.evolveAvailable) {
          this.evolveAvailable = true;
          this.game.ui?.cellReady(this);
          this.game.audio.play('evolve');
        }
      }
    }
    // predators
    for (const p of this.predators) {
      const d = p.pos.distanceTo(this.playerPos);
      const dir = new THREE.Vector3().subVectors(this.playerPos, p.pos);
      dir.y = 0;
      const dist = dir.length();
      if (dist < 1) dir.set(1, 0, 0);
      dir.normalize();
      const playerBigger = scale > p.size * 0.95;
      if (dist < 15 && playerBigger) {
        p.pos.x -= dir.x * p.speed * dt * 1.2;
        p.pos.z -= dir.z * p.speed * dt * 1.2;
      } else if (dist < 16) {
        p.pos.x += dir.x * p.speed * dt;
        p.pos.z += dir.z * p.speed * dt;
      } else {
        p.timer -= dt;
        if (p.timer <= 0) {
          p.timer = 3 + Math.random() * 5;
          p.wander = new THREE.Vector3(p.home.x + (Math.random() - 0.5) * 16, 1.1, p.home.z + (Math.random() - 0.5) * 16);
        }
        if (p.wander) {
          const wd = new THREE.Vector3().subVectors(p.wander, p.pos); wd.y = 0;
          const wl = wd.length() || 1;
          p.pos.x += wd.x / wl * p.speed * 0.45 * dt;
          p.pos.z += wd.z / wl * p.speed * 0.45 * dt;
        }
      }
      const pr = Math.hypot(p.pos.x, p.pos.z);
      if (pr > 46) { p.pos.x *= 46 / pr; p.pos.z *= 46 / pr; }
      p.pos.y = 1.1 + Math.sin(this.time + p.speed) * 0.1;
      p.rig.group.position.copy(p.pos);
      p.rig.group.rotation.y = Math.atan2(this.playerPos.x - p.pos.x, this.playerPos.z - p.pos.z);
      p.rig.update(dt, 0.4);
      if (dist < p.size * 1.15 + scale * 0.7 && this.damageCooldown <= 0) {
        if (playerBigger) {
          const idx = this.predators.indexOf(p);
          if (idx >= 0) { this.scene.remove(p.rig.group); this.predators.splice(idx, 1); }
          this.biomass += 5; this.dna += 6;
          this.game.particles?.burst(p.pos, 18, new THREE.Color(0xff7b95), 2);
          this.game.audio.play('cellEat');
          this.game.ui?.toast('You consumed a rival cell! +5 biomass', 'kill');
        } else {
          this.health -= 25;
          this.damageCooldown = 1.4;
          this.game.audio.play('hurt');
          this.game.particles?.burst(this.playerPos, 10, new THREE.Color(0xff5b6e), 1.4);
          this.game.shake(0.3);
          this.playerVel.x += dir.x * -8; this.playerVel.z += dir.z * -8;
          this.game.ui?.cellHUD(this);
          if (this.health <= 0) {
            this.alive = false;
            this.playerRig.group.visible = false;
            this.game.audio.play('death');
            this.game.ui?.toast('Your cell was consumed. Dividing anew…', 'danger');
          }
        }
      }
    }
    // motes drift
    const mp = this.motes.geometry.attributes.position;
    for (let i = 0; i < mp.count; i++) {
      let y = mp.getY(i) + dt * 0.12;
      if (y > 20) y = -2;
      mp.setY(i, y);
    }
    mp.needsUpdate = true;
    for (const k of this.kelp) k.mesh.rotation.z = Math.sin(this.time * 0.5 + k.phase) * 0.05;
    this.updateCamera(dt);
    this.game.ui?.cellTick(this);
  }

  updateCamera(dt) {
    const target = this.playerPos.clone();
    this.camera.position.x = damp(this.camera.position.x, target.x + 2.6, 2.2, dt);
    this.camera.position.z = damp(this.camera.position.z, target.z + 9.5, 2.2, dt);
    this.camera.position.y = damp(this.camera.position.y, target.y + 9.0, 2.2, dt);
    this.camera.lookAt(target.x, target.y + 0.3, target.z);
  }
}

:root {
  --mint: #7df3bc;
  --mint-bright: #b6ffdf;
  --mint-dim: #3d9c78;
  --amber: #ffd170;
  --amber-dim: #b98a3e;
  --red: #ff6f5e;
  --red-deep: #c53b46;
  --blue: #6fd8ff;
  --violet: #b89bff;
  --ink: #edf8f1;
  --muted: #91aa9e;
  --muted-2: #6c857a;
  --bg: #06110d;
  --glass: rgba(10, 26, 21, 0.66);
  --glass-2: rgba(11, 33, 26, 0.82);
  --line: rgba(163, 255, 214, 0.14);
  --line-strong: rgba(163, 255, 214, 0.3);
  --font: "Avenir Next", "Segoe UI", "Helvetica Neue", system-ui, sans-serif;
  --display: "Trebuchet MS", "Avenir Next", "Segoe UI", sans-serif;
}

* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; height: 100%; overflow: hidden; background: var(--bg); color: var(--ink); font-family: var(--font); -webkit-font-smoothing: antialiased; }
body { touch-action: none; user-select: none; }
#app { position: fixed; inset: 0; overflow: hidden; }
#game-canvas { position: absolute; inset: 0; width: 100%; height: 100%; display: block; outline: none; }
.hidden { display: none !important; }
button { font-family: inherit; color: inherit; }
canvas { display: block; }

#world-vignette { position: absolute; inset: 0; pointer-events: none; background: radial-gradient(ellipse at center, transparent 45%, rgba(2, 8, 6, 0.35) 82%, rgba(2, 6, 5, 0.65) 100%); }
#damage-vignette { position: absolute; inset: 0; pointer-events: none; opacity: 0; background: radial-gradient(ellipse at center, transparent 40%, rgba(255, 42, 38, 0.4) 100%); transition: opacity 0.18s ease; }
#heal-vignette { position: absolute; inset: 0; pointer-events: none; opacity: 0; background: radial-gradient(ellipse at center, rgba(90, 255, 190, 0.08), transparent 65%); transition: opacity 0.5s ease; }
#screen-flash { position: absolute; inset: 0; pointer-events: none; background: #fff; opacity: 0; }

.glass {
  background: linear-gradient(150deg, rgba(17, 40, 32, 0.78), rgba(6, 18, 14, 0.7));
  border: 1px solid var(--line);
  box-shadow: 0 10px 40px rgba(0, 0, 0, 0.35), inset 0 1px 0 rgba(255, 255, 255, 0.035);
  backdrop-filter: blur(16px) saturate(1.15);
  -webkit-backdrop-filter: blur(16px) saturate(1.15);
}

.screen { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; }
.btn {
  border: 1px solid var(--line-strong);
  background: rgba(13, 30, 24, 0.55);
  padding: 12px 24px;
  border-radius: 3px;
  font-size: 12px;
  letter-spacing: 0.18em;
  font-weight: 700;
  cursor: pointer;
  transition: transform 0.16s ease, background 0.2s ease, border-color 0.2s ease, box-shadow 0.2s ease;
  text-transform: uppercase;
}
.btn:hover { background: rgba(30, 64, 51, 0.7); border-color: var(--mint); transform: translateY(-1px); }
.btn:active { transform: translateY(0) scale(0.99); }
.btn-primary { background: linear-gradient(135deg, #9cf7ca, #4fd39b); color: #05110c; border-color: #b8ffe1; box-shadow: 0 0 34px rgba(73, 231, 164, 0.25); }
.btn-primary:hover { background: linear-gradient(135deg, #b8ffe0, #63e8ae); box-shadow: 0 0 48px rgba(73, 231, 164, 0.4); }
.btn-ghost { background: rgba(10, 24, 19, 0.35); }
.btn-quiet { background: transparent; border-color: rgba(255, 255, 255, 0.12); color: var(--muted); }
.btn-quiet:hover { color: var(--ink); }
.btn-xl { padding: 16px 34px; font-size: 12px; }

/* ============ LOADING ============ */
#loading { background: radial-gradient(circle at 50% 40%, #102b22, #050f0c 70%); z-index: 100; transition: opacity 0.6s ease; }
.loading-inner { text-align: center; }
.loading-mark { font-size: 54px; color: var(--mint); animation: spinSlow 4s linear infinite; text-shadow: 0 0 40px var(--mint); }
.loading-title { font-size: 13px; letter-spacing: 0.42em; margin: 18px 0 22px; color: var(--mint); }
.loading-bar { width: 260px; height: 2px; background: rgba(255, 255, 255, 0.1); margin: 0 auto; overflow: hidden; }
.loading-bar span { display: block; height: 100%; width: 20%; background: var(--mint); box-shadow: 0 0 14px var(--mint); animation: loadBar 1.6s ease-in-out infinite; }
#loading-text { margin-top: 16px; color: var(--muted); font-size: 11px; letter-spacing: 0.15em; }
@keyframes loadBar { 0% { transform: translateX(-120%); width: 20%; } 60% { width: 58%; } 100% { transform: translateX(520%); width: 20%; } }
@keyframes spinSlow { to { transform: rotate(360deg); } }

/* ============ TITLE ============ */
#title-screen { z-index: 60; background: radial-gradient(ellipse at 50% 42%, rgba(4, 12, 9, 0.15) 0%, rgba(4, 11, 8, 0.6) 48%, rgba(3, 8, 6, 0.92) 100%); }
.title-gradient { position: absolute; inset: 0; background: linear-gradient(180deg, rgba(4, 12, 9, 0.72) 0%, transparent 28%, transparent 58%, rgba(3, 10, 7, 0.9) 100%); pointer-events: none; }
.title-content { position: relative; text-align: center; z-index: 2; padding: 20px; animation: titleIn 1.2s cubic-bezier(.16,1,.3,1) both; }
@keyframes titleIn { from { opacity: 0; transform: translateY(26px); } }
.eyebrow { display: flex; align-items: center; justify-content: center; gap: 15px; font-size: 10px; letter-spacing: 0.45em; color: var(--mint); font-weight: 600; }
.eyebrow i { width: 42px; height: 1px; background: linear-gradient(90deg, transparent, var(--mint)); display: block; }
.eyebrow i:last-child { transform: scaleX(-1); }
.logo { margin: 20px 0 14px; font-family: var(--display); font-size: clamp(52px, 10.2vw, 148px); line-height: 0.8; letter-spacing: 0.02em; font-weight: 900; text-transform: uppercase; text-shadow: 0 20px 80px rgba(0, 0, 0, 0.65); }
.logo span { display: block; background: linear-gradient(180deg, #d5ffed 0%, #74f0bb 48%, #2f9d73 100%); -webkit-background-clip: text; background-clip: text; color: transparent; letter-spacing: 0.08em; font-size: 0.72em; }
.tagline { color: #b8cbc0; font-size: 14px; line-height: 1.75; margin: 24px auto 38px; max-width: 560px; letter-spacing: 0.02em; text-shadow: 0 2px 16px rgba(0,0,0,.8); }
.title-actions { display: flex; gap: 12px; justify-content: center; flex-wrap: wrap; }
.title-meta { margin-top: 42px; color: var(--muted-2); font-size: 9.5px; letter-spacing: 0.24em; display: flex; gap: 13px; justify-content: center; flex-wrap: wrap; }
.title-meta b { color: var(--muted); font-weight: 600; }
.title-footer { position: absolute; bottom: 26px; left: 0; right: 0; display: flex; justify-content: center; gap: 30px; color: var(--muted-2); font-size: 9px; letter-spacing: 0.26em; z-index: 2; }

/* ============ HUD ============ */
#hud { position: absolute; inset: 0; pointer-events: none; z-index: 20; }
#hud button, #hud .action, #hud .target-panel { pointer-events: auto; }
.hud-top { position: absolute; top: max(18px, env(safe-area-inset-top)); left: 20px; right: 20px; display: flex; align-items: flex-start; justify-content: space-between; gap: 18px; }
.species-card { display: flex; gap: 12px; padding: 10px 14px 10px 10px; border-radius: 6px; min-width: 292px; }
.portrait-wrap { position: relative; width: 62px; height: 62px; border: 1px solid var(--line-strong); border-radius: 4px; overflow: hidden; background: radial-gradient(circle at 50% 30%, rgba(80, 220, 160, 0.18), rgba(4, 18, 12, 0.8)); flex: none; }
#hud-portrait { width: 100%; height: 100%; }
.stage-badge { position: absolute; bottom: 0; left: 0; right: 0; text-align: center; font-size: 7px; letter-spacing: 0.14em; background: rgba(85, 233, 173, 0.85); color: #04110b; font-weight: 800; padding: 2px 0; }
.species-eyebrow { font-size: 8px; color: var(--mint); letter-spacing: 0.25em; font-weight: 700; }
.species-name { font-family: var(--display); font-size: 18px; letter-spacing: 0.03em; font-weight: 700; line-height: 1.2; text-transform: uppercase; }
.species-sub { color: var(--muted); font-size: 10px; letter-spacing: 0.06em; margin-top: 1px; }
.dna-row { font-size: 10px; color: var(--muted); margin-top: 6px; letter-spacing: 0.06em; }
.dna-row b { color: var(--mint); font-size: 12px; }
.dna-icon { color: var(--mint); }
.pop { float: right; color: var(--muted-2); font-size: 9px; }
.objective { padding: 10px 18px; border-radius: 6px; width: 340px; }
.objective-label { font-size: 8px; letter-spacing: 0.24em; color: var(--amber); font-weight: 700; }
.objective-text { font-size: 11.5px; margin: 4px 0 7px; color: #d9e9df; line-height: 1.35; }
.objective-progress { height: 3px; background: rgba(255,255,255,.09); border-radius: 2px; overflow: hidden; }
.objective-progress span { display: block; height: 100%; width: 10%; background: linear-gradient(90deg, var(--mint), var(--amber)); transition: width .4s ease; }
.environment { display: flex; align-items: center; gap: 14px; padding: 10px 16px; border-radius: 6px; }
.env-clock { font-family: var(--display); font-size: 22px; letter-spacing: 0.05em; line-height: 1; }
.env-day { font-size: 8px; letter-spacing: 0.18em; color: var(--mint); margin-top: 4px; }
.env-divider { width: 1px; height: 32px; background: var(--line); }
.env-detail { font-size: 9px; letter-spacing: 0.06em; color: var(--muted); line-height: 1.8; text-align: right; }
#env-year { color: var(--amber); }

.vitals { position: absolute; left: 20px; top: 102px; width: 292px; border-radius: 6px; padding: 14px 16px 10px; }
.vital { margin-bottom: 9px; }
.vital-head { display: flex; justify-content: space-between; font-size: 8.5px; letter-spacing: 0.16em; color: var(--muted); margin-bottom: 4px; font-weight: 700; }
.vital-head b { color: var(--ink); font-size: 10px; letter-spacing: 0.02em; }
.bar { height: 6px; background: rgba(255,255,255,0.08); border-radius: 1px; overflow: hidden; position: relative; }
.bar span { display: block; height: 100%; width: 100%; transition: width 0.3s ease, background 0.3s; }
[data-vital="health"] .bar span { background: linear-gradient(90deg, #ff8b7e, #ff5a52); box-shadow: 0 0 10px rgba(255, 95, 80, 0.35); }
[data-vital="hunger"] .bar span { background: linear-gradient(90deg, #ffd887, #e89b3c); }
[data-vital="thirst"] .bar span { background: linear-gradient(90deg, #8ce4ff, #3d9fd4); }
[data-vital="stamina"] .bar span { background: linear-gradient(90deg, #a6f5cb, #41c58c); }
.vital-mini { display: flex; justify-content: space-between; font-size: 8px; color: var(--muted-2); letter-spacing: 0.12em; margin-top: 8px; border-top: 1px solid rgba(255,255,255,.06); padding-top: 7px; }
#fear-label { color: var(--mint); }
.injury-chips { display: flex; flex-wrap: wrap; gap: 4px; margin-top: 6px; }
.injury-chip { font-size: 7.5px; letter-spacing: 0.1em; color: #ffb1a2; border: 1px solid rgba(255, 111, 94, 0.35); background: rgba(255, 78, 62, 0.09); padding: 2px 6px; border-radius: 2px; }
.hazard { font-size: 8px; letter-spacing: 0.08em; color: #ffce7a; margin-top: 6px; }

.top-actions { position: absolute; right: 20px; top: 102px; display: flex; gap: 6px; }
.icon-btn { background: linear-gradient(150deg, rgba(17, 40, 32, .72), rgba(6, 18, 14, .62)); border: 1px solid var(--line); border-radius: 4px; padding: 7px 9px 6px; font-size: 7px; letter-spacing: 0.11em; color: var(--muted); cursor: pointer; display: flex; flex-direction: column; align-items: center; gap: 3px; min-width: 48px; transition: all .18s; backdrop-filter: blur(12px); }
.icon-btn span { font-size: 15px; color: var(--mint); line-height: 1; }
.icon-btn:hover { border-color: var(--mint); color: var(--ink); background: rgba(31, 68, 53, 0.75); }
.icon-btn:active { transform: scale(.96); }

.target-panel { position: absolute; right: 20px; top: 172px; width: 246px; border-radius: 6px; padding: 12px 14px; }
.target-head { display: flex; justify-content: space-between; font-family: var(--display); font-size: 14px; font-weight: 700; letter-spacing: .02em; }
.target-head button { background: none; border: none; color: var(--muted); font-size: 16px; cursor: pointer; }
.target-sub { font-size: 9px; color: var(--muted); margin-top: 2px; }
.target-fear { font-size: 8px; letter-spacing: .18em; margin: 9px 0 5px; color: var(--mint); font-weight: 800; }
.target-bars > div { display: flex; align-items: center; gap: 6px; margin-bottom: 4px; font-size: 7px; color: var(--muted-2); letter-spacing: .1em; }
.mini-bar { flex: 1; height: 4px; background: rgba(255,255,255,.1); overflow: hidden; }
.mini-bar i { display: block; height: 100%; width: 100%; background: var(--red); transition: width .25s; }
.mini-bar.fear i { background: var(--amber); }
.target-meta { font-size: 8.5px; color: var(--muted-2); margin: 6px 0 8px; line-height: 1.5; }
.target-actions { display: flex; gap: 6px; }
.mini-btn { flex: 1; font-size: 8px; letter-spacing: .12em; padding: 6px; background: rgba(255,255,255,.05); border: 1px solid var(--line); cursor: pointer; color: var(--ink); }
.mini-btn:hover { border-color: var(--mint); }
.mini-btn.danger { color: #ffb1a2; border-color: rgba(255,111,94,.3); }
.mini-btn.danger:hover { background: rgba(255,111,94,.15); }

.minimap-wrap { position: absolute; left: 20px; bottom: 26px; width: 174px; height: 174px; border-radius: 50%; overflow: hidden; padding: 0; }
#minimap { width: 100%; height: 100%; opacity: .92; }
.minimap-ring { position: absolute; inset: 5px; border-radius: 50%; border: 1px solid rgba(163,255,214,.2); pointer-events: none; }
.compass { position: absolute; top: 5px; left: 50%; transform: translateX(-50%); font-size: 7px; letter-spacing: .12em; color: var(--mint); background: rgba(3,12,8,.7); padding: 1px 5px; border-radius: 9px; }
.minimap-label { position: absolute; bottom: 23px; left: 0; right: 0; text-align: center; font-size: 7px; letter-spacing: .2em; color: #dff9ea; text-shadow: 0 1px 8px #000; }

.context-prompt { position: absolute; left: 50%; bottom: 128px; transform: translateX(-50%); background: rgba(5, 17, 12, .8); border: 1px solid var(--line-strong); border-radius: 3px; padding: 8px 14px; font-size: 10px; letter-spacing: .08em; display: flex; align-items: center; gap: 9px; backdrop-filter: blur(10px); animation: promptIn .2s ease; }
@keyframes promptIn { from { opacity: 0; transform: translate(-50%, 5px); } }
.key { font-size: 8px; font-weight: 800; background: var(--mint); color: #05110c; padding: 3px 5px; border-radius: 2px; letter-spacing: .06em; }
.action-bar { position: absolute; left: 50%; bottom: 26px; transform: translateX(-50%); display: flex; gap: 6px; background: linear-gradient(160deg, rgba(13,33,26,.78), rgba(4,14,10,.72)); border: 1px solid var(--line); border-radius: 6px; padding: 8px; backdrop-filter: blur(14px); pointer-events: auto; }
.action { width: 62px; height: 62px; border-radius: 4px; border: 1px solid rgba(163,255,214,.1); background: rgba(255,255,255,.025); position: relative; cursor: pointer; display: flex; flex-direction: column; align-items: center; justify-content: center; transition: all .15s; overflow: hidden; }
.action:hover { border-color: var(--mint); background: rgba(80, 230, 170, .12); }
.action:active { transform: scale(.95); }
.action-key { position: absolute; top: 3px; left: 5px; font-size: 6.5px; color: var(--muted-2); letter-spacing: .05em; }
.action-icon { font-size: 18px; color: var(--mint); line-height: 1; }
.action-name { font-size: 7px; letter-spacing: .1em; color: var(--muted); margin-top: 4px; text-transform: uppercase; }
.action.disabled { opacity: .4; }
.action .cooldown { position: absolute; bottom: 0; left: 0; width: 100%; height: 0%; background: rgba(3, 10, 7, .65); pointer-events: none; }
.control-hint { position: absolute; right: 20px; bottom: 28px; font-size: 7.5px; letter-spacing: .1em; color: rgba(213, 238, 224, .4); text-align: right; }
.control-hint b { color: rgba(213, 238, 224, .7); font-weight: 600; }

#nearby-tags { position: absolute; inset: 0; pointer-events: none; overflow: hidden; }
.nameplate { position: absolute; transform: translate(-50%, -100%); text-align: center; transition: opacity .2s; will-change: left, top; }
.nameplate .np-name { font-size: 8px; letter-spacing: .1em; color: #e2f5e9; text-shadow: 0 1px 6px #000; background: rgba(3, 12, 8, .45); padding: 2px 5px; border-radius: 2px; white-space: nowrap; }
.nameplate .np-bar { width: 52px; height: 3px; margin: 3px auto 0; background: rgba(0,0,0,.55); }
.nameplate .np-bar i { display: block; height: 100%; background: var(--red); }
.nameplate .np-fear { font-size: 8px; margin-top: 1px; text-shadow: 0 1px 4px #000; }

#toasts { position: absolute; right: 20px; top: 50%; width: 280px; display: flex; flex-direction: column; gap: 6px; align-items: flex-end; pointer-events: none; }
.toast { background: rgba(7, 22, 16, .85); border-left: 2px solid var(--mint); color: #dff6ea; font-size: 10px; line-height: 1.35; padding: 8px 12px; letter-spacing: .03em; width: 100%; animation: toastIn .35s cubic-bezier(.16,1,.3,1); backdrop-filter: blur(10px); box-shadow: 0 6px 20px rgba(0,0,0,.35); }
.toast.danger { border-color: var(--red); color: #ffd9d3; }
.toast.kill { border-color: var(--amber); }
.toast.discovery { border-color: var(--violet); }
.toast.birth { border-color: #8fd7ff; }
@keyframes toastIn { from { opacity: 0; transform: translateX(20px); } }
.toast.out { animation: toastOut .4s forwards; }
@keyframes toastOut { to { opacity: 0; transform: translateX(25px); } }

#damage-numbers { position: absolute; inset: 0; pointer-events: none; overflow: hidden; }
.damage-num { position: absolute; transform: translate(-50%, -50%); font-family: var(--display); font-weight: 800; font-size: 16px; color: #ffcf9e; text-shadow: 0 2px 8px #000, 0 0 16px rgba(255, 90, 60, .5); animation: dmgFloat .9s ease-out forwards; }
@keyframes dmgFloat { from { opacity: 1; transform: translate(-50%, -50%) scale(.7); } 20% { transform: translate(-50%, -80%) scale(1.08); } to { opacity: 0; transform: translate(-50%, -170%) scale(.9); } }

#selection-reticle { position: absolute; width: 54px; height: 54px; border: 1px solid rgba(255, 235, 160, .55); border-radius: 50%; transform: translate(-50%, -50%); pointer-events: none; box-shadow: 0 0 18px rgba(255,230,140,.15), inset 0 0 14px rgba(255,230,140,.1); animation: reticlePulse 2s ease-in-out infinite; }
#selection-reticle::before, #selection-reticle::after { content: ""; position: absolute; background: rgba(255, 235, 160, .5); }
#selection-reticle::before { width: 7px; height: 1px; left: -9px; top: 50%; box-shadow: 60px 0 0 rgba(255,235,160,.5); }
#selection-reticle::after { width: 1px; height: 7px; top: -9px; left: 50%; box-shadow: 0 60px 0 rgba(255,235,160,.5); }
@keyframes reticlePulse { 50% { transform: translate(-50%, -50%) scale(1.08); opacity: .7; } }

#joystick { position: absolute; left: 30px; bottom: 140px; width: 110px; height: 110px; border-radius: 50%; border: 1px solid rgba(163,255,214,.25); background: rgba(4, 16, 11, .35); pointer-events: none; z-index: 26; }
#joystick-knob { position: absolute; left: 50%; top: 50%; width: 44px; height: 44px; margin: -22px 0 0 -22px; border-radius: 50%; background: rgba(125,243,188,.25); border: 1px solid rgba(125,243,188,.55); backdrop-filter: blur(5px); }
.mobile-actions { display: none; position: absolute; right: 20px; bottom: 120px; grid-template-columns: repeat(2, 54px); gap: 8px; pointer-events: auto; z-index: 26; }
.mob-btn { width: 54px; height: 54px; border-radius: 50%; border: 1px solid rgba(163,255,214,.28); background: rgba(5, 20, 14, .6); backdrop-filter: blur(10px); font-size: 19px; color: var(--mint); }
.mob-btn:active { background: rgba(125,243,188,.25); transform: scale(.92); }

/* ============ CELL HUD ============ */
#cell-hud { position: absolute; inset: 0; z-index: 22; pointer-events: none; }
#cell-hud button { pointer-events: auto; }
.cell-top { position: absolute; left: 24px; top: 24px; padding: 14px 20px; border-radius: 5px; }
.cell-stage { font-size: 8px; letter-spacing: .28em; color: var(--mint); font-weight: 700; }
.cell-stage b { color: var(--amber); }
.cell-name { font-family: var(--display); font-size: 22px; letter-spacing: .04em; margin-top: 4px; text-transform: uppercase; }
.cell-sub { font-size: 9.5px; color: var(--muted); margin-top: 2px; }
.cell-stats { position: absolute; left: 24px; bottom: 46px; width: 300px; padding: 14px; display: flex; gap: 16px; align-items: center; border-radius: 6px; }
.cell-ring-wrap { position: relative; width: 88px; height: 88px; flex: none; }
.cell-ring { width: 100%; height: 100%; transform: rotate(-90deg); }
.ring-bg { fill: none; stroke: rgba(255,255,255,.1); stroke-width: 4; }
.ring-fill { fill: none; stroke: var(--mint); stroke-width: 4; stroke-dasharray: 264; stroke-dashoffset: 264; stroke-linecap: round; filter: drop-shadow(0 0 5px rgba(125,243,188,.7)); transition: stroke-dashoffset .4s ease; }
.cell-ring-text { position: absolute; inset: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; }
.cell-ring-text b { font-family: var(--display); font-size: 26px; line-height: 1; color: var(--mint); }
.cell-ring-text span { font-size: 8px; color: var(--muted); margin-top: 2px; }
.cell-details { flex: 1; display: flex; flex-direction: column; gap: 8px; }
.cell-row { display: flex; justify-content: space-between; align-items: center; font-size: 8px; letter-spacing: .12em; color: var(--muted); gap: 8px; }
.cell-row b { color: var(--ink); font-size: 11px; }
.cell-row .mini-bar { max-width: 120px; }
.cell-row .mini-bar i { background: linear-gradient(90deg, #ff8b7e, #ff5a52); }
.cell-objective { position: absolute; left: 50%; transform: translateX(-50%); bottom: 46px; width: 440px; padding: 14px 18px; border-radius: 6px; text-align: center; font-size: 11px; color: #d5e9dd; line-height: 1.5; }
.eyebrow-mini { display: block; font-size: 7.5px; letter-spacing: .24em; color: var(--amber); font-weight: 700; margin-bottom: 4px; }
.cell-objective b { color: var(--mint); }
.cell-tip { font-size: 8px; color: var(--muted-2); letter-spacing: .12em; margin-top: 6px; }
.evolve-btn { position: absolute; left: 50%; bottom: 145px; transform: translateX(-50%); animation: evolveGlow 1.8s ease-in-out infinite; }
@keyframes evolveGlow { 50% { box-shadow: 0 0 55px rgba(73,231,164,.6); } }
.cell-bottom-hint { position: absolute; right: 24px; bottom: 30px; font-size: 8px; letter-spacing: .18em; color: rgba(200,240,220,.4); }
.cell-bottom-hint span { margin: 0 6px; }
.cell-exit { position: absolute; right: 24px; top: 24px; background: rgba(4,14,10,.5); border: 1px solid var(--line); padding: 8px 12px; font-size: 8px; letter-spacing: .14em; color: var(--muted); cursor: pointer; }

/* ============ MODAL ============ */
#modal-overlay { position: absolute; inset: 0; z-index: 70; background: rgba(2, 8, 6, .7); backdrop-filter: blur(7px); display: flex; align-items: center; justify-content: center; padding: 24px; animation: fadeIn .2s ease; }
@keyframes fadeIn { from { opacity: 0; } }
.modal-panel { width: min(960px, 96vw); max-height: 88vh; background: linear-gradient(160deg, rgba(10, 28, 21, .97), rgba(4, 13, 9, .98)); border: 1px solid var(--line-strong); border-radius: 6px; display: flex; flex-direction: column; box-shadow: 0 40px 120px rgba(0,0,0,.7); animation: modalIn .3s cubic-bezier(.16,1,.3,1); }
.modal-panel.wide { width: min(1180px, 97vw); }
@keyframes modalIn { from { opacity: 0; transform: translateY(18px) scale(.985); } }
.modal-head { display: flex; justify-content: space-between; align-items: flex-start; padding: 22px 26px 16px; border-bottom: 1px solid var(--line); flex: none; }
.modal-kicker { font-size: 8px; letter-spacing: .3em; color: var(--mint); font-weight: 700; }
.modal-head h2 { margin: 5px 0 0; font-family: var(--display); font-size: 28px; font-weight: 700; letter-spacing: .02em; text-transform: uppercase; }
#modal-close { background: none; border: 1px solid var(--line); border-radius: 3px; width: 34px; height: 34px; font-size: 20px; color: var(--muted); cursor: pointer; line-height: 1; }
#modal-close:hover { border-color: var(--mint); color: var(--ink); }
.modal-body { padding: 22px 26px 28px; overflow-y: auto; scrollbar-width: thin; scrollbar-color: var(--mint-dim) transparent; }
.modal-body::-webkit-scrollbar { width: 6px; }
.modal-body::-webkit-scrollbar-thumb { background: var(--mint-dim); }

.section-label { font-size: 8px; letter-spacing: .26em; color: var(--amber); font-weight: 700; margin: 22px 0 10px; display: flex; align-items: center; gap: 10px; }
.section-label:first-child { margin-top: 0; }
.section-label::after { content: ""; flex: 1; height: 1px; background: var(--line); }
.muted { color: var(--muted); }
.tiny { font-size: 9px; color: var(--muted-2); letter-spacing: .04em; line-height: 1.6; }
.pill { display: inline-block; font-size: 8px; letter-spacing: .12em; padding: 3px 8px; border: 1px solid var(--line); border-radius: 20px; color: var(--muted); }
.pill.green { color: var(--mint); border-color: rgba(125,243,188,.3); background: rgba(125,243,188,.07); }
.pill.amber { color: var(--amber); border-color: rgba(255,209,112,.3); background: rgba(255,209,112,.07); }
.pill.red { color: #ff9d8f; border-color: rgba(255,111,94,.3); background: rgba(255,111,94,.07); }

/* codex */
.codex-layout { display: grid; grid-template-columns: 300px 1fr; gap: 24px; }
.codex-list { display: flex; flex-direction: column; gap: 6px; max-height: 58vh; overflow-y: auto; padding-right: 4px; }
.codex-item { display: flex; align-items: center; gap: 10px; padding: 8px 10px; border: 1px solid transparent; border-radius: 3px; cursor: pointer; transition: all .15s; background: rgba(255,255,255,.02); }
.codex-item:hover { background: rgba(125,243,188,.06); }
