import { fearInfo, FEAR_LEVELS } from './ecosystem.js';

const $ = (sel) => document.querySelector(sel);
const $$ = (sel) => Array.from(document.querySelectorAll(sel));
const pct = (v) => `${clamp(v, 0, 100)}%`;

const SLIDER_GROUPS = [
